WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[41467] = { title = "The Only Choice We Can Make", description = "Take this torch, {name}. \n\nWe cannot reverse the Nightmare corruption once it has taken hold. All we can hope to do is destroy its manifestations.\n\nIncinerate the root. Only then can we rest easy in Suramar.", objectives = "" }
WordHunterWoW_QuestEN[41468] = { title = "Mistress of the Claw", description = "The great forest guardian, Ursoc, gave his life for this world ten thousand years ago. After the guardian's death his claws were hidden away, safe from any who would use their power for evil.\n\nLea Stonepaw and her Druids of the Claw consider Ursoc their paragon and dedicate their lives to following in his example. If anyone would know where the claws reside, it would be Lea.\n\nShe and her Druids of the Claw reside in the Tel'Andu Barrow Den just to the north.", objectives = "" }
WordHunterWoW_QuestEN[41469] = { title = "Return to Irongrove Retreat", description = "We have three blessings from the creatures we share this land with.\n\nCombined with a blessing from Elune, the moonwell will watch over this land for years to come.\n\nMeet Mythandros at the retreat. I am sure he would like to include you in the ritual.", objectives = "" }
WordHunterWoW_QuestEN[41473] = { title = "Redhoof the Ancient", description = "While you were busy assisting the Owlcats across the river, Mythandros and Solendra ventured further to the east.\n\nI believe Mythandros may have found the next creature that may offer us its blessing.\n\nThere is a secluded glade along the river's bend to the Northeast. There you may find our new ally, an elderly stag named Redhoof.", objectives = "" }
WordHunterWoW_QuestEN[41474] = { title = "Fertilizing the Future", description = "Like most herbivores, our antlered friends will eat anything green enough to chew. \n\nHowever I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food.\n\nI will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.", objectives = "" }
WordHunterWoW_QuestEN[41475] = { title = "Prongs and Fangs", description = "Now, {name}, do not mistake me- I am a druid. I understand that nature has a balance.\n\nPredators must feed, and others will be hunted. I also understand that tampering with such balance has consequences.\n\nThat is why I have taken upon myself to walk this land and perform some... ah... calculations.\n\nSlay only a small number of the wolves you find, and one alpha. That should reduce their number enough to allow the Sablehorn to thrive without disrupting the flow of things here.", objectives = "" }
WordHunterWoW_QuestEN[41478] = { title = "The Final Blessing", description = "My friend Solendra Featherdown went to explore the habitat of the native Nightsabers. \n\nNow that we have the blessings of the Feathermane and the Sablehorn it is time to seek the blessing of the Nightsabers. She is just on the other side of this glade, to the North.", objectives = "" }
WordHunterWoW_QuestEN[41479] = { title = "Natural Adversaries", description = "I have walked this land in the time since our arrival. Here, basilisks have emerged from the ravines to the east. They encroach upon the home of the Nightsabers.\n\nTo earn their blessing, I believe we should clear the way for their return.\n\nSlay the basilisks that have taken more than their fair share of the land, {race}.", objectives = "" }
WordHunterWoW_QuestEN[41480] = { title = "Managazer", description = "There is one basilisk here who has gorged himself so thoroughly on Nightsaber flesh that he seldom leaves his cave.\n\nWe will use this to our advantage.\n\nSeek out the basilisk Managazer and use his death as an example to the others who have strayed from their home.", objectives = "" }
WordHunterWoW_QuestEN[41485] = { title = "Moonwhisper Rescue", description = "As a druid I understand that predation happens. Creatures that eat meat must acquire meat.\n\nBut this...\n\n<Solendra gestures angrily toward a nearby petrified nightsaber.>\n\nThis is just sad. Free them, {race}. Take my blessing and free them from this needless torment.", objectives = "" }
WordHunterWoW_QuestEN[41494] = { title = "Eminent Grow-main", description = "You have done very well, {race}. \n\nAll that is left is to combine their blessings into the ritual bundle and imbue the Moonwell. Once that is done, Mayruna will add a little water from a purified Moonwell and this land will be protected so long as we inhabit it.\n\nThis is a momentous occasion, my friend. You bear witness to a sacred rite not often performed in the company of strangers.\n\nI will let you do the honors- simply place the ritual bundle into the sacred waters and we will do the rest.", objectives = "" }
WordHunterWoW_QuestEN[41499] = { title = "Squid Out of Water", description = "Toryl told me about those squid creatures that are controlling my brothers.\n\nI have never seen anything like them before around Jandvik. The naga must have brought them from wherever they came.\n\nI do not want any more of my kin to suffer the fate of being controlled by the naga.\n\nFind out where those squids come from and stop them.", objectives = "" }
WordHunterWoW_QuestEN[41510] = { title = "Azeroth Needs You", description = "We shaman under your command will aid your efforts against the Legion. You may direct our actions from here.\n\nSeek out Advisor Sevel just to the south and locate the scouting map from which you can direct your followers. We will also indicate on the scouting map various hot-spots around the Broken Isles that require your attention.\n\nAzeroth needs you, Farseer! Visit the scouting map and choose our first point of attack.", objectives = "" }
WordHunterWoW_QuestEN[41540] = { title = "Rendezvous with the Courier", description = "Thas'dorah is a mighty bow indeed! The weapon was carved from a limb of Thas'alah, the mother tree of Eversong, and infused with the magic of the Sunwell. I fought alongside its first wielder, Talanas Windrunner, during an Amani troll incursion.\n\nAh, but such tales can wait for another time.\n\nCourier Larkspear was making preparations to depart. You can meet him at Krasus' Landing.", objectives = "" }
WordHunterWoW_QuestEN[41541] = { title = "A Beastly Expedition", description = "I know the power of Titanstrike well. The Unseen Path battled the vrykul warlord Volund as he campaigned to conquer the Broken Isles. We sought to wrest the rifle from him, but he took it to his grave.\n\nIf Volund's tomb can at last be opened, the artifact would be a great boon to our cause.\n\nI believe Grif Wildheart is making preparations to depart. You can meet him at Krasus' Landing.", objectives = "" }
WordHunterWoW_QuestEN[41542] = { title = "Preparation for the Hunt", description = "Talonclaw is a mighty spear indeed! I first set eyes upon it when the Highmountain tauren led the members of my order up to Talon Peak to found the Trueshot Lodge.\n\nBut such tales must wait for another time.\n\nApata has been in Dalaran gathering supplies for her expedition. I imagine she's ready to depart by now.\n\nSeek her out at Krasus' Landing. I know she will be eager to begin.", objectives = "" }
WordHunterWoW_QuestEN[41574] = { title = "Stolen Thunder", description = "Titanstrike is in the tomb of Warlord Volund somewhere on the isle of Shield's Rest. It's a dank, sloppy mess adrift in a sea of gloom.\n\nSounds lovely, eh?\n\nI've been workin' with a vrykul guide named Prustaga. She'll help us break the wards keepin' the tomb sealed.\n\nI know what you're thinkin'... vrykul are trouble. But she hasn't taken a swing at me just yet.\n\nHuey'll take us down to the shore. Prustaga's probably found the tomb by now!", objectives = "" }
WordHunterWoW_QuestEN[41575] = { title = "Felsoul Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "" }
WordHunterWoW_QuestEN[41606] = { title = "Finding Brytag", description = "<Kell barely manages to speak.>\n\nThat naga witch... has given many of my kin... to the sea giants.\n\nBrytag was... the last one I saw alive.\n\nFind him quickly.", objectives = "" }
WordHunterWoW_QuestEN[41607] = { title = "Taking a Promenade", description = "We must learn much about our long-lost kin if we are to fight them.\n\nWe dispatched one of our scouts to infiltrate the Promenade and gather intelligence. The Sentinels sent their own scout as well, hopefully she is smart enough to not get herself killed before reporting in.\n\nThey have not returned in some time, and we must suspect the worst.\n\nFind them and we shall see what we are up against.", objectives = "" }
WordHunterWoW_QuestEN[41618] = { title = "The Seawarden", description = "The Seawarden made a deal with the Tidemistress. She handed us over to him like cattle.\n\nI despise that sea giant! If I were not trapped in this bubble, I would choke the life out of him with my own two hands.\n\nIf you cross his path before I get out of here, make him regret ever making a deal with the naga!", objectives = "" }
WordHunterWoW_QuestEN[41625] = { title = "The Light's Wrath", description = "Light's Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause.\n\nRetrieving it won't be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.\n\nThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", objectives = "" }
WordHunterWoW_QuestEN[41626] = { title = "A New Threat", description = "If you seek the Nexus, I would warn not to rush headlong. There are strange happenings in Coldarra, and it would be best to gather some information before proceeding.\n\nDuring my last visit to the Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was very closely tied to Malygos' plans during the Nexus Wars, whatever is present there may explain the current state of the Nexus.\n\nI cannot accompany you, but this crystal can be used to communicate with me. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[41627] = { title = "A Forgotten Enemy", description = "The device still hums with power. It must have been abandoned not long ago.\n\nThe nearby switch appears to activate it.", objectives = "" }
WordHunterWoW_QuestEN[41628] = { title = "Eyes of the Dragon", description = "You should travel at once to Coldarra in Borean Tundra, {name}. There, I would recommend you scout out a few key locations and report back to me. \n\nI know the area well, and should be able to tell you how to proceed.\n\nMake haste!", objectives = "" }
WordHunterWoW_QuestEN[41629] = { title = "Harnessing the Holy Fire", description = "The energy from Light's Wrath lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.\n\nIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", objectives = "" }
WordHunterWoW_QuestEN[41630] = { title = "Unleashing Judgment", description = "You have the power you need to destroy the Surge Needles. \n\nAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Light's Wrath into these points of focused void, and the reaction should cause an overload, destroying the Surge Needle above.\n\nYou must act quickly. The Ethereum likely won't sit idly by as you lay waste to their machinations.", objectives = "" }
WordHunterWoW_QuestEN[41631] = { title = "The Nexus Vault", description = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. \n\nWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Light's Wrath, I would ask that you also free my brother from their grip.\n\nWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, {name}.", objectives = "" }
WordHunterWoW_QuestEN[41632] = { title = "A Gift of Time", description = "You have done a great thing for the blue dragons today, {name}, as well as for my own peace of mind.\n\nNow, armed with Light's Wrath, I only ask that you fulfill your original goal, and take the fight to the Legion.\n\nI believe Alonsus Faol awaits your return. Safe travels, friend.", objectives = "" }
WordHunterWoW_QuestEN[41684] = { title = "The Necrodark", description = "Things are worse than I expected.\n\nWe might be in trouble, {name}. With this place all but taken over by the Necrodark, they might have already unleashed the Grey One.", objectives = "" }
WordHunterWoW_QuestEN[41689] = { title = "Cleansing the Mother Tree", description = "We must save the Mother Tree at all costs.\n\nI believe I know a way.\n\nThe world tree Nordrassil, atop Mount Hyjal, was born from an acorn of G'Hanir. We can use the sacred waters surrounding its roots to purify the corruption.\n\nIf we take the Dreamway to Mount Hyjal's summit we should have enough time to complete the cleansing ritual before G'Hanir falls completely to the darkness.", objectives = "" }
WordHunterWoW_QuestEN[41690] = { title = "Reconvene", description = "You found Lyessa in the Dream, didn't you, Shan'do {name}? I heard you mutter her name in your slumber.\n\nThank Elune she is well.\n\nYou must seek her out - I can sense her presence even now at the Circle of Spirits above.\n\nIf ever there were one who could help us cleanse G'Hanir, it is Lyessa.", objectives = "" }
WordHunterWoW_QuestEN[41702] = { title = "Written in Stone", description = "<You bundle the notes and store them away in your pack.\n\nAccording to his final journal entry, Kel'danath used something called a \"spellstone\" in his experiments.\n\nThe spellstone, if not the arcanist himself, must be nearby.>", objectives = "" }
WordHunterWoW_QuestEN[41704] = { title = "Subject 16", description = "<It seems Theryn is still under the arcanist's spell. In the absence of Kel'danath himself, a live subject could be useful in helping Thalyssra unravel his research.>", objectives = "" }
WordHunterWoW_QuestEN[41707] = { title = "Wormtalon Wreckage", description = "As if Shaladrassil's encroaching roots were not enough to deal with, now the Wormtalon harpies have come to take advantage of our plight. \n\nKill them, {race}. They deserve nothing less for feeding on our misery.", objectives = "" }
WordHunterWoW_QuestEN[41708] = { title = "Dark Side of the Moon", description = "Xavius led Ysera past here, but their destination is unclear. This twisted wickedness smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins of their home. If it somehow resisted this corruption...\n\nI will beg of Elune a vision to give me direction. With her light, I may find my husband yet.", objectives = "" }
WordHunterWoW_QuestEN[41709] = { title = "Breaking Down the Big Guns", description = "You did well against that sea witch, but not well enough.\n\nHer power far surpasses any creature that I have ever fought. To defeat her, we will need something formidable. Something that she will not expect...\n\n<Toryl grins wryly.>\n\nSomething of their own design... \n\nSalvage as many parts from their harpoon launchers as you can carry and meet me back in Jandvik.", objectives = "" }
WordHunterWoW_QuestEN[41724] = { title = "Heart of the Nightmare", description = "I know only that my husband is somewhere deeper in this twisted forest. He is still alive, but it remains to be seen if he is whole.\n\n<Tyrande's expression hardens into a scowl.>\n\nElune herself cannot protect Xavius if he is not.", objectives = "" }
WordHunterWoW_QuestEN[41728] = { title = "The Defense of Tian Monastery", description = "Chen's recent report indicates that Tian Monastery is under attack!\n\n{name}, they need your help. Go speak to Tak-Tak west of the main temple. He can get you there quickly.", objectives = "" }
WordHunterWoW_QuestEN[41729] = { title = "Slowing the Spread", description = "Reinforcements. Just what we needed! Grandmaster, the monastery is under attack.\n\nThe Legion is using a foul device known as a Fel Spreader to scorch the very earth we walk on with disgusting fel energy.\n\nDestroy those machines, and we can slow their efforts.", objectives = "" }
WordHunterWoW_QuestEN[41730] = { title = "Desperate Strike", description = "Good, your timing couldn't have been better, {name}.\n\nThese foul Legion creatures have invaded our sanctuary. They have no place here on our world.\n\nKill every demon you see, brother.", objectives = "" }
WordHunterWoW_QuestEN[41731] = { title = "Storm, Earth, and Fire", description = "Tian Monastery is in bad shape.\n\nFelspreader imps are torching the grounds. Fel spikes radiate foul energy, corrupting the nearby earth. And fel magic has seeped into the monastery's ale barrels, tainting the brew.\n\nUse your abilities to snuff the flames, shatter the spikes, and destroy the tainted barrels.\n\nSigh... hundreds of years of the finest ale... ruined.\n\nI don't wish to hear any more of it. Just get it done.", objectives = "" }
WordHunterWoW_QuestEN[41732] = { title = "The Hand of Keletress", description = "The demons' leader is up ahead, taking prisoners it is said!\n\nThis dire storm, we will weather... if we fight her together!", objectives = "" }
WordHunterWoW_QuestEN[41733] = { title = "Rebuilding the Order", description = "On behalf of all the students and teachers here at Tian Monastery, thank you, Grandmaster {name}.\n\nYou have a difficult task ahead of you to rebuild our order, but we stand with you.\n\nLet us head back to the Wandering Isle.", objectives = "" }
WordHunterWoW_QuestEN[41734] = { title = "Champion: Taran Zhu", description = "", objectives = "" }
WordHunterWoW_QuestEN[41735] = { title = "Champion: The Monkey King", description = "", objectives = "" }
WordHunterWoW_QuestEN[41736] = { title = "Champion: Angus Ironfist", description = "", objectives = "" }
WordHunterWoW_QuestEN[41737] = { title = "Champion: Hiro", description = "", objectives = "" }
WordHunterWoW_QuestEN[41738] = { title = "Champion: Sylara Steelsong", description = "", objectives = "" }
WordHunterWoW_QuestEN[41739] = { title = "Champion: Aegira", description = "", objectives = "" }
WordHunterWoW_QuestEN[41740] = { title = "Tech It Up A Notch", description = "There are many ways to commune with the elements. In their ingenuity, the goblins have found ways to imbue their mechanical devices with the energy of elemental spirits. I do not pretend to understand. But in our hour of need, we should not hesitate to embrace a diversity of options.\n\nWe are fortunate to have at our disposal the services of the one they call \"Goldmine,\" whose unorthodox research may significantly augment our power. He waits nearby.", objectives = "" }
WordHunterWoW_QuestEN[41741] = { title = "Troops in the Field", description = "It is time for us to test the strength of your newly summoned Lesser Elementals. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", objectives = "" }
WordHunterWoW_QuestEN[41742] = { title = "Champion: Celestos", description = "", objectives = "" }
WordHunterWoW_QuestEN[41743] = { title = "Champion: Nobundo", description = "", objectives = "" }
WordHunterWoW_QuestEN[41744] = { title = "Champion: Rehgar Earthfury", description = "", objectives = "" }
WordHunterWoW_QuestEN[41745] = { title = "Champion: Scaldius", description = "", objectives = "" }
WordHunterWoW_QuestEN[41746] = { title = "Champion: Muln Earthfury", description = "", objectives = "" }
WordHunterWoW_QuestEN[41747] = { title = "Champion: Avalanchion", description = "", objectives = "" }
WordHunterWoW_QuestEN[41748] = { title = "Champion: Ritssyn Flamescowl", description = "", objectives = "" }
WordHunterWoW_QuestEN[41749] = { title = "Given to Corruption", description = "A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.\n\nAs with all who suffer this fate, there is no restoring him.\n\nPlease, {name}, bring him peace.", objectives = "" }
WordHunterWoW_QuestEN[41750] = { title = "Champion: Calydus", description = "", objectives = "" }
WordHunterWoW_QuestEN[41751] = { title = "Champion: Kira Iresoul", description = "", objectives = "" }
WordHunterWoW_QuestEN[41752] = { title = "Champion: Zinnin Smythe", description = "", objectives = "" }
WordHunterWoW_QuestEN[41753] = { title = "Champion: Jubeka Shadowbreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[41754] = { title = "Champion: Shinfel Blightsworn", description = "", objectives = "" }
WordHunterWoW_QuestEN[41755] = { title = "Champion: Lulubelle Fizzlebang", description = "", objectives = "" }
WordHunterWoW_QuestEN[41756] = { title = "Champion: Eredar Twins", description = "", objectives = "" }
WordHunterWoW_QuestEN[41759] = { title = "An Unlikely Ally", description = "Channeling the demonic gateway will require the assistance of someone with intimate knowledge of the Burning Legion.\n\nI know of such a warlock, though I imagine her blood still boils upon hearing my name. It might be best if you are the one to request her help.", objectives = "" }
WordHunterWoW_QuestEN[41760] = { title = "Kel'danath's Legacy", description = "Kel'danath discovered something incredible - the power to subdue and even control the withered.\n\nI will pick up where my old friend left off. We shall see to it that he did not die in vain. \n\nPerhaps in the end we can even find peace for the wretches who have been left to a fate worse than death.\n\nI will need more subjects. Take Kel'danath's spellstone and use it to subdue more withered.", objectives = "" }
WordHunterWoW_QuestEN[41762] = { title = "Sympathizers Among the Shal'dorei", description = "Elisande's decision to welcome the Legion into Suramar earned her plenty of enemies, though only some of us were bold enough to openly defy her.\n\nWe have allies in the city - we just don't know how many.\n\nI need you to make contact with a spell-fencer by the name of Silgryn. He is loyal to our cause, and has been lying in wait since our failed coup.\n\nHe patrols the western edge of the city. Address him by name and tell him our cause is not lost!", objectives = "" }
WordHunterWoW_QuestEN[41763] = { title = "Close Enough to Touch", description = "He is near, {race}, I can feel it.\n\nWe must search Shala'nir for Malfurion. If we do not find him soon, I fear he will be lost to me forever.\n\nI was unsure of your worth when first we met. I know now that you will not fail me.\n\nI am... grateful.", objectives = "" }
WordHunterWoW_QuestEN[41764] = { title = "Walking in Their Footsteps", description = "Spiritwalkers maintain balance between the world of the living and the spirit realm. We can travel into the memories of the dead to glean clues about the past.\n\nThe wards Ebonhorn maintained were placed long ago by heroes who fought the darkness. By walking in their footsteps, we may locate the wards and restore them.\n\nIgrul, the drogbar known as the Scalebane, was a true friend to Huln Highmountain. Use the Water of Vision to enter his memories and find where he placed the first ward.", objectives = "" }
WordHunterWoW_QuestEN[41767] = { title = "A Daring Rescue", description = "The plan is a simple one, but it will require great effort on your part.\n\nKira and I will summon the demonic gateway, but you will have to enter alone and recover the missing council members.", objectives = "" }
WordHunterWoW_QuestEN[41768] = { title = "Soul Beacon", description = "I have bound Shinfel's soul to her staff, allowing it to serve as an anchor in this world.\n\nWhen we perform the ritual of summoning, it will act as a beacon, guiding Shinfel through the Twisting Nether and back to our world.", objectives = "" }
WordHunterWoW_QuestEN[41769] = { title = "Mad Ernie the Alchemist", description = "If we have any hope of curing this curse, we need to know what kind of magic we're dealing with.\n\nI know of an alchemist who earned himself quite the reputation for his unconventional methods. Shunned from Gilneas long ago, I believe Mad Ernie has taken up residence in these lands.\n\nHis knowledge may be the first step to breaking this curse.", objectives = "" }
WordHunterWoW_QuestEN[41770] = { title = "The Skies Above", description = "There has been no Windlord to lead the air elementals since the death of Al'Akir.\n\nThe realm of Skywall has been thrown into turmoil. The throne of Al'Akir is Thunderaan's by right, but what remains of the prince's essence within Thunderfury is diminishing. If we do not move quickly, Thunderaan may be lost forever.\n\nTake the damaged Thunderfury to Vortex Pinnacle and speak with Celestos.\n\nCelestos was a loyal servant of Al'Akir and he will share our desire to see Thunderaan reborn.", objectives = "" }
WordHunterWoW_QuestEN[41771] = { title = "Recharging the Blade", description = "You have recovered the Blessed Blade of the Windseeker, and with it you hold all that is left of the soul of Prince Thunderaan.\n\nThunderfury can be restored, but it will require a rare essence known as the Heart of Skywall.\n\nVortos, the Duke of the East Winds, possesses the heart... but he will not give it willingly.\n\nVortos must be defeated, and the Heart of Skywall must be combined with the blade.\n\nOnly then can Thunderaan return and claim the Throne of Four Winds.", objectives = "" }
WordHunterWoW_QuestEN[41772] = { title = "Ascendant of Flames", description = "As we speak, an endless war rages for control of the Firelands. Of the two aspiring Firelords, Lord Smolderon hates mortals less.\n\nIf we help him defeat his rival and ascend to Firelord, he may unite with us in return.\n\nThe champions of the Earthen Ring have already made their way to the Firelands. Go and meet with Rehgar Earthfury and find a way to turn an old enemy into a new ally.\n\nIf anyone can succeed at this impossible task, I have faith that it is you, Farseer.\n\nMay the elements be with you.", objectives = "" }
WordHunterWoW_QuestEN[41773] = { title = "The Firelord's Command", description = "Greetings, mortal. I am Scaldius, emissary of Lord Smolderon.\n\nI have just met with others from your order. They tell me that you will bring an end to those who oppose my master. This pleases Lord Smolderon.\n\nPyroth and his minions defy my master's rule and so an example must be made of them. You will slay Pyroth and his champions!\n\nNothing is more humiliating than death at the hands of a mortal. Do this and Lord Smolderon will grant you audience.", objectives = "" }
WordHunterWoW_QuestEN[41774] = { title = "The Rival Lords of Fire", description = "You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself.\n\nHowever, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands.\n\nThey must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal.\n\nAmuse me shaman. Prove your worth and destroy my rivals!", objectives = "" }
WordHunterWoW_QuestEN[41775] = { title = "The Great Stonemother", description = "In order to unite the four Elemental Lords of Azeroth, you will need to seek out Therazane and convince her to join the cause of Azeroth.\n\nHowever, the Stonemother currently has her hands full battling a Twilight's Hammer resurgence in Deepholm.\n\nIf we lend Therazane our aid she may agree to unite with the Earthen Ring against the Burning Legion.\n\nJourney to Therazane's Throne in the heart of Deepholm. Aid her in defeating the Twilight's Hammer and convince her to join the defense of Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[41776] = { title = "Return of the Windlord", description = "With Thunderfury recharged, Prince Thunderaan can now return to the physical realm.\n\nIn a moment, I will release my master's spirit from the blessed blade.\n\nWhen the ritual is complete, Skywall will once again have its Windlord.", objectives = "" }
WordHunterWoW_QuestEN[41777] = { title = "Destroying the Cult", description = "We are all that stands between the Twilight's Hammer and their conquest of Deepholm.\n\nAzeroth cannot hope to fight the full strength of the Twilight's Hammer and the Burning Legion at the same time. It is up to us to put an end to their cult before they are able to fully rebuild.\n\nAccompany me into their stronghold and we shall cut through their ranks together!", objectives = "" }
WordHunterWoW_QuestEN[41780] = { title = "Doom and Gloom", description = "Doom curses are serious business, so much so that many warlocks didn't deal in them for some time. \n\nThe magic grows stronger as time goes on, eventually leading to death. Only the caster of the curse can remove it.\n\nI can craft an elixir that will slow its progression, but you'll need to collect an assortment of ingredients first.", objectives = "" }
WordHunterWoW_QuestEN[41781] = { title = "Herding Goats", description = "In case you haven't noticed, things are a bit hectic around here.\n\nMarl's doing a good job protecting the corn fields, but the commotion gave our goats quite the scare. They dashed out of their pen as soon as the fighting started, and are now running amuck!\n\nRound them up for me and I'll do my best to figure out how to handle the curse you're dealing with.", objectives = "" }
WordHunterWoW_QuestEN[41782] = { title = "To The Hills", description = "It is said that a fragment of Ursoc's spirit, his fury and rage, remained within the claws after his death. Only those who have attained mastery of discipline have any hope of wielding them without being overwhelmed by the bear lord's fury.\n\n<Lea looks intently at you for a moment.>\n\nBut you are no novice, I can see that clearly.\n\nVery well, draw water from the moonwell on the northern edge of the grove then come find me. I'll await your arrival within the broken stump of Vordrassil in Northrend.", objectives = "" }
WordHunterWoW_QuestEN[41784] = { title = "Borrowed Time", description = "Don't let the aroma deceive you, this concoction is mostly safe for consumption.\n\nWhoever is afflicted should drink the entire contents of the vial, every last drop! If the elixir works, the effects should be immediate. If not, well... just tell them they drink at their own risk, alright?\n\nKeep in mind, this will only weaken the curse, not cure it.", objectives = "" }
WordHunterWoW_QuestEN[41785] = { title = "Finding Fizzlebang", description = "I have reason to believe that Wilfred Fizzlebang's sister has made her way to Stormheim.\n\nIf she has half his power, but at least twice his intelligence, then we just might succeed in summoning the eredar twins.", objectives = "" }
WordHunterWoW_QuestEN[41787] = { title = "Someone Else's Mess", description = "A confession alone won't be enough to clear my name. As long as those demons run amuck, people will blame their presence on me. \n\nSomeone needs to clean up the mess that warlock made. I'd do it myself, but I can't be placed at the scene of the crime.\n\nYou could banish them though. That would do the trick. Use this orb on newly summoned demons to send them right back where they came from - permanently!", objectives = "" }
WordHunterWoW_QuestEN[41788] = { title = "Coercing a Confession", description = "My location has to be kept secret, at least until I have proof of my innocence.\n\nThanks to the legacy of my family name, any time some miserable warlock summons demons they can't control, I get the blame.\n\nThe scene of my latest \"crime\" is a nearby cave, where unruly imps and other nasty demons are roaming free.\n\nFind the lousy warlock who's responsible, and get him to write a confession.", objectives = "" }
WordHunterWoW_QuestEN[41790] = { title = "The First Trial of Ursol", description = "The Legion...\n\n<the glow of Ursol's eyes begin to shine intensely>\n\nYes... I remember clearly that day long ago when my brother fell. Countless demons fell beneath his claws until, through the overwhelming numbers of the enemy, he was overtaken. My brother was the true spirit of the bear!\n\nYou must prove to me that the spirit of the bear resides within you as well.", objectives = "" }
WordHunterWoW_QuestEN[41791] = { title = "The Second Trial of Ursol", description = "Ursoc never backed down from a battle, even when faced with overwhelming odds. If you would take up his claws you will show me that you possess the same courage.\n\nYour next trial will place you against an onslaught of my followers. Defeat all of the spirits and prove that you possess the courage of the bear!", objectives = "" }
WordHunterWoW_QuestEN[41792] = { title = "The Third Trial of Ursol", description = "You've proven to me your strength and your courage, but do you possess the ability to apply yourself when it matters most?\n\nThis final trial will reveal all.", objectives = "" }
WordHunterWoW_QuestEN[41793] = { title = "Lulubelle on Loan", description = "What you plan to do is pretty risky, you know? Summoning one sister would be difficult enough, but both of them at once? That's just asking for trouble.\n\nLuckily, I'm up for the challenge. I'll help you and the rest of the council summon those demons, and hopefully restore pride to the Fizzlebang name.", objectives = "" }
WordHunterWoW_QuestEN[41795] = { title = "Summoning the Sisters", description = "It would be best to conduct the summoning on the outskirts of Dreadscar Rift. If things do not go as planned, at least the aftermath will be contained to a small island of land that floats above our order.\n\nOnce the sisters have been summoned, use the Bloodstone to enslave them.\n\nI'll let the others know it's time to begin.", objectives = "" }
WordHunterWoW_QuestEN[41796] = { title = "Selecting a Sixth", description = "With the demon sisters under your control, you have managed to weaken Mephistroth's army and gain powerful allies for the council.\n\nOur work is not done, however. Dreadscar Rift will remain a target as long as the Burning Legion remains.\n\nIf we wish to protect our new home, we must rebuild the council. Both Lulubelle and Kira have proven themselves worthy to join our ranks, though only one spot remains.\n\nAs First of the Black Harvest, the choice is yours.", objectives = "" }
WordHunterWoW_QuestEN[41797] = { title = "Recruiting The Troops", description = "As her name suggests, Imp Mother Dyala is adept at summoning imps.\n\nWhile the council controls Dreadscar Rift, her services will be ours to use as we see fit.\n\nSpeak to her if you wish to train a pack of imps.", objectives = "" }
WordHunterWoW_QuestEN[41798] = { title = "Recruiting More Troops", description = "As First of the council, you have acolytes devoted to helping any way they can. Recruiter Jared is in charge of screening candidates, only selecting those that possess the skills we desire.\n\nSpeak to him now.", objectives = "" }
WordHunterWoW_QuestEN[41799] = { title = "Minions of the Darkness", description = "Oenia Skyhorn was a legendary chieftain of her tribe. Though she crossed over to the spirit realm long ago, her presence is still felt all around us.\n\nEbonhorn told me that Oenia placed a ward here to protect the people she cared for so deeply... perhaps from the specter of the Darkness.\n\nUse the Water of Vision to journey into her echoes. Worry not that this ritual might disturb her rest. A hero like Oenia would relish a chance to aid us in the present.", objectives = "" }
WordHunterWoW_QuestEN[41800] = { title = "Servants of the Darkness", description = "The heroes of Highmountain's past placed wards to protect our land from the insidious Old Gods. The deeds of these noble champions kept us safe for thousands of years.\n\nWe must not fail their memory.\n\nHuln Highmountain himself placed the ward here at Snowblind Mesa. It must be reactivated for us to have any hope of saving Ebonhorn.\n\nEnter the echo of Huln's spirit, and let his courage lead you to the location of this ward.", objectives = "" }
WordHunterWoW_QuestEN[41802] = { title = "The Gates of Valor", description = "Ye'd not normally know it, but the terraced entrance to the vrykul's Halls o' Valor is a fine place for findin' ancient artifacts. Problem is, the place is just a big mess with demons at the time.\n\nWell, ye've not got much choice. If the disc isn't elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[41803] = { title = "Asking a Favor", description = "Caria Felsoul was a bright student... and a Legion traitor.\n\nIn her treason she was bestowed the Aldrachi Warblades, the soul-rending blades of the Aldrachi's greatest champion - they say he only finally fell to Sargeras himself.\n\nWe sent a small force to find Caria, but we have not heard word since. Jace has a Legion communicator he believes we can use to reach them- we just need a power source.\n\nPerhaps you could see if Khadgar has anything we could use? I'm afraid our allies are few.", objectives = "" }
WordHunterWoW_QuestEN[41804] = { title = "Ask and You Shall Receive", description = "A Legion communicator? Hmmmm.\n\n<Khadgar pauses to think for a moment.>\n\nYou know what, I think I have something in my lockbox upstairs that is just the ticket.", objectives = "" }
WordHunterWoW_QuestEN[41806] = { title = "Return to Jace", description = "That crystallized soul should power your communicator long enough to reach your allies.\n\nI must urge you to be cautious, {name}. If that device is of Legion origin, then you never know who among its creators might overhear your message.\n\nI'm sure your allies eagerly await your return.", objectives = "" }
WordHunterWoW_QuestEN[41807] = { title = "Establishing a Connection", description = "<Jace glances at the crystallized soul.>\n\nYes, that will do nicely. Release its energy to activate the communicator - it should already be configured to contact Allari and her forces.\n\nIf Caria is out there, we will find her, and we will make her suffer for her transgressions.", objectives = "" }
WordHunterWoW_QuestEN[41815] = { title = "Curse of the Necrodark", description = "It is clear that the Old Gods have long sought to control Highmountain. Their covetous desire speaks to the power of this land, and the strength of the spirits that echo through its peaks and valleys.\n\nThey will not take our sacred mountain, {name}. Not while I draw breath.\n\nWith the Highmountain tribes united, and with Baine Bloodhoof at our side, we will defeat the Darkness... once and for all.\n\nCome. Let us take back the summit from the forces that would corrupt it.", objectives = "" }
WordHunterWoW_QuestEN[41834] = { title = "The Masks We Wear", description = "Many nightborne had pinned their hopes on Thalyssra deposing the Grand Magistrix. Since she disappeared, dissenting voices have grown silent.\n\nWe must spread the word, discreetly, among the populace. Ly'leth Lunastre will be a perfect ally in this. She is a socialite with many connections, and she is no friend of the Legion.\n\nLy'leth hosts a masquerade party at her estate where rumors are traded like coin - and brandished like daggers.\n\nLet us invite ourselves in.", objectives = "" }
WordHunterWoW_QuestEN[41839] = { title = "The Taken", description = "When Mayla's father was taken, so were the corpses of several of our greatest chieftains.\n\nThe Grey One, even now, is priming Mayla's father to be a vessel for his evil agenda.\n\nBut the others have already been taken by the necrodark, their corpses now vessels for malevolent drogbar spirits.\n\nI will be honest, I do not think my skills could defeat these monstrosities.\n\nWe need your help!", objectives = "" }
WordHunterWoW_QuestEN[41840] = { title = "Ice and Shadow", description = "We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence.\n\nPerhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets.\n\nI know little of such magics, but it seemed that Ebonhorn had a use for them in mind.", objectives = "" }
WordHunterWoW_QuestEN[41841] = { title = "The Final Ward", description = "The Necrodark are readying their ritual to give physical form to the Darkness. They've sealed themselves inside and barred our way.\n\nThe shards you brought me should provide the means to bring down the barrier. Once it is done, we have to act quickly. We must restore the final ward before the Darkness can manifest.\n\nDo not hesitate. The fate of Highmountain itself hangs in the balance.", objectives = "" }
WordHunterWoW_QuestEN[41845] = { title = "The Tribes Must Be Warned", description = "Though he lacks a corporeal form, do not assume the Grey One to be weak. \n\nLegends speak of him using the bodies of the dead as vessels for his dark magic. If true, this may be the next stage of his plan.\n\nMayla must be warned of what has transpired here. Now that he has been freed, the Grey One means to doom us all.\n\nSay the word and I can return us quickly to Thunder Totem.", objectives = "" }
WordHunterWoW_QuestEN[41846] = { title = "Power in a Vessel", description = "The Grey One is real! I always thought he was some ghost story told to young calves to keep them out of caves.\n\nWe must go to my father's burial chamber immediately!", objectives = "" }
WordHunterWoW_QuestEN[41849] = { title = "The Iron Fist", description = "It's time to send a rescue operation to the Gates of Valor, {name}.\n\nI will prepare our troops and send them at once. We will need a sizable army to take on the massive Legion force in Stormheim.\n\nGrandmaster, go ahead whenever you are ready. I will send our forces to meet you in the field.", objectives = "" }
WordHunterWoW_QuestEN[41850] = { title = "The Master of Swords", description = "I got bad news fer ya - we don't have time to wait for reinforcements. They're sacrificin' prisoners now! Every minute we wait here jabberin' is another life on the line!\n\nFirst things first, my friend Sylara is being held captive in the camp just across the road.\n\nWe need ta free her - she'll be a valuable ally.\n\nWe've got ta move move move!", objectives = "" }
WordHunterWoW_QuestEN[41851] = { title = "Quelling the Tide", description = "<Sylara looks at you with determined eyes.>\n\nOur friends are in danger. We will save them. Kill any Legion in the way.", objectives = "" }
WordHunterWoW_QuestEN[41852] = { title = "No Monk Left Behind", description = "Most of the prisoners are being held in the main camp at the Gates of Valor.\n\nOur people have been beaten and tortured, and worse still awaits for them if we don't save them.\n\nFind the cages within the main camp and free as many monks as you can find.\n\nI'll be right beside you, knocking heads and taking names!", objectives = "" }
WordHunterWoW_QuestEN[41853] = { title = "Zero to Hiro", description = "I have a favor to ask of you, {name}. My good friend Hiro is still somewhere inside the main camp.\n\nOnly problem is, the Gates of Valor are swarming with the biggest, baddest, nastiest Legion creatures I've ever seen. If we walk in there, we'll just get slaughtered.\n\nBut I've seen these vrykul chugging some kind of special brew called Storm Brew. It's some kind of combat tonic that makes them bigger and stronger.\n\nLet's steal some of that drink, then storm in to save Hiro!", objectives = "" }
WordHunterWoW_QuestEN[41854] = { title = "Brick By Brick", description = "Da monks be free, and we put a thorn in dat eredar lady's side.\n\nI'm back wit my friends, and lookin' forward to sleepin' in a bed tonight.\n\nLet's go back ta da Wanderin' Isle. I've never been so excited ta see a turtle in my life.", objectives = "" }
WordHunterWoW_QuestEN[41863] = { title = "Vengeance Will Be Ours", description = "Caria lies in the very heart of Legion territory - they'll see our forces immediately if we try to launch an all-out attack.\n\nFailure is not an option.\n\nHowever, if you go alone you might be able to slip by unnoticed long enough to avoid the brunt of the Legion army.\n\nRemember, {name} - this is not a rescue mission. The power of the Aldrachi Warblades could tip the scales of this war in our favor; Allari and her men are expendable if need be.", objectives = "" }
WordHunterWoW_QuestEN[41877] = { title = "Lady Lunastre", description = "Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city.\n\nHave your disguise ready just in case, {name}.", objectives = "" }
WordHunterWoW_QuestEN[41878] = { title = "The Gondolier", description = "I need your help.\n\nThe wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered.\n\nI am dedicated to preventing this for as long as possible.\n\nThere is a woman by the name of Deline who owns and operates a small delivery service out of her gondola.\n\nFind her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.", objectives = "" }
WordHunterWoW_QuestEN[41879] = { title = "A Lack of Punctuality", description = "You will likely have noticed on your way here that there are some very... busy... Nightborne running about.\n\nNaturally, the nobles lack any sense of discretion: they are couriers. They carry important missives.\n\nI give you this blade to perform a necessary service to our intelligence gathering. Use it to silently and quickly dispatch the couriers.\n\nTake their missives and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[41880] = { title = "Den of Shadows", description = "Placeholder: Thalyssra sends you to find Arluin Shadowblade, a deft assassin once in her employ/social circle. (whichever fits) Indicate that he would be an invaluable asset to making progress in the City with covert operations.", objectives = "" }
WordHunterWoW_QuestEN[41882] = { title = "Whispers of the Darkness", description = "Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into.\n\nOur people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own.\n\nWake them from their stupor. Free them from the whispers any way you can.", objectives = "" }
WordHunterWoW_QuestEN[41883] = { title = "Whispers of the Darkness", description = "Our Stonedark ally, Navarrogg, has asked for your aid.\n\nIt would seem a band of drogbar cultists known as the Necrodark are searching for something in the Vault of Neltharion.\n\nHe asks for you since you have been there before and held your own against its defenses.\n\nNavarrogg awaits you at the Obsidian Overlook.", objectives = "" }
WordHunterWoW_QuestEN[41884] = { title = "Dark Tales", description = "Spiritwalker Ebonhorn is stable... for now.\n\nHe once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own.\n\nIncapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack.\n\nTo find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there.\n\nMeet me in Riverbend, {name}. It is there our search begins.", objectives = "" }
WordHunterWoW_QuestEN[41888] = { title = "Allegiance of Flame", description = "My rivals lay dead and there are none within the Firelands who dare oppose my rule!\n\nAs promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies!\n\nGo now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!", objectives = "" }
WordHunterWoW_QuestEN[41889] = { title = "Dazed of the Past", description = "Let's begin crafting this mount armor, shall we?", objectives = "" }
WordHunterWoW_QuestEN[41890] = { title = "Dark Side of the Moon", description = "Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins ahead.\n\nIf it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet.\n\nMeet me at the Moonwell at once, {class}.", objectives = "" }
WordHunterWoW_QuestEN[41893] = { title = "Given to Corruption", description = "A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.\n\nAs with all who suffer this fate, there is no restoring him.\n\nPlease, {name}, bring him peace.", objectives = "" }
WordHunterWoW_QuestEN[41897] = { title = "The Master's Plan", description = "The purpose of the Twilight's Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant.\n\nDefeating the Twilight's Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created.\n\nLet us start by searching the encampment for clues as to their true purpose here.", objectives = "" }
WordHunterWoW_QuestEN[41898] = { title = "Unleashing the Elements", description = "According to The Master's journal, the Twilight's Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals.\n\nThe journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing.\n\nIt appears that our journey here is going to take us deeper into the depths of darkness...", objectives = "" }
WordHunterWoW_QuestEN[41899] = { title = "Held Captive!", description = "There are prisoners here, Farseer {name}, that are enslaved by the Twilight's Hammer.\n\nThe cultists work them to death in the depths of the mine.\n\nI cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight's Hammer prisoners we find, so that they may return to their homes and families.\n\nThe Twilight's Hammer will pay for their crimes!", objectives = "" }
WordHunterWoW_QuestEN[41900] = { title = "A Promise of Earth", description = "Deepholm thanks you, shaman.\n\nThe Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts.\n\nFor your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth.\n\nI have no love for the mortal races, but this world is not the Burning Legion's to destroy.\n\nTell your Earthen Ring that Therazane the Stonemother stands with them!", objectives = "" }
WordHunterWoW_QuestEN[41901] = { title = "Oath of the Windlord", description = "You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable.\n\nI know that the Earthen Ring seeks to save Azeroth from the Burning Legion.\n\nI will pledge my sword, and the armies of Skywall to the aid of Azeroth.\n\nWhen the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.", objectives = "" }
WordHunterWoW_QuestEN[41905] = { title = "Report from Tian Monastery", description = "We have heard from all our temples on Pandaria, except for one.\n\nWe dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual.\n\nGrandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.", objectives = "" }
WordHunterWoW_QuestEN[41907] = { title = "Appropriations", description = "I have come to lend my help to the Order of the Broken Temple.\n\nMy job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses.\n\nLao Shu is in charge of our supply inventory. Go and speak with him now in the inn.", objectives = "" }
WordHunterWoW_QuestEN[41909] = { title = "Tracking the Tideskorn", description = "We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off.\n\nThey've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail.\n\nI suggest that we send our champions immediately to assist with the tracking effort.", objectives = "" }
WordHunterWoW_QuestEN[41910] = { title = "Freya's Spring", description = "First, we need water from Freya's Spring.\n\nOnce a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool.\n\nSome say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew.\n\nI suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.", objectives = "" }
WordHunterWoW_QuestEN[41911] = { title = "Amaranthine Hops", description = "The hops for our brew must be a very specific, and they will also be hard to acquire.\n\nAmaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid.\n\nThere is one such supplier from whom I receive this item, but she may ask for something in exchange.", objectives = "" }
WordHunterWoW_QuestEN[41915] = { title = "The Master's Legacy", description = "You work for a murderer and a thief.\n\nThat design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret.\n\nI had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design.\n\nRetrieve the design and keep it out of his hands!", objectives = "" }
WordHunterWoW_QuestEN[41916] = { title = "A Better Future", description = "We must move quickly, {name}. I must save as many of my people as I can before the attack begins.\n\nWord has gotten out in the city that there is a safe haven with us and some no longer fear exile.\n\nVenture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.", objectives = "" }
WordHunterWoW_QuestEN[41918] = { title = "The Dreamer Returns", description = "Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone.\n\nI can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth!\n\nOur paths will cross again, {name}. Be sure of it.", objectives = "" }
WordHunterWoW_QuestEN[41919] = { title = "The Shadows Reveal", description = "The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive.\n\n<Valeera scrawls a few lines on a piece of paper, then hands it to you.>\n\nBut not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes.\n\nGo to each contact and tell them \"The shadows reveal.\" See what they know.", objectives = "" }
WordHunterWoW_QuestEN[41920] = { title = "A Matter of Finesse", description = "A rune of portals?! Who does Val'zuun think he is?\n\n<Valeera takes a deep breath.>\n\nIt's worth the price, but those runes aren't exactly easy to come by. Unless...\n\nArchmage Celindra, the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were...\n\n<Valeera smirks.>\n\nBut who said anything about asking?", objectives = "" }
WordHunterWoW_QuestEN[41921] = { title = "Closing In", description = "The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area.\n\nCome prepared for a fight. Akaari won't go down easily.", objectives = "" }
WordHunterWoW_QuestEN[41922] = { title = "Traitor!", description = "That lying demon SCUM! I should have known.\n\nLet's show Val'zuun what happens to people who dare cross the Uncrowned.", objectives = "" }
WordHunterWoW_QuestEN[41924] = { title = "Fangs of the Devourer", description = "If you spare me I can use the rune of portals you provided to open a gateway to Akaari's citadel in the Twisting Nether.\n\nOf course, killing the Legion's master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no?\n\n<Val'zuun smiles.>\n\nI will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.", objectives = "" }
WordHunterWoW_QuestEN[41934] = { title = "The Brand of Damnation", description = "I require a symbol of my dominion as Firelord. A weapon that will strike fear into the hearts of all who dare to oppose my rule!\n\nDeep within the den of the Cinderweb, there is an ancient spear born from within the heart of the Firelands. Emberscar is a living weapon whose wicked power is beyond mortal comprehension.\n\nProve your strength and claim Emberscar in my name! If you survive, perhaps I will aid the feeble races of humanity against the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[41945] = { title = "Tianji of the Ox", description = "Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked.\n\nI suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.", objectives = "" }
WordHunterWoW_QuestEN[41946] = { title = "Building Our Troops", description = "Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox.\n\nShe is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils.\n\nSpeak to her now and train an initiate of the ox.", objectives = "" }
WordHunterWoW_QuestEN[41957] = { title = "The Vindicator's Plea", description = "I've obtained a request from Vindicator Boros in Dalaran asking for our help.\n\nHe has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost!\n\nYou are strong with the Light, perhaps you can succeed where they can't?\n\nIf you need it, Brother Larry can provide you with a flight to Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[41966] = { title = "House Call", description = "I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there.\n\nI was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei.\n\nThere is something about those wounds that resists everything we've done to treat them. Please, {class}, as a brother in the Light I ask you to do all that you can to help him to recover.", objectives = "" }
WordHunterWoW_QuestEN[41967] = { title = "Out of the Darkness", description = "Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us.\n\nThe portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora... she tripped and I watched them drag her back.\n\nRescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.", objectives = "" }
WordHunterWoW_QuestEN[41981] = { title = "Traversing the Heavens", description = "If you are not opposed, {name}, I would accompany you on your journey through Skywall.\n\nThere are wonders here that my eyes have never before beheld, and it would be my great honor to join you.\n\nOur quest to resurrect the mighty Thunderaan and unite the four great elemental lords will be no easy task.\n\nLead the way, Farseer, and I shall follow.", objectives = "" }
WordHunterWoW_QuestEN[41989] = { title = "Blood of My Blood", description = "As my darling brother has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne.\n\nLoyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family.\n\nI will help Thalyssra stir a new rebellion, but first we must deal with Anarys.\n\nI do not wish to spill the blood of my blood - only to help him see reason.\n\nAnarys is likely brooding over our father's memorial. Bring him to me alive.", objectives = "" }
WordHunterWoW_QuestEN[41993] = { title = "Salvation From On High", description = "I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure!\n\nAll my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!", objectives = "" }
WordHunterWoW_QuestEN[42000] = { title = "Seeker of Truth", description = "You may be familiar with Orik Trueheart. He has devoted his time after the Northrend campaign to learning more about Tyr. \n\nOrik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out.\n\nPlease speak to him immediately.", objectives = "" }
WordHunterWoW_QuestEN[42001] = { title = "Aluneth, Greatstaff of the Magna", description = "Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic.\n\nWhen Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken.\n\nThe dragon Kalec may be our best chance. He now resides on the Council of Six.", objectives = "" }
WordHunterWoW_QuestEN[42002] = { title = "To Northrend", description = "Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord.\n\nTahu can help locate the grave, and with a short ritual we should have our answers!\n\nMeet us at Shield Hill in the Howling Fjord and we'll move on to the next step.", objectives = "" }
WordHunterWoW_QuestEN[42005] = { title = "The End of the Saga", description = "Ye should read the saga yerself, it's right here.\n\nWe're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak.\n\nYou should speak with Tahu so we can get started.", objectives = "" }
WordHunterWoW_QuestEN[42006] = { title = "A New Threat", description = "If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding.\n\nDuring my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus.\n\nHere, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[42007] = { title = "A Forgotten Enemy", description = "The device still hums with power. It must have been abandoned not long ago.\n\nThe nearby switch appears to activate it.", objectives = "" }
WordHunterWoW_QuestEN[42008] = { title = "Eyes of the Dragon", description = "You should travel at once to Coldarra in Borean Tundra, {name}. There, I would recommend you scout out a few key locations and report back to me. \n\nI know the area well, and should be able to tell you how to proceed.\n\nMake haste!", objectives = "" }
WordHunterWoW_QuestEN[42009] = { title = "Harnessing the Arcane", description = "The energy from Aluneth lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.\n\nIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", objectives = "" }
WordHunterWoW_QuestEN[42010] = { title = "Arcane Unleashed", description = "You have the power you need to destroy the Surge Needles. \n\nAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above.\n\nYou must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.", objectives = "" }
WordHunterWoW_QuestEN[42011] = { title = "The Nexus Vault", description = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. \n\nWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip.\n\nWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, {name}.", objectives = "" }
WordHunterWoW_QuestEN[42017] = { title = "Shrine of the Truthguard", description = "We'll be flying straight to the island. My friend said that the warrior who came here before us never entered the shrine itself, since they were after one of the tombs.\n\nIf a vrykul hero couldn't enter the shrine, I bet it's still protected by Tyr's power. I'm thinkin' we have a good shot at this.\n\nMy pal Cato will meet us there. We might be needin' the talents of a good healer!", objectives = "" }
WordHunterWoW_QuestEN[42031] = { title = "Dire Growth", description = "Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.", objectives = "" }
WordHunterWoW_QuestEN[42032] = { title = "Sampling the Nightmare", description = "There is still so much that we don't know about the Nightmare.\n\nBefore we can fight it, we must understand how it spreads.\n\nLet us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.", objectives = "" }
WordHunterWoW_QuestEN[42033] = { title = "Malorne's Refuge", description = "I see... it is as we have always feared. The Emerald Nightmare has found our world.\n\nWe must call upon the ancient god, Malorne.\n\nTravel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself.\n\nI already sent Broll Bearmantle ahead to give word of your arrival.", objectives = "" }
WordHunterWoW_QuestEN[42034] = { title = "Grip of Nightmare", description = "Most of the druids were able to escape, but the shrine is still swarming with enemies.\n\nThe shrine's leader, Sylendra  Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.", objectives = "" }
WordHunterWoW_QuestEN[42035] = { title = "Tracking the Enemy", description = "The Idol may be stolen, but there is still hope.\n\nWhile I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh.\n\nWith our heightened senses, we may still be able to pick up their trail.\n\nWe must follow their signs through the forest and recover the Idol!", objectives = "" }
WordHunterWoW_QuestEN[42036] = { title = "Idol of the Wilds", description = "We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere.\n\nSurely one of these satyrs will know where it was taken.\n\nGet the information out of these satyrs, even if it's the last thing they do.", objectives = "" }
WordHunterWoW_QuestEN[42037] = { title = "Gathering the Dreamweavers", description = "Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids.\n\nSend your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.", objectives = "" }
WordHunterWoW_QuestEN[42038] = { title = "Champion: Broll Bearmantle", description = "", objectives = "" }
WordHunterWoW_QuestEN[42039] = { title = "Champion: Sylendra Gladesong", description = "", objectives = "" }
WordHunterWoW_QuestEN[42040] = { title = "The Way to Nordrassil", description = "The time has come for us to use the Idol of the Wilds and commune with Malorne.\n\nThe ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree's essence.\n\nThere is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.", objectives = "" }
WordHunterWoW_QuestEN[42041] = { title = "Enduring the Nightmare", description = "We are under attack here, {name}!\n\nCreatures of the Nightmare are spilling into the Dreamway as we speak.\n\nDestroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!", objectives = "" }
WordHunterWoW_QuestEN[42042] = { title = "Teensy Weensies!", description = "Oh {name}, I'm so very very happy to see you!\n\nThe woodland critters whispered there was trouble in the Dreamway so I came immediately!\n\nThere are so very many teensy weensy little creatures that live here in the Emerald Dream, and they're out there, all lost and alone!\n\nWould you go out there and gather them up? You can use my flute to call them to you.\n\nThank you, brave druid!", objectives = "" }
WordHunterWoW_QuestEN[42043] = { title = "Cleaning Up", description = "When the Nightmare spreads, it consumes the life force of all that it touches.\n\nThe more it spreads, the weaker our magic becomes.\n\nIn its early stages, before the taint has taken hold, we can still cleanse the affected areas.\n\nI will bless you with Elune's grace. By channeling her power, you can reverse the Nightmare's spread.", objectives = "" }
WordHunterWoW_QuestEN[42044] = { title = "A Dying Dream", description = "Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart.\n\nHe was among the first defenders to battle against the Nightmare, but he has fallen to total corruption.\n\nIt pains me to say it, but we must destroy him.", objectives = "" }
WordHunterWoW_QuestEN[42045] = { title = "Communing With Malorne", description = "Our work here is done, {name}. We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state.\n\nBut we have more important matters at hand.\n\nTake the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[42046] = { title = "A New Beginning", description = "If Malorne is in danger, then things are even worse than I feared. It truly is up to us now.\n\nWe have very little time left. Let us reconvene in the Dreamgrove at once.", objectives = "" }
WordHunterWoW_QuestEN[42047] = { title = "Champion: Hamuul Runetotem", description = "", objectives = "" }
WordHunterWoW_QuestEN[42048] = { title = "Champion: Mylune", description = "", objectives = "" }
WordHunterWoW_QuestEN[42049] = { title = "Powering the Portal", description = "If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool's errand, but we cannot sit by idly.\n\nThere is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln.\n\nTo infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants.\n\nSend our champions to hunt and kill these enemies.", objectives = "" }
WordHunterWoW_QuestEN[42050] = { title = "Defenders of the Dream", description = "Never has our order faced such a difficult challenge. To succeed, we must rely on each other's strengths.\n\nHowever, we only have a few defenders to spare for the battle ahead.\n\nBroll, Sylendra, Zen'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one.\n\nWhich one will you choose to aid you in battle?", objectives = "" }
WordHunterWoW_QuestEN[42051] = { title = "Enter Nightmare", description = "The portal to the nightmare is ready, {name}. Remulos and the others have already gone ahead.\n\nThere is no telling what horrors await on the other side, {name}. Good luck.", objectives = "" }
WordHunterWoW_QuestEN[42053] = { title = "The War of the Ancients", description = "To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same.\n\nGo upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!", objectives = "" }
WordHunterWoW_QuestEN[42054] = { title = "Archimonde, The Defiler", description = "We have turned the battle, {name}! The Burning Legion is greatly weakened.\n\nOnly one task remains. Malorne is locked in battle with Archimonde, the demon that slew him ten thousand years ago.\n\nRemember, {name}, we are trapped in Malorne's nightmare. There is no telling what will manifest here, but we MUST do something.\n\nMay Elune guide us, {name}.", objectives = "" }
WordHunterWoW_QuestEN[42055] = { title = "The Demi-God's Return", description = "<Malorne's voice echoes in your mind.>\n\nMortal you may be, but your valor is worthy of the ancient gods.\n\nNature's spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature's spark - the WILL to survive.\n\nOur triumph here will be spoken of for ages to come, {name}.\n\nReturn to the waking world through this portal. We will speak again when we return to the Dreamgrove.", objectives = "" }
WordHunterWoW_QuestEN[42056] = { title = "Champion: Remulos", description = "", objectives = "" }
WordHunterWoW_QuestEN[42065] = { title = "The Twilight Master", description = "There is only one more thing that remains, Farseer {name}. We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all.\n\nWithout their so-called master, the remaining cultists will be forced to retreat from Deepholm.\n\nOnly when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[42068] = { title = "The Return of Twilight", description = "The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly.\n\nI cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it.\n\nGo. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!", objectives = "" }
WordHunterWoW_QuestEN[42074] = { title = "Return of the Light", description = "Excellent!\n\nThere is a gateway further down this pathway and like most Legion constructs it is powered by souls.\n\nI think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from.\n\nLet's go see where the path takes us, shall we?", objectives = "" }
WordHunterWoW_QuestEN[42079] = { title = "Masquerade", description = "Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra's return.\n\nYou must walk among the nightborne. You must earn the trust of our friends and foes alike.\n\nYou must become someone else.\n\n<Ly'leth hands you a shimmering party mask.>\n\nPut this on Anarys.", objectives = "" }
WordHunterWoW_QuestEN[42081] = { title = "In With the New", description = "Well, here's your new conduit. Try not to break this one, I really don't feel like making another.\n\nOh, and tell your boss, Deucus, that he owes me big time for this.", objectives = "" }
WordHunterWoW_QuestEN[42088] = { title = "Evacuate Snowmane", description = "They just keep coming!\n\nAnd now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village.\n\nGo, help the evacuation. We will hold the line here and try to buy you some time.", objectives = "" }
WordHunterWoW_QuestEN[42096] = { title = "Champion: Naralex", description = "", objectives = "" }
WordHunterWoW_QuestEN[42097] = { title = "Searching the Archives", description = "The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. \n\nIt's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. \n\nThe search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[42098] = { title = "Black Rook Hold: An Unclaimed Soul", description = "In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul.\n\nThe soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift.\n\nShinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. \n\nDwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.", objectives = "" }
WordHunterWoW_QuestEN[42100] = { title = "Empowering the Soul", description = "Creating the anchor will require more power than our soul shards will be able to provide.\n\nDreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.", objectives = "" }
WordHunterWoW_QuestEN[42102] = { title = "One Who's Worthy", description = "If we wish to successfully summon the sisters, we'll need the help of a warlock who is skilled in summoning greater demons.\n\nWe cannot afford to lose another council member due to inexperience. \n\nThe Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. \n\nHopefully among them we can find one worthy of this council.", objectives = "" }
WordHunterWoW_QuestEN[42103] = { title = "Let it Feed", description = "We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it.\n\nThe stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.", objectives = "" }
WordHunterWoW_QuestEN[42104] = { title = "The Underking Comes", description = "Here, I'm too slow to get these laggards to safety. Take my horn and sound the evacuation.\n\nWe need to get the people out of here before the drogbar arrive. The warbraves can take it from there.\n\nFor now just send them over to Spiritwalker Ebonhorn. That fool can watch over them until it is safe.", objectives = "" }
WordHunterWoW_QuestEN[42107] = { title = "On the Trail of the Great Worm", description = "We need the Gjallarhorn to compel the armies of Odyn's children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!", objectives = "" }
WordHunterWoW_QuestEN[42110] = { title = "To the Summit!", description = "Your armies have tracked the beast to the highest peak in Highmountain.\n\nIt has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!", objectives = "" }
WordHunterWoW_QuestEN[42114] = { title = "The Ritual of Tides", description = "Long ago, the first Farseer of the Earthen Ring was given a vision of the elements.\n\nIn the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements.\n\n{name}, I believe that you are the Farseer of this prophecy, called to lead before you were ever born.\n\nThe time has come to fulfill your destiny!\n\nWhen you are ready, we will perform the Ritual of Tides and call upon Neptulon, the first of the four great Elemental Lords.", objectives = "" }
WordHunterWoW_QuestEN[42120] = { title = "The Silver Hand", description = "Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer.\n\nTyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us.\n\nTake the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.", objectives = "" }
WordHunterWoW_QuestEN[42125] = { title = "Dark Whispers", description = "Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in!\n\nThere is a portal that my kind use to haul in treasures, with it you can get in and find the skull!", objectives = "" }
WordHunterWoW_QuestEN[42126] = { title = "Archmage Omniara", description = "Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked.\n\nSend Archmage Kalecgos to help her. He will be uniquely suited to this task.", objectives = "" }
WordHunterWoW_QuestEN[42127] = { title = "Building Our Troops", description = "Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order.\n\nShe is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us.\n\nSpeak to her now, and recruit her elementals.", objectives = "" }
WordHunterWoW_QuestEN[42128] = { title = "Ritual Reagents", description = "The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord!\n\nThere is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead!\n\nWe will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst.\n\nOh, and blood! I sense a beast whose blood should be perfect.", objectives = "" }
WordHunterWoW_QuestEN[42129] = { title = "The Pendant of Starlight", description = "To finish my work here, I will need a magical item called the Pendant of Starlight.\n\nFor centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it!\n\nThis pendant stores a great amount of arcane power... power I can use to heal the grove.\n\nGet it back, and I will be very grateful!", objectives = "" }
WordHunterWoW_QuestEN[42130] = { title = "Building Our Troops", description = "[PH] You can requisition new troops.\n\nGo speak to the trainers of these schools and train our first batch of recruits.", objectives = "" }
WordHunterWoW_QuestEN[42131] = { title = "Unexpected Visitors", description = "Brace yourself, {name}. I am detecting a strange magic forming in the chamber. Something is projecting itself in.", objectives = "" }
WordHunterWoW_QuestEN[42132] = { title = "Last, But Not Least", description = "I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions.\n\nThe two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.", objectives = "" }
WordHunterWoW_QuestEN[42133] = { title = "Same Day Delivery", description = "I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons.\n\nWhile I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.", objectives = "" }
WordHunterWoW_QuestEN[42134] = { title = "Recruiting More Troops", description = "Our champions acquired the talents of Recruiter Sampson, an extraordinary tracker.\n\nHe has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed.\n\nSpeak to him now.", objectives = "" }
WordHunterWoW_QuestEN[42137] = { title = "Champion: Yalia Sagewhisper", description = "", objectives = "" }
WordHunterWoW_QuestEN[42138] = { title = "Champion: Zabra Hexx", description = "", objectives = "" }
WordHunterWoW_QuestEN[42139] = { title = "Rise, Champions", description = "The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible.\n\nWe have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done.\n\nMight I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.", objectives = "" }
WordHunterWoW_QuestEN[42140] = { title = "A More Wretched Hive of Scum and Villainy", description = "Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types?\n\nI know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade.\n\nYeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City.\n\nSo, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.", objectives = "" }
WordHunterWoW_QuestEN[42141] = { title = "Summoner Morn", description = "Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.\n\nThe first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked.\n\nI suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.", objectives = "" }
WordHunterWoW_QuestEN[42142] = { title = "Recruiting The Troops", description = "Our champions acquired the talents of Summoner Morn, a powerful shaman.\n\nHe is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause.\n\nSpeak to him now and train a Lesser Elemental.", objectives = "" }
WordHunterWoW_QuestEN[42143] = { title = "The Champion's Call [WIP]", description = "[PH] Greetings, {class}. Beside me is the Mission Table. From it, you can assign our troops to complete vital assignments across the Broken Isles.\n\nGive it a try now, master. We have received word of a small demon attack on the city of Dalaran. Let us send someone to help repel the enemy.\n\nGaze upon the Mission Table and send a Champion to Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[42147] = { title = "First Contact", description = "Time to put your new disguise to the test.\n\nYour first contact is Vanthir, a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers.\n\nTell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand.\n\nBeyond that, we will need time to prepare. You should return to Thalyssra.\n\n<Ly'leth hands you a corked bottle of faintly glowing fluid.>\n\nGive her this, with my regards. We will call upon you soon.", objectives = "" }
WordHunterWoW_QuestEN[42149] = { title = "Some Knowledge Shouldn't Be Shared", description = "I noticed that quite a few of the Empyrean Society's books are inscribed with fel magic. That's blasphemous. We must confiscate as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[42158] = { title = "The Creator's Workshop", description = "My remote observation relay captured an astonishing amount of data from that tomb.\n\nIf we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it.\n\nSince you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!", objectives = "" }
WordHunterWoW_QuestEN[42166] = { title = "What Is Going On Here?", description = "We don't know much about the Empyrean Society's activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. \n\nLet's meet up at the rotunda on the hill.", objectives = "" }
WordHunterWoW_QuestEN[42168] = { title = "Looking into the Darkness", description = "Friend now is ready to perform the ritual!\n\nRemember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.", objectives = "" }
WordHunterWoW_QuestEN[42171] = { title = "Final Exit", description = "We've certainly reduced the Empyrean Society's numbers. I don't think they'll be luring any more members to their cause for a while. \n\nThere's only one place we haven't investigated, and I suspect that rune we found is attuned to the door. Let's see what's inside the building.", objectives = "" }
WordHunterWoW_QuestEN[42175] = { title = "Growing Power", description = "The Tirisgarde has need of your help now that you have grown in strength, {name}. Meet me in the Hall of the Guardian when you are done with your adventures.", objectives = "" }
WordHunterWoW_QuestEN[42184] = { title = "Mission: Elemental Diplomacy", description = "The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains.\n\nFor the next step of our campaign, I have organized a diplomatic mission to Skywall.\n\nThe goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al'Akir the Windlord, and to identify any elementals who would aid our cause.\n\nThe mission is currently waiting your assignment.", objectives = "" }
WordHunterWoW_QuestEN[42185] = { title = "Never Hunt Alone", description = "Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark.\n\nIf my deductions are correct, she'll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves!\n\nHopefully Thorim isn't off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.", objectives = "" }
WordHunterWoW_QuestEN[42186] = { title = "Growing Power", description = "Iron-Body Ponshu has requested your presence.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.", objectives = "" }
WordHunterWoW_QuestEN[42187] = { title = "Rise, Champions", description = "We are still recovering from the attack at the Peak of Serenity.\n\nTo help us rebuild the order, we should enlist the greatest champions of our class to fight by our side.\n\nI know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu.", objectives = "" }
WordHunterWoW_QuestEN[42188] = { title = "Nobundo Awaits", description = "Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer.\n\nA great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I'll take care of things here.\n\nNobundo is waiting for you now. May the elements be with you, Farseer.", objectives = "" }
WordHunterWoW_QuestEN[42191] = { title = "Tech It Up A Notch", description = "Thanks to you, the Order of the Broken Temple is gradually re-assembling.\n\nHowever, there is much more work to do. As our leader, you can determine the trajectory of our order's future.\n\nSpeak to Number Nine Jia. She will show you the ropes.", objectives = "" }
WordHunterWoW_QuestEN[42193] = { title = "The Gjallarhorn", description = "You have proven yourself most thoroughly time and again, {name}. There can be no doubt that you are the one to lead Odyn's armies into the final battle.\n\nYou must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us.\n\nKing Svergan Stormcloak was the last known living guardian of the horn.\n\nSeek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.", objectives = "" }
WordHunterWoW_QuestEN[42194] = { title = "Stolen Honor", description = "Safeguarding the Gjallarhorn was my duty, {race}. I will do what is right, but first I must ask for your aid.\n\nMy family was disavowed by the mystics of our time and this grave was ransacked.\n\nI cannot find peace while my family heirlooms are in the hands of the servants of the false God-King.\n\nReturn them to me and I will aid you in finding the Gjallarhorn!", objectives = "" }
WordHunterWoW_QuestEN[42197] = { title = "Champion: Duke Hydraxis", description = "", objectives = "" }
WordHunterWoW_QuestEN[42198] = { title = "Champion: Stormcaller Mylra", description = "", objectives = "" }
WordHunterWoW_QuestEN[42200] = { title = "Mission: Investigating Deepholm", description = "In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us.\n\nTherazane has been absent from our negotiations with the elements thus far.\n\nThere have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid.\n\nI have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.", objectives = "" }
WordHunterWoW_QuestEN[42202] = { title = "Revenge, Served Cold", description = "My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared.\n\nHelp me avenge my people and I will aid you in your quest to find Jorhuttam.", objectives = "" }
WordHunterWoW_QuestEN[42204] = { title = "Jorhuttam", description = "You upheld your end of your promise. I will do the same.\n\nTake these drogbar drums. Then bang on them to call upon Jorhuttam to feast.\n\nFind the Great Worm's feeding mound and use the drums to lure her out.", objectives = "" }
WordHunterWoW_QuestEN[42206] = { title = "The Next Level Has Arrived", description = "The Empyrean Society is certainly much more dangerous than they appear. It's unimaginable that any mage would study fel magic -- that's for warlocks and the Legion!\n\nSince our friend, Ravandwyr, appears to be delayed, it looks like we'll have to deal with this ourselves. We should remove this sect so they can't corrupt anyone else.", objectives = "" }
WordHunterWoW_QuestEN[42208] = { title = "Return to the Firelands", description = "The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer.\n\nRagnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression.\n\nI have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there.\n\nIf the mission is successful, we may find the information we need to bring the Firelands into our fold.", objectives = "" }
WordHunterWoW_QuestEN[42210] = { title = "Scrolls of Knowledge", description = "Our troops are ready! It's time to test them out in the field, and I have the perfect assignment.\n\nNumber Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many  of her important scrolls were left behind during the attack on the Peak of Serenity.\n\nSend our champions to retrieve these documents at once!", objectives = "" }
WordHunterWoW_QuestEN[42213] = { title = "Eye of Azshara: The Tidestone of Golganneth", description = "<Now that you have defeated Queen Azshara's Wrath and have the Tidestone in hand, it is time to place it in the Portrait Room of the Chamber of the Guardian in lower Dalaran.>", objectives = "" }
WordHunterWoW_QuestEN[42214] = { title = "Knocked for a Loop", description = "While you're focused on murlocs...\n\nMany murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use.\n\nCollect some of their jewelry and bring it back to me. The wetter, the better!", objectives = "" }
WordHunterWoW_QuestEN[42220] = { title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<It looks like the sailors are being poisoned and worse. Best to put them out of their misery.>", objectives = "" }
WordHunterWoW_QuestEN[42222] = { title = "Empyrean Society Report", description = "I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... \n\nRegardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.", objectives = "" }
WordHunterWoW_QuestEN[42223] = { title = "Scouting the Crimson Thicket", description = "If you are heading east, there is something I would ask of you.\n\nWhile we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long.\n\nI would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.", objectives = "" }
WordHunterWoW_QuestEN[42224] = { title = "Cloaked in Moonshade", description = "I do not know what Theryn found, but I know where he found it. \n\nMoonshade Sanctum, to the west. Beyond the Temple of Fal'adora. \n\nWhatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. \n\nI know this as surely as if I had been there myself.", objectives = "" }
WordHunterWoW_QuestEN[42225] = { title = "Breaking the Seal", description = "<As you behold the relic, Thalyssra's voice echoes in your mind.>\n\nYou found it! But it is sealed away tight.\n\nSearch the room for a way to break those seals.", objectives = "" }
WordHunterWoW_QuestEN[42226] = { title = "Moonshade Holdout", description = "<Tampering with the relic has drawn the attention of some hideous creatures from beneath Falanaar.>", objectives = "" }
WordHunterWoW_QuestEN[42227] = { title = "Into the Crevasse", description = "I have protected that seed for ten thousand years. You let it fall into the hands of the fal'dorei.\n\nI should have let you die.\n\nRepay your debt. Help me get the seed back.", objectives = "" }
WordHunterWoW_QuestEN[42228] = { title = "The Hidden City", description = "Orathiss has underestimated the seed. It is sapping her power - slowing her down.\n\nWe must catch her and get the seed to safety!", objectives = "" }
WordHunterWoW_QuestEN[42229] = { title = "Shal'Aran", description = "The chamber beyond may be the perfect hiding place, now that its guardian has been dealt with.\n\nCome with me.", objectives = "" }
WordHunterWoW_QuestEN[42230] = { title = "The Valewalker's Burden", description = "The seed is awakening. Without power it will quickly wither and die.\n\nWe must carry the seed out of here and plant it somewhere safe.\n\nI am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. \n\nPlease take the seed.", objectives = "" }
WordHunterWoW_QuestEN[42231] = { title = "The Mysterious Paladin", description = "It appears we have been afforded a unique opportunity.\n\nA small order of paladins has come forward claiming to know the location of Tyr's tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled.\n\nI'd like you to speak with Travard, their leader, to find out more about this artifact.", objectives = "" }
WordHunterWoW_QuestEN[42238] = { title = "Missing Demon", description = "I seem to have misplaced my imp, Daglop.\n\nIf you see him, tell him to check in.\n\nNormally I would just resummon him but I'm worried blind Marius here will kill him first and ask questions later.\n\nNo vision, that one.", objectives = "" }
WordHunterWoW_QuestEN[42244] = { title = "Fate of the Queen's Reprisal", description = "<This is the kind of intelligence that should be shared. Perhaps someone at the Windrunner's Sanctuary on Dalaran will know what to do with it.>", objectives = "" }
WordHunterWoW_QuestEN[42268] = { title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<The sailors are being treated very poorly. It looks like a rescue operation is in order.>", objectives = "" }
WordHunterWoW_QuestEN[42271] = { title = "Their Dying Breaths", description = "I have precious little time. As we speak, my troops are defending against an onslaught of withered elves.\n\nThese four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear.\n\nSome cracked ley crystals should bring them back to their senses.", objectives = "" }
WordHunterWoW_QuestEN[42365] = { title = "Focusing the Energies", description = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.\n\nThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", objectives = "" }
WordHunterWoW_QuestEN[42366] = { title = "The Bigger They Are, The Harder They Fel", description = "I have had it with these small fry, assistant. Time to go straight to the top.\n\nThe tome is the key! The key to unlocking the potential within our people.\n\nDo not worry, young one. I have enough power to complete the task at hand. Let us harness fel magic and change the future.\n\nFollow me and witness the redemption of the shal'dorei!", objectives = "" }
WordHunterWoW_QuestEN[42367] = { title = "Arkethrax", description = "Within the Ingress is a demon who must die.\n\nArkethrax is a creature of cunning evil. If left unchecked he will be able to use the Ingress as a staging point for targeted assaults that will decimate our forces.\n\nI, for one, have no intention of underestimating this opponent and shall join you on the battlefield when you are ready to fight him.", objectives = "" }
WordHunterWoW_QuestEN[42368] = { title = "Quantity Over Quality", description = "The demons of Felblaze Ingress are amassing at an exponential rate.\n\nWe must cull these invaders before they have enough demons to flank our forces at Illidari Stand.\n\nWill you join us in battle?", objectives = "" }
WordHunterWoW_QuestEN[42369] = { title = "They're Doing it Wrong", description = "These demon portals are terrible and sloppy. No skill or finesse in it.\n\nThis physically hurts me and I haven't felt real pain in decades.\n\nI \"fixed\" some of the Legion's precious Portal Stabilizer crystals.\n\nI want you to take them and \"modify\" their main portal in the Ingress and watch the \"hilarity\" ensue.", objectives = "" }
WordHunterWoW_QuestEN[42370] = { title = "Wanding 101", description = "We'll start with some wand work. You have your wand with you? Good.\n\nI've set up a number of targets around the hall. Use your wand to hit as many as you can.\n\nAnd no point-blank shots! That's cheating.", objectives = "" }
WordHunterWoW_QuestEN[42371] = { title = "Study Hall: Combat Research", description = "What's this? A new, confused student, desperately trying to win the favor of the headmistress, wandering the halls without anything to do?\n\nPerfect! I need help with my research.\n\nI'm writing a paper on combat. Grab me some books from the shelf over there.", objectives = "" }
WordHunterWoW_QuestEN[42372] = { title = "Felblaze Ingress", description = "It is my mission to cover the rear guard of Illidari Stand. I have employed this warlock... thing, to assist me.\n\nHowever, the two of us are insufficient for a task that needs doing.\n\nTo the east is a mass of demons at Felblaze Ingress. These creatures have begun to open portals to summon in countless reinforcements.\n\nMeet us at Felblaze Ingress and together we can crush this fel insurgency.", objectives = "" }
WordHunterWoW_QuestEN[42375] = { title = "Eye See You", description = "There is being blind, and then there is being stupid.\n\nThis eyeless wonder next to me wants to barrel into Felblaze Ingress without preparation.\n\nBah! I say we scout it first.\n\nHere, I will provide you with an extra eye I picked up from a place better left unmentioned.\n\nEnter Felblaze Ingress, investigate the area, and try not to get poked in the eye.", objectives = "" }
WordHunterWoW_QuestEN[42377] = { title = "The Brother's Trail", description = "We must reclaim the Silver Hand before those with evil intent can seize it. To free it from its wards, we need relics called the Sparks of Tyr. I have one, as does my brother, Galford.\n\nHe journeyed to Northrend to seek aid from the Tyr's homeland, but has not returned.\n\nI must ask you to find him, and his Spark.", objectives = "" }
WordHunterWoW_QuestEN[42383] = { title = "Rise, Champions", description = "The Earthen Ring is built upon the strength and dedication of its members.\n\nIf we are to help defend this world against the Burning Legion, we will need to grow our order, and recruit skilled champions to our side.\n\nBegin by speaking to Stormcaller Mylra and Duke Hydraxis. Perhaps they would be willing to fight for us.", objectives = "" }
WordHunterWoW_QuestEN[42384] = { title = "Scouting Reports", description = "In the recent past, our order has spent a lot of time watching and waiting. With you at the helm, we'll be able to focus on our original calling.\n\nTake a look around us, {name}. Azeroth needs us now more than ever. The same enemy that led to our formation is threatening us once again.\n\nYou should send someone to gather reports from our scouts. From there, we'll be able to focus our efforts where they are needed most.", objectives = "" }
WordHunterWoW_QuestEN[42385] = { title = "Lending a Hand", description = "Our scouts reported seeing a village in Val'sharah being attacked by undead hounds.\n\nThis is the perfect opportunity for the Unseen Path to make good on our promise to help those in need.\n\nYou should head out to Bradensbrook and see what you can do to help.", objectives = "" }
WordHunterWoW_QuestEN[42386] = { title = "Rising Troubles", description = "Our village is swarming with beasts risen from the dead!\n\nThe abominations never rest! They attack night and day.\n\nWe're doing our best to keep them at bay, but it's getting to be more than the townsfolk can handle. They're tired and losing their will to fight.\n\nAnything you can do to lessen the burden would be greatly appreciated.", objectives = "" }
WordHunterWoW_QuestEN[42387] = { title = "Assassin Entrapment", description = "Black Rook invaders are still targeting our farms and homes, even though there's not much left to pillage.\n\nWe had hoped that once they cleared us out that the attacks would stop, but it seems those mindless ghouls will follow any orders given by their commander.\n\nWe'd take him out ourselves, but he's a sneaky fella. The only way we're going to catch him, is if someone lays a trap. I can provide the supplies if you're willing to help.", objectives = "" }
WordHunterWoW_QuestEN[42388] = { title = "Urgent Summons", description = "The eagle appears to have a message for you:\n\n             To: {name}\n\nOur scouts have returned with reports from all over Azeroth. It seems that things are much worse than they initially seemed.\n\nReturn to Trueshot Lodge as soon as you can.\n\n             -Emmarel Shadewarden", objectives = "" }
WordHunterWoW_QuestEN[42389] = { title = "Calling Hilaire Home", description = "With so many in need of our help, it may be time to call in some of our scouts in the field.\n\nOne such scout is a huntress by the name of Hilaire. Although she abandoned her clan long ago to join our order, she still feels a need to watch over them.\n\nHer dedication to protect those who would shun her is admirable, but we need her here.\n\nSeek Hilaire out in Stormheim, and let her know it's time to come home.", objectives = "" }
WordHunterWoW_QuestEN[42390] = { title = "Recruiting Rexxar", description = "To do the most good, we need the best hunters at our side.\n\nHaving you leading the order is a great start, but we'll need others who share your skill and expertise if we plan on making an impact.\n\nRexxar has a reputation of being one of the greatest hunters of his time, yet he's never been eager to aid the Unseen Path.\n\nHe has a camp just north of here, where he and Misha live off the land. Maybe you can convince him to join our ranks.", objectives = "" }
WordHunterWoW_QuestEN[42391] = { title = "Bite of the Beast", description = "I will not leave my post without Cora.\n\nA group of mages have her caged up like a beast, threatening to put her down.\n\nThey claim she's responsible for the death of one of their own, but I refuse to believe that. Cora is a loyal and obedient companion; she would never attack without my command.\n\nI tracked the demon that was truly responsible to this location, but it put up quite a fight before getting away. My injuries prevented me from giving chase, but I am sure that beast has left a bloody trail.", objectives = "" }
WordHunterWoW_QuestEN[42392] = { title = "Survive the Night", description = "Now it's time to put your skills to the test.\n\nYour order seems to be a lot of watching and waiting without a lot of action.\n\nProve me wrong. Show me that I might have something in common with the Unseen Path.\n\nIf you survive a night in the wild, then I will consider joining your order.", objectives = "" }
WordHunterWoW_QuestEN[42393] = { title = "Homecoming", description = "Cora has calmed enough to make the journey back to Trueshot Lodge.\n\nYou can let Emmarel know that we are on our way home.", objectives = "" }
WordHunterWoW_QuestEN[42394] = { title = "Unseen Protection", description = "We will not let the city of Dalaran fall.\n\nIf the Legion is planning an attack, the Unseen Path will be there to stop it.\n\nOur scouts' most recent reports list a few other areas that sound like they could really use our help, whether they realize it or not.\n\nAs soon as you're able, send your hunters to take care of the threats.", objectives = "" }
WordHunterWoW_QuestEN[42395] = { title = "Signaling Trouble", description = "Long ago, we gave select leaders special flares that were only to be used in times of great need.\n\nUpon seeing the flare, the leader of the Unseen Path is supposed to head to the southern watchtower to meet with whomever lit it.\n\nI don't know who we'll face once we reach the tower, but we must move quickly.", objectives = "" }
WordHunterWoW_QuestEN[42396] = { title = "Do The Thing!", description = "Mrglrg! Mrlglr mrgllrg.\n\n<Phin gesticulates wildly>\n\nMrlgrlg glrglmglr mrlglrg. Rglrgmrg mrglr glr. Glr! Gmrlgrmlg mrglmrgm...\n\n<Phin looks at you expectantly.>", objectives = "" }
WordHunterWoW_QuestEN[42397] = { title = "Baron and the Huntsman", description = "We've received word from Khadgar that he's lost contact with the mages he sent to investigate the Legion's camps. He's requested our assistance in tracking them down.\n\nIf we have any hope of locating those mages, we'll need to find ourselves a reliable hound capable of following a scent.\n\nThere is only one such hound that I know of, and he's long since retired. It's worth it to check in with his master, Hunstman Blake, and see if old Baron still has it in him.", objectives = "" }
WordHunterWoW_QuestEN[42398] = { title = "Awakening the Senses", description = "I'm afraid old Baron here is past his prime. His nose can't catch a scent the way it used to. Others told me to put him down, but I can't bear the thought of losing my loyal friend.\n\nBaron was always at his best when working, though. Maybe if you let him wander through these fields and dig up some old bones, it'll be enough to awaken his senses.", objectives = "" }
WordHunterWoW_QuestEN[42399] = { title = "Ready to Work", description = "If Baron's ready to work, I am too.\n\nWe'll make our way to the hunter's lodge as soon as I pack up camp and get this dog fed. I'm sure with all that digging, he'll have a hearty appetite.", objectives = "" }
WordHunterWoW_QuestEN[42400] = { title = "Missing Mages", description = "The Archmage has already made his way to Suramar, where the missing mages were last seen.\n\nBaron ran off, too. It seems that hound is eager to work again.\n\nMeet them both near the road that leads into the city. With any luck, Baron will be about to pick up on their magical scent and find the missing mages before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[42401] = { title = "The Scent of Magic", description = "This is the last known location of the missing Kirin Tor. There isn't much evidence, other than a torn piece of cloth, which looks to be from one of our tabards.\n\nThe scrap may be small, but it should be heavy with the essence of magic. We can only hope that Baron can catch the scent and track down the mages.", objectives = "" }
WordHunterWoW_QuestEN[42402] = { title = "Requesting Reinforcements", description = "Many powerful factions have pledged their loyalty to the Unseen Path. It's time that we call on them to help us defeat Hakkar and his demon hounds.\n\nSend your champions into the field to track down these leaders and let them know we require their help.", objectives = "" }
WordHunterWoW_QuestEN[42403] = { title = "Highmountain Hunters", description = "I've just received word from our scouts that they've identified some potential recruits.\n\nIt seems as though the famed Hemet Nesingwary has set up camp not too far from our lodge.\n\nWhile he isn't traditionally the type of hunter we'd invite into our ranks, his experience hunting large game could come in handy.\n\nHead on over to his retreat and see if he's willing to aid our cause.", objectives = "" }
WordHunterWoW_QuestEN[42404] = { title = "Assisting the Archmage", description = "Hakkar maintains an army of felhounds that feed off of magic. As long as he remains within Azeroth, no mage will be safe.\n\nHe and his hounds are immune to most spells, so I must ask for assistance in killing them.\n\nYou have proven yourself more than capable, but are you willing to help take down this demon?", objectives = "" }
WordHunterWoW_QuestEN[42405] = { title = "Informing Our Allies", description = "Leaders from some of the greatest military factions are here, ready and willing to help.\n\nThey're currently waiting to speak with you directly, hoping to provide insight on how they can help.\n\nWith any luck, we can pull our resources and find a way to take Hakkar down.", objectives = "" }
WordHunterWoW_QuestEN[42406] = { title = "To Tame the Beast", description = "Deep in the heart of Faronaar are dens that are overrun with felhounds. If Hakkar is breeding those beasts, that is the place he would do it.\n\nThe bait I've crafted is potent. Once you apply it, you'll draw the attention of nearby hounds, so only use it when you're close to the dens.\n\nOnce the demon has taken the bait, get it into a weakened state to make trapping easier.\n\nGood luck, {name}. I hope you return in one piece.", objectives = "" }
WordHunterWoW_QuestEN[42407] = { title = "The Nature of the Beast", description = "By nature, this demon is immune to magic, but it has also been bred to be resistant to physical attacks. It's covered in scales unlike anything I've ever seen; layered and thick. I doubt that most metals will be able to pierce the demon's armor-like hide.\n\nUnless your entire army has weapons like yours, I suggest fighting those beasts with something that will exploit their weakness.", objectives = "" }
WordHunterWoW_QuestEN[42408] = { title = "Required Reagents", description = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.\n\nShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", objectives = "" }
WordHunterWoW_QuestEN[42409] = { title = "Champion: Loren Stormhoof", description = "", objectives = "" }
WordHunterWoW_QuestEN[42410] = { title = "Champion: Rexxar", description = "", objectives = "" }
WordHunterWoW_QuestEN[42411] = { title = "Champion: Beastmaster Hilaire", description = "", objectives = "" }
WordHunterWoW_QuestEN[42412] = { title = "Champion: Huntsman Blake", description = "", objectives = "" }
WordHunterWoW_QuestEN[42413] = { title = "Champion: Hemet Nesingwary", description = "", objectives = "" }
WordHunterWoW_QuestEN[42414] = { title = "Champion: Addie Fizzlebog", description = "", objectives = "" }
WordHunterWoW_QuestEN[42415] = { title = "Champion: Halduron Brightwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[42416] = { title = "The Council is in Session", description = "Archmage Vargoth's involvement with the Empyrean Society is troubling. However, as he has proven his loyalty to the Kirin Tor many times, we must give him the benefit of the doubt for now. \n\nStill, I am obligated to share our concerns with the rest of the Council. You had best travel to Dalaran and meet with them in the Violet Citadel. I will remain here to care for our old friend.", objectives = "" }
WordHunterWoW_QuestEN[42418] = { title = "An Unexpected Visitor", description = "Archmage Vargoth's long-time apprentice, Ravandwyr, has arrived here in the Hall of the Guardian with an urgent message from his mentor.\n\nHe will be waiting for you upstairs. You had best find him quickly, {name}!", objectives = "" }
WordHunterWoW_QuestEN[42423] = { title = "Archmage Vargoth's Retreat", description = "Archmage Vargoth has been absent for a while. You may have a look around his living quarters here in the citadel tower, {name}. Kalec will escort you there.\n\nI will hold out hope that our esteemed colleague is merely up to his usual eccentricities.", objectives = "" }
WordHunterWoW_QuestEN[42424] = { title = "Following In His Footsteps", description = "Archmage Vargoth seems to be mixed up in something dangerous, not that that's unusual for an archmage of his caliber and experience!\n\nThe Arcway Vaults may be where he's headed, but we should investigate all leads in order to get a better idea of what he's up to.", objectives = "" }
WordHunterWoW_QuestEN[42425] = { title = "Going Down, Going Up", description = "Now that we have the necessary worm guts, I was able to fashion them into a special sort of rope.\n\nIt will allow you to descend from the bridge into the chasm below and recover some of my possessions that were stolen and thrown in by the Deeprock.", objectives = "" }
WordHunterWoW_QuestEN[42428] = { title = "The Shrine of Ashamane", description = "The mighty Ancient, Ashamane, fell in battle against the Burning Legion ten thousand years ago. To honor her sacrifice, a group of devoted druids called the Ashen forged Ashamane's fangs into powerful daggers.\n\nTake my signet and present it to their leader, Delandros Shimmermoon. He will know that you have my blessing.\n\nOur flight master, Danise Stargazer, can see you to the shrine.", objectives = "" }
WordHunterWoW_QuestEN[42429] = { title = "Memories of Ebonchill", description = "Is that Ebonchill you've got there? Alodi's old staff? My my my... <Cough>\n\nIn the days of the first guardian, all the members of the Council of Tirisfal granted their powers to the young mage in the hopes that he could overcome the Legion. <Wheeze> None of them are alive today... but that staff of yours remembers.\n\nSearch the streets of Dalaran below for reflections of the former council members. Their memories may empower you as they once did Alodi. Seek them out and speak with one!", objectives = "" }
WordHunterWoW_QuestEN[42430] = { title = "The Fangs of Ashamane", description = "I have to admit, Verstok was right. The shrine was too easy of a target for the Burning Legion to attack. Still, he's gone and the Fangs are with him.\n\nWe're going to have to track him down for you to recover the Fangs. I should come with you but I have to stay with my people should we be attacked again.\n\nHere, my companion Ebonfang has a sense of smell like no other. He will be able to guide you to wherever Verstok is hiding. Also take this shell, through it we can communicate.\n\nMay Elune guide you.", objectives = "" }
WordHunterWoW_QuestEN[42432] = { title = "The Emerald Nightmare: The Emerald Nightmare", description = "The Lord of Nightmare, Xavius, is still out there. Cenarius is still in grave danger, deep within the Rift of Aln.\n\nSummon your greatest allies, {name}. If we are to stare into the face of the Nightmare, we had best be ready.\n\nOnce you are ready, enter the Emerald Nightmare and defeat all the horrors you find there.", objectives = "" }
WordHunterWoW_QuestEN[42433] = { title = "Ancient Magic", description = "Since the Broken Isles is the epicenter of ancient night elven learning, there must be countless magical artifacts secreted away in forgotten vaults and reliquaries. We must secure them so they do not fall into the wrong hands!\n\nPerhaps you should send a champion in search of them.", objectives = "" }
WordHunterWoW_QuestEN[42434] = { title = "A Covert Operation", description = "Your champion discovered some sort of powerful magic emanating from the secretive Empyrean Society enclave in Azsuna. \n\nArchmage Vargoth asked me to request Meryl's aid in investigating it, but as you can see, Meryl is clearly too ill to travel at the moment. Would you be willing to go in his place?\n\nYou will need to prove yourself in order to gain entrance. We should be able to find something sufficient in the Hatecoil Warcamp in Azsuna.", objectives = "" }
WordHunterWoW_QuestEN[42435] = { title = "Prepare To Be Assimilated", description = "The Empyrean Society is a dangerous cult. They claim to study all magic regardless of its source, but in reality they focus mostly on the forbidden. They will welcome you to their enclave if you bring them a magical artifact.\n\nThe Hatecoil naga have found the perfect gifts - a Pearl of Arcane Wisdom and scrolls from the depths beneath the Nar'thalas Academy. You will have to convince them to part with a few.\n\nI will meet you on the road just north of the Empyrean Enclave.", objectives = "" }
WordHunterWoW_QuestEN[42436] = { title = "Aiding Our Allies", description = "Our Skyhorn allies could use some assistance. \n\nTheir ongoing war with the invading harpies has left them low on supplies. \n\nAnything we can give them will surely help with their efforts to rid those witches from their village.", objectives = "" }
WordHunterWoW_QuestEN[42438] = { title = "Seeds of Renewal", description = "The Fangs of Ashamane are in danger, {name}. For ten thousand years a powerful magic ward has protected them from any would-be thieves, but the ward has weakened over time and is in danger of failing. My three most trusted Ashen have the Tel'andu seeds we need to perform the ritual of renewal,  but the woods are now crawling with demons and I fear they have fallen.\n\nNo matter what, we cannot allow the Legion to obtain the Fangs! Go and find the Tel'andu seeds, we must hurry before the ward can be broken!", objectives = "" }
WordHunterWoW_QuestEN[42439] = { title = "Aid for the Ashen", description = "Turn your eyes above and you will see the cause of our misfortune. Ever since that ship appeared the attacks have been relentless. Many of the Ashen have been captured and even now I can hear their screams of torture.\n\nPlease, go out there and rescue as many of my followers as you can. They do not deserve the fate that awaits them if left in the Legion's grip.", objectives = "" }
WordHunterWoW_QuestEN[42440] = { title = "The Shrine in Peril", description = "You've helped us greatly, champion. Now, it is time that you tell me what brings you here.\n\n<You mention to Delandros that Archdruid Greathoof sent you to seek the Fangs of Ashamane.>\n\nHrm... if you had told me this at the outset, I would have told you to take a walk. The Fangs are our greatest treasure, but you've done a great deed for the Ashen today and I am an elf of my word.\n\nVery well, let's clear out the rest of these demons and you shall have your weapons.", objectives = "" }
WordHunterWoW_QuestEN[42444] = { title = "Plight of the Blackfeather", description = "<The ravenbear frantically gestures and points down the path. \n\nIt seems he wants you to follow him.>", objectives = "" }
WordHunterWoW_QuestEN[42445] = { title = "Nithogg's Tribute", description = "It looks like the ravenbears have started gathering materials for some sort of tribute, but the storm drakes are keeping them from finishing what they started.  \n\nFrom the looks of it, they're gathering fully intact stag horns and long tail feathers from the greatstags and eagles nearby. \n\nIt shouldn't take too long to gather the rest of what they need.", objectives = "" }
WordHunterWoW_QuestEN[42446] = { title = "Singed Feathers", description = "Ca-caw! Caw caw!\n\n<The chieftain flaps his wings and points outside where the storm dragons attack the ravenbears of his tribe. \n\nIt's plain to see that he's seeking your help to save his flock.>", objectives = "" }
WordHunterWoW_QuestEN[42447] = { title = "Dances With Ravenbears", description = "<The chieftain beckons for the ravenbears to gather the tribute and gestures toward the ritual circle outside.>\n\nCaw! Caw ca-caw!\n\n<It looks like he wants you to follow.>", objectives = "" }
WordHunterWoW_QuestEN[42449] = { title = "Return of the Four Horsemen", description = "The voice of the Lich King has spoken, Deathlord, and the Knights of the Ebon Blade will obey your command.\n\nThe Four Horsemen were no ordinary death knights, they were born of pure, unholy power gifted from the Lich King to Kel'thuzad.\n\nThis unholy power to raise the dead has now been passed to you, Deathlord. I am sure you will wield it with great conviction.\n\nThe Four Horsemen will be powerful allies against the Burning Legion... and Nazgrim is a worthy choice as the firstborn.", objectives = "" }
WordHunterWoW_QuestEN[42451] = { title = "Kalec's Plan", description = "Your champion was unable to penetrate very far inside the Arcway Vaults due to the heavy legion presence around it.  Hopefully you will have better luck following Archmage Vargoth inside.\n\nKalecgos will be waiting for you on the ridge overlooking Felsoul Hold.", objectives = "" }
WordHunterWoW_QuestEN[42452] = { title = "Finding Ebonchill", description = "Ebonchill bears a lineage of powerful wielders dating back to its maker, Alodi. He passed it on to his favorite apprentice and so on until... the archmage Arrexis, I believe.\n\nArrexis disappeared sometime around the First War. I know nothing of his fate, but the answer may well be somewhere in this library.\n\nStart by looking around here. Whatever you find should lead us to Ebonchill.", objectives = "" }
WordHunterWoW_QuestEN[42454] = { title = "The Hammer of Khaz'goroth", description = "<Now that you have defeated Dargrul the Underking and have the Hammer of Khaz'goroth in hand, it is time to place it in Aegwynn's Gallery in the lower chambers of Dalaran.>", objectives = "" }
WordHunterWoW_QuestEN[42455] = { title = "Alodi's Gems", description = "Arrexis had a cadre of apprentices and subordinates to help him with the ritual, something you are currently lacking.\n\nIn older times, when magic was less understood and spells required vast amounts of mana to cast, we stored mana in gems for use in complex spells.\n\nLucky for us, I still have a few powerful Mana Gems in my vault, along with some other useful items. You merely need to go to the Bank of Dalaran and gain access.", objectives = "" }
WordHunterWoW_QuestEN[42461] = { title = "Vanilla 10-19", description = "", objectives = "" }
WordHunterWoW_QuestEN[42463] = { title = "Legion 110 H", description = "", objectives = "" }
WordHunterWoW_QuestEN[42465] = { title = "Legion 110 H", description = "", objectives = "" }
WordHunterWoW_QuestEN[42476] = { title = "The Deadwind Site", description = "Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there.\n\nYou will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.", objectives = "" }
WordHunterWoW_QuestEN[42477] = { title = "Daio the Decrepit", description = "That text lists someone named Daio as being instrumental to the demonic ritual. They can't possibly mean Daio the Decrepit!\n\nI never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation.\n\nHe most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.", objectives = "" }
WordHunterWoW_QuestEN[42479] = { title = "The Mage Hunter", description = "And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly.\n\nI've heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won't want us to complete.\n\nThe chances of us dying horribly are exceptionally high.", objectives = "" }
WordHunterWoW_QuestEN[42483] = { title = "Put It All on Red", description = "All right, I've got one last beasty to send you after. He's a bit far out, but trust me, it'll be worth it. This one I put a huge wager on!\n\nAlong the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable.\n\nBut you're gonna prove them wrong, aren't ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.", objectives = "" }
WordHunterWoW_QuestEN[42484] = { title = "The Firstborn Rises", description = "General Nazgrim was one of the finest warriors our world has known, and his loyalty was unsurpassed... even for an orc.\n\nHe deserves the peace of death, but this world cries out to be saved. The time for rest is over...\n\nCome, Deathlord... let us welcome Nazgrim into the arms of the damned.", objectives = "" }
WordHunterWoW_QuestEN[42486] = { title = "Little One Lost", description = "I'm ready to go home now, but there are still scary men outside...\n\nWill you stay with me? Make sure they don't take me away?\n\nI don't want to go back in the cage...", objectives = "" }
WordHunterWoW_QuestEN[42487] = { title = "Friends On the Outside", description = "You have done well for us here, but it is time for you to return to Thalyssra.\n\nThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.\n\nOh, and before you go:\n\n<Vanthir hands you a wrapped bottle of Arcwine.>\n\nTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.\n\nWe are grateful beyond measure. Farewell for now.", objectives = "" }
WordHunterWoW_QuestEN[42488] = { title = "Thalyssra's Abode", description = "While you were busy in the city I reached a roadblock in my withered research. \n\nI feel I am close to overcoming this barrier, but I'm afraid I cannot do so without some more advanced tools.\n\nI hid among my possessions an item called an Arcane Amplifier. It does precisely what its name entails.\n\nIt is more than likely that the Magistrix ordered my estate dismantled. If the Amplifier remains, it will be in fragments.\n\nRecover the whole, if you can.", objectives = "" }
WordHunterWoW_QuestEN[42489] = { title = "Thalyssra's Drawers", description = "Thalyssra's ransacked estate still contains a number of items important to Thalyssra. Collect them and return them to her.", objectives = "" }
WordHunterWoW_QuestEN[42490] = { title = "The Arcway: Opening the Arcway", description = "Deep beneath Suramar is a defunct set of tunnels known as the Arcway. They were abandoned when a disaster disrupted the mana collectors operating there. \n\nI know not what awaits you down there, but I do know one thing.\n\nWe are not the only ones interested in this place. Make enough noise and one of the advisors with whom I served under Elisande is sure to appear.\n\nHis name is Vandros. Slay him, if you can.\n\nHis death will be our victory, as we deprive Elisande of one more weapon in her arsenal.", objectives = "" }
WordHunterWoW_QuestEN[42491] = { title = "The Arcway: Long Buried Knowledge", description = "Beneath Suramar City is an ancient network of tunnels known as the Arcway.\n\nThey were abandoned some time ago as part of the cavern became unstable. Since then, who knows?\n\nRegardless of what is currently down there, I believe you will find something essential to our continued success.\n\nLong ago my people took a thorough survey of the ley lines in and around Suramar. This they would have stored in the library in the Arcway. \n\nFind this map for me.", objectives = "" }
WordHunterWoW_QuestEN[42493] = { title = "Impending Dooooooom!", description = "Millhouse attracts trouble, so he's sure to find Archmage Vargoth if he's still here. \n\nOh and if you do find the Nightborne Soulstone, best get it first!", objectives = "" }
WordHunterWoW_QuestEN[42494] = { title = "More Than Just A Food Vendor", description = "Your champions made a good dent in thinning out the enemy's numbers. They also discovered a number of starving prisoners who could use our help. Your Conjured Mana Pudding or Fritters will be useful in getting them up on their feet. \n\nYou should also dispatch as many of the remaining legion invaders back to the twisting nether as you can!", objectives = "" }
WordHunterWoW_QuestEN[42501] = { title = "Finishing the Job", description = "Garona set out to assassinate the leaders of a Legion cult some time ago. We haven't heard from her since.\n\nTo make matters worse, she took the Kingslayers with her. She knows they bring out the worst in her!\n\nYour best bet to find Garona is by continuing her work. Our intel points to a warlock by the name of Caden Shadowgaze inducting new recruits at the Altar of Storms in Blasted Lands. See if he has anything useful in his pockets.\n\nOnce he's dead, I mean.", objectives = "" }
WordHunterWoW_QuestEN[42502] = { title = "No Sanctuary", description = "We have one other lead that may prove useful. Goes by Felcaller Whitley, another of the cult's elite. He's eluded our agents at every turn.\n\nOur latest reconnaissance report puts him somewhere in the village of Raven Hill in Duskwood. He's sure to have information vital to your search.\n\nYou know what to do.", objectives = "" }
WordHunterWoW_QuestEN[42503] = { title = "Codebreaker", description = "<The coded message you obtained is protected by powerful magic, rendering it indecipherable by conventional means.>\n\n<If you use the cipher you took from Felcaller Whitley you might be able to crack the code, leading you ever closer to both the cult's base of operations and Garona.>", objectives = "" }
WordHunterWoW_QuestEN[42504] = { title = "The Unseen Blade", description = "We can't let Stormwind fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own.\n\nThe two of us need to handle this while there's still time.\n\nThe entire city is on edge from murmurs of the cult's activities. They're as likely to turn on you as they are the cultists if you aren't careful.\n\nThe other Shadows spoke highly of your skills. Are you in?", objectives = "" }
WordHunterWoW_QuestEN[42508] = { title = "Not A Toothless Dragon", description = "The Arcway Vaults have been buried and untouched for thousands of years. We have the legion to thank for it being accessible once again, though I would give much for it to remain hidden.\n\nI think we are not far behind Archmage Vargoth's heels and he may yet be inside the vaults. We should make haste if we hope to intercept him.", objectives = "" }
WordHunterWoW_QuestEN[42510] = { title = "Immortal Soul", description = "Illidan's immortal demon soul is lost somewhere in the vastness of the Twisting Nether. Contacting him risks much, the Nether is full of creatures of unimaginable power and appetites. But, it must be done if we are to move forward.\n\nThe ritual can be performed using the nether crucible. Make the blood offering, {name}.", objectives = "" }
WordHunterWoW_QuestEN[42512] = { title = "Highmountain Stands", description = "That will have to do. Dargrul has come and we need every able body on the front line. Go, I will be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[42516] = { title = "Growing Power", description = "Archdruid Rensar Greathoof has requested your presence.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.", objectives = "" }
WordHunterWoW_QuestEN[42517] = { title = "Ritual of Doom", description = "Your research has granted you access to a very powerful ritual, one that will require the aid of a few friends if you wish to successfully summon a demon.\n\nThe ritual needs to be performed at the summoning platform above. \n\nKeep in mind, this sort of power always comes at a price. Not all who participate in the summoning will survive, so be prepared.", objectives = "" }
WordHunterWoW_QuestEN[42519] = { title = "Rise, Champions", description = "As leader of our order, other hunters will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary in the name of the Unseen Path.\n\nI know of two within our ranks who are impressed with what they've seen from you so far, and want to help any way they can.\n\nSeek them out, and let them ease the burden of leadership.", objectives = "" }
WordHunterWoW_QuestEN[42520] = { title = "A Terrible Loss", description = "I would say I am surprised by this terrible turn of events, but nothing surprises me of late. It is dark times when even the most upstanding of us can fall... \n\nWe had best inform Archmage Khadgar of Vargoth's betrayal.", objectives = "" }
WordHunterWoW_QuestEN[42521] = { title = "The Enemy of My Enemy...", description = "Millhouse Manastorm has been quite vociferous about his intention to acquire the Nightborne Soulstone. If you find him, you may as well make use of him. \n\nHowever, he is unpredictable at best and you should always watch your back around him, {name}. Use my crystal to contact me once you have located him.", objectives = "" }
WordHunterWoW_QuestEN[42522] = { title = "Leader of the Illidari", description = "Illidan has officially placed you in charge, {name}. The Illidari are now yours.\n\nMeet me upstairs. We will let everyone know together.", objectives = "" }
WordHunterWoW_QuestEN[42523] = { title = "Making Contact", description = "Now that we have recruited champions for our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.\n\nOver the years our scouts have kept a close eye on hunters that might one day be added to our ranks. One such hunter, Lenara, was on her way to Trueshot Lodge when she was attacked.\n\nI suggest that we send Loren Stormhoof on a mission to rescue her. He may be uniquely suited to this task.", objectives = "" }
WordHunterWoW_QuestEN[42524] = { title = "Recruiting The Troops", description = "Our champions acquired the talents of Recruiter Lenara, an extraordinary archer.\n\nShe can hit the smallest of targets at extended ranges. Her arrows never miss.\n\nSpeak to her now and train a squad of archers.", objectives = "" }
WordHunterWoW_QuestEN[42525] = { title = "Troops in the Field", description = "It's time to send our newly trained archers out into the field. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", objectives = "" }
WordHunterWoW_QuestEN[42526] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Survivalist Bahn. He spent his younger years living off the land in Pandaria, relying on the native flora and fauna to survive.\n\nHis firsthand experience with building from limited resources could really help shape Trueshot Lodge into something great.\n\nSpeak to him now and see what he can do for us.", objectives = "" }
WordHunterWoW_QuestEN[42533] = { title = "The Ruined Kingdom", description = "So the Lich King has revealed the second of the Four Horsemen... it appears that not even kings may rest as the world burns around them.\n\nSo be it, Deathlord.\n\nI will send Nazgrim and Thassarian to meet you at the fallen kingdom of Stromgarde.\n\nPrince Galen Trollbane holds the key to the tomb of his father, a famous sword known as Trol'kalar. In order to raise the king as the second of the Four Horsemen, we will need to gain entrance to the tomb.\n\nDo what you must to persuade Galen assist us...", objectives = "" }
WordHunterWoW_QuestEN[42534] = { title = "Our Oldest Enemies", description = "I will grant the Ebon Blade access to my father's tomb. First though, I must ask a favor.\n\nI have taken up the sword and banner of my father. I have reclaimed Stromgarde with its former citizens as my guard. Yet, one task remains.\n\nWitherbark invaders have blockaded themselves in the former mage district of the city. My men have suffered heavy losses at their vile hands.\n\nCut them down to the last! Bring me their heads and I shall give you what you seek.\n\nYou have my word as the King of Stromgarde.", objectives = "" }
WordHunterWoW_QuestEN[42535] = { title = "Death... and Decay", description = "My family has fought the Witherbark trolls for generations... their presence in Arathi has always been a curse upon the land. I want to drive them out of Stromgarde for good!\n\nDestroy their supplies and we shall give them no incentive to return. Blight their supplies... or whatever it is you death knights do to defile things. I care not.\n\nJust make sure that it is done!", objectives = "" }
WordHunterWoW_QuestEN[42536] = { title = "Regicide", description = "Galen Trollbane is a fool if he thinks that he can betray the Ebon Blade.\n\nI have had enough of his games. The fallen prince wastes our time playing the king of a ruined throne, while heroes sacrifice their lives to save this world.\n\nIf Galen Trollbane will not open the tomb of his father, then we must take the sword and do it ourselves.\n\nIf he chooses to resist, so be it.", objectives = "" }
WordHunterWoW_QuestEN[42537] = { title = "The King Rises", description = "King Thoras was one of the greatest warriors this world has known.\n\nHis people loved him and his enemies feared him. He only ever spoke truth, often saying the words others were afraid to speak.\n\nKing Thoras lived a life of war and he certainly deserves the peace of death. But this is not a man who would sleep peacefully while the world around him burns.\n\nThe time has come, Deathlord, to welcome the last true King of Stromgarde into the arms of the dead and damned.", objectives = "" }
WordHunterWoW_QuestEN[42539] = { title = "Cloak and Dagger", description = "<The cultists seem to have a base of operations in Darkshire. At least Althea Ebonlocke is a member, but it is likely that the entire Night Watch has been compromised.>\n\n<The best course of action for now is to retrieve the dark implements for their ritual and make an attempt on Althea's life. Garona will have to wait.>", objectives = "" }
WordHunterWoW_QuestEN[42567] = { title = "Cursed to Wither", description = "So Cedonu said he saw nightfallen going into Leyhollow?\n\nI don't like the sound of that.\n\nGrandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.", objectives = "" }
WordHunterWoW_QuestEN[42568] = { title = "Preparation", description = "<With Althea's escape there is only one place to go: Stormwind.>\n\n<If Garona is keeping a similar pace on the cult's trail, she's bound to be making preparations to enter the city herself.>\n\n<Finding her is paramount before moving into the city.>", objectives = "" }
WordHunterWoW_QuestEN[42583] = { title = "Rise, Champions", description = "The Legion's defeat cannot be accomplished alone.\n\nTo win this war, we must work together, just as we did in ancient times.\n\nTo begin, we must recruit more druids to our aid. Speak to the troll Zen'tabra and the night elf Naralex.\n\nBoth of them are accomplished druids. They will gladly defend the Dreamgrove.", objectives = "" }
WordHunterWoW_QuestEN[42584] = { title = "Sister Lilith", description = "We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we've received word that she may be in trouble.\n\nSend Zen'tabra to her aid.", objectives = "" }
WordHunterWoW_QuestEN[42585] = { title = "Recruiting the Troops", description = "In our champions' travels, they made contact with Sister Lilith, a fearless leader among the Laughing Sisters.\n\nShe is revered among the dryads as a seasoned warrior and a demanding teacher. She will serve as an excellent recruiter.\n\nSpeak to her now, and recruit some Treants.", objectives = "" }
WordHunterWoW_QuestEN[42586] = { title = "A Glade Defense", description = "We have a new mission that needs our attention, Archdruid. Deep in the forests of Val'sharah, a small druidic outpost known as Shal'doren Grove is under attack by satyrs.\n\nSend our champions to deal with this threat at once, {name}. We cannot allow these satyr incursions to grow unchecked!", objectives = "" }
WordHunterWoW_QuestEN[42588] = { title = "Branching Out", description = "Leafbeard is known as the Storied for good reason.\n\nIt is said that he remembers tales from before the Sundering. After examining the inscribed leaf that our champions recovered, he may be able to provide new knowledge and improvements for the grove.\n\nGo take it to him now.", objectives = "" }
WordHunterWoW_QuestEN[42590] = { title = "Moozy's Reunion", description = "You will never know how thankful we are to you, {race}. Because of you, Moozy and my husband are safe. I won't let either of them out of my sight!\n\nI am sorry to ask one last favor of you, but do you think you could find my mother and bring her here so she can see that her grandchild is safe?\n\nHer name is Ethel, and her home is on the northern bluff of Thunder Totem.", objectives = "" }
WordHunterWoW_QuestEN[42593] = { title = "The Arcane Way", description = "Getting into the Black Temple is going to be tricky. Following the break-in by the Council of the Black Harvest, Akama had his Sha'tari priests erect a holy barrier. It prevents my teleportation.\n\nHowever, I might know a way to bypass those protections and take us directly to the Temple Summit.\n\nLong ago, I had a... liaison with a certain high elf wizard named Lan'dalock. He later joined the Kirin Tor.\n\nIf you were to ask him very nicely, and drop my name, I am certain that he would help.", objectives = "" }
WordHunterWoW_QuestEN[42594] = { title = "Move Like No Other", description = "Sorry about the holographic projection... I literally need to be in two places at once these days.\n\nA holy barrier that protects against fel magic, you say? I have just the thing to bypass it and enable Malevolence's teleport.\n\n<The high elf rummages around in his pack, a shocked look quickly coming over his face.>\n\nSneaky! Look there... that imp just made off with it!", objectives = "" }
WordHunterWoW_QuestEN[42596] = { title = "Mountainstrider Round-Up", description = "Stranger! You are the one I have heard of?\n\nWhen the kerfuffle with the drogbar happened, some of the young moose ran off!\n\nI can't chase them down or the others might wander off as well.\n\nCould you bring them back here?", objectives = "" }
WordHunterWoW_QuestEN[42597] = { title = "Odyn's Summons", description = "Odyn would like to speak to you at once, my liege.\n\nHe is convinced that as you have grown in power you are ready to take direct command of his armies and would like to begin preparations.", objectives = "" }
WordHunterWoW_QuestEN[42598] = { title = "Champions of Skyhold", description = "You will soon command one of the greatest armies in existence, but before my own Valarjar follow your every command you must prove your ability to lead.\n\nSpeak to the two vrykul champions who ascended into these halls with you and tell them it is time for you to assume your duties as Odyn's chosen.", objectives = "" }
WordHunterWoW_QuestEN[42601] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Archivist Melinda. She is somewhat of an anomaly, as not many from her race choose our path. What makes her even more unique is her meticulous study of our craft. Her knowledge will be unsurpassed.\n\nSpeak to her now and seek her council. With her help, we can surely strengthen the council.", objectives = "" }
WordHunterWoW_QuestEN[42602] = { title = "Troops in the Field", description = "It's time to send our newly trained imps out into the field. Look at the Dreadscar Battle Plans and send your champions and troops on a routine scouting mission.", objectives = "" }
WordHunterWoW_QuestEN[42603] = { title = "Information at Any Cost", description = "Now that you've found other warlocks that are willing to aid your cause, we can use the Dreadscar Battle Plans to complete vital assignments across the Broken Isles.\n\nIf we wish to rebuild the council, we must start by locating its missing members.\n\nLet us send Ritssyn and Calydus to interrogate the Burning Legion's minions. They might have information that will help us locate the missing council members.", objectives = "" }
WordHunterWoW_QuestEN[42605] = { title = "Champion: Ragnvald Drakeborn", description = "", objectives = "" }
WordHunterWoW_QuestEN[42606] = { title = "Champion: Finna Bjornsdottir", description = "", objectives = "" }
WordHunterWoW_QuestEN[42607] = { title = "Captain Stahlstrom", description = "The souls that make it to these halls are brave, yes. That's why they're here after all.\n\nValor alone does not make for an effective army, however. You will need someone who can train those who would be valarjar to fight with discipline.\n\nHave your champions send word to Captain Stahlstrom. Unruly vrykul berserkers may not fear death, but they might fear Hjalmar Stahlstrom enough to make them follow your orders.", objectives = "" }
WordHunterWoW_QuestEN[42608] = { title = "Rise, Champions", description = "Friend is in a powerful, but lonely position. First of a council whose members are missing.\n\nFriend does not have to be alone though. Others will be drawn to friend's power, willing to follow if friend leads.\n\nFind those who want to help, and accept their pledge of loyalty.", objectives = "" }
WordHunterWoW_QuestEN[42609] = { title = "Recruiting the Troops", description = "Captain Stahlstrom has arrived. It would be advisable to speak to him and see that the valarjar are armed and ready for battle.\n\nWe'll need more than your two champions if we're to win a full-fledged war against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[42610] = { title = "Troops in the Field", description = "Our enemies' transgressions have gone unchecked for long enough. Now that we have troops to back your champions, you would do well to send them to deal with them.\n\nOne of our own has been taken prisoner by Odyn's sworn nemesis, Helya. If your forces manage to bring back Einar the Runecaster alive he can aid us in using powerful runes to advance the power of your armies.", objectives = "" }
WordHunterWoW_QuestEN[42611] = { title = "Einar the Runecaster", description = "Being a leader is not just about sending your troops to combat. You will also make decisions about how we train and improve our armies.\n\nSpeak to Einar the Runecaster and let him know how you would like development to progress.", objectives = "" }
WordHunterWoW_QuestEN[42614] = { title = "Champion: Svergan Stormcloak", description = "", objectives = "" }
WordHunterWoW_QuestEN[42616] = { title = "Champion: Dvalen Ironrune", description = "", objectives = "" }
WordHunterWoW_QuestEN[42618] = { title = "Champion: Thorim", description = "", objectives = "" }
WordHunterWoW_QuestEN[42619] = { title = "Champion: Hodir", description = "", objectives = "" }
WordHunterWoW_QuestEN[42622] = { title = "Ceremonial Drums", description = "Those foolish calves!\n\nThey've made off with our ceremonial drums again, treating them as toys... as... common drums!\n\nCan you help me find them? They must be scattered to all corners of Thunder Totem by now, discarded as soon as the fun dries up.", objectives = "" }
WordHunterWoW_QuestEN[42627] = { title = "The Unseen Blade", description = "Stormwind is too important to fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own.\n\nThe two of us will have to handle this while there's still time.\n\nUse extreme caution. The entire city is on edge from murmurs of the cult's activities, and we're already kill on sight.\n\nThe other Shadows spoke highly of your skills. Are you in?", objectives = "" }
WordHunterWoW_QuestEN[42630] = { title = "Bolas Bastion", description = "I received word that a coven of harpies and their rocs plan to attack in force.\n\nThey'll be coming from the mountains to the north.\n\nUse one of the bolas launchers and I'll man the other.\n\nQuick!", objectives = "" }
WordHunterWoW_QuestEN[42634] = { title = "Confrontation at the Black Temple", description = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers.\n\nI will need but a moment to summon a gateway. Stand back, please.", objectives = "" }
WordHunterWoW_QuestEN[42635] = { title = "The Mystery of Dreyrgrot", description = "Well met, good chap!\n\nI was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they've unleashed some ancient evil.\n\nI would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps.\n\nI spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.", objectives = "" }
WordHunterWoW_QuestEN[42639] = { title = "A Stone of Blood", description = "Unfortunately, we may have another problem. That mist seeping out of the ruins has affected the looting pirates. It's driven them quite mad.\n\nOnly one of them seems to be unaffected - a captainly fellow with a very fine hat.  He wears a large ruby amulet, which I believe protects him from the mist. You'll need it if you are to enter the tomb.\n\nHe may not give it up willingly.", objectives = "" }
WordHunterWoW_QuestEN[42640] = { title = "The Value of Knowledge", description = "This crate is filled with relics from the nearby ruins. The pirates have discarded them, likely thinking they're of little value.\n\nThe Explorers' League would probably appreciate if you retrieved these relics for them to study.", objectives = "" }
WordHunterWoW_QuestEN[42641] = { title = "What the Bonespeakers Buried", description = "Most Fascinating! It would appear that we're dealing with our very own vrykul vampyr!\n\nAll we have encountered have been of blood elven descent, but it has long been theorized that the vrykul have suffered the curse as well. It's too bad he's awake - I would dearly like a subject to study.\n\nOh well, guess there's nothing for it. Take this stake and put it through the old chap's heart. I'm pretty sure that should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[42645] = { title = "Spilling Bad Blood", description = "Ending the evil of the Blood Prince will be a boon to this land, but we can't just allow these crazed corsairs to run amok.  I'm afraid there is no choice but to put them to the sword.\n\nCarry out this noble deed, my good fellow, and we will celebrate with a nice warm lager.", objectives = "" }
WordHunterWoW_QuestEN[42650] = { title = "Break the Bonds", description = "The Bonespeaker mystics used these heirlooms to tie my soul to this world.\n\nUnder their curse, my soul could not enter the Halls of Valor. Find the soul pyre in Haustvald and throw my belongings into the flames.\n\nThe fire that bound my soul through their foul magic will be the same fire that undoes this bond!", objectives = "" }
WordHunterWoW_QuestEN[42651] = { title = "Svergan's Promise", description = "I thank you for doing this for me. I swore an oath to protect the Gjallarhorn with my life, and so I did.\n\nYou must tell Hymdall that his Gjallarhorn was devoured by the great worm, Jorhuttam!\n\nIt devoured an entire army of my men who were swallowed whole trying to fend off the beast. Find Jorhuttam and you will find the horn!", objectives = "" }
WordHunterWoW_QuestEN[42653] = { title = "Champion: Akama", description = "", objectives = "" }
WordHunterWoW_QuestEN[42654] = { title = "Darkheart Thicket: Nightmare Oak", description = "Blacksmith Kyriel is no stranger to the Farstriders. He has forged countless arrows for us in the past, using his knowledge of unique materials to help build better, stronger ammo.\n\nHe's efficient and gifted, making the most of scarce materials.\n\nUsing a single branch from a corrupted ancient, he can craft thousands of arrows.", objectives = "" }
WordHunterWoW_QuestEN[42655] = { title = "Ore Under the Sea", description = "If we want to bring the fight to Hakkar, my rangers are going to need arrows and ammo that are capable of piercing the thick, magic-resistant hides of his hounds.\n\nThere's a versatile smith in Dalaran who does incredible work with both bows and blades alike.\n\nHe uses azure ore in his creations, which can only be found below sea level.\n\nDue to its proximity to leystone, the ore is often overlooked, but in an expert smith's hands, it can be smelted into something nearly indestructible.", objectives = "" }
WordHunterWoW_QuestEN[42656] = { title = "Azure Weaponry", description = "Take the materials to Blacksmith Kyriel in Dalaran, and he'll use them to craft whatever weapons he can.\n\nAs I mentioned before, he's skilled and efficient, so you shouldn't have to wait long.\n\nWhen his work is complete, speak to Shandris Feathermoon about getting the weapons enchanted.", objectives = "" }
WordHunterWoW_QuestEN[42657] = { title = "Meeting in Moonclaw Vale", description = "Lyana Stardust still lingers in a vale that has been overrun by demons. Despite its current start of upheaval, she refuses to abandon her home.\n\nThe strength and stubbornness she exhibits in the face of an enemy are also traits that shine through in her enchantments.\n\nWe want our weapons to be as strong and stubborn as she is.\n\nMeet her in Moonclaw Vale, and see if she can work her magic with the weapons that Kyriel has crafted for us.", objectives = "" }
WordHunterWoW_QuestEN[42658] = { title = "Delicate Enchantments", description = "As I'm sure you've noticed, demons have taken over the vale. Their arrival has forced many of my fellow druids to flee their homes, but I refuse to go down without a fight.\n\nDespite all this, I'm happy to provide enchantments for your weapons, but you should know that it is a delicate process that takes time and concentration, something I have little of lately.\n\nIf you're willing to shelter me from attackers, I will certainly do my best to enchant your weapons.", objectives = "" }
WordHunterWoW_QuestEN[42659] = { title = "In Defense of Dalaran", description = "We have everything we need to set the trap for Hakkar.\n\nArchmage Khadgar will summon a portal to the Violet Hold. Once inside, he will begin to channel his essence into the arcane vessel at your command.\n\nOur allies will be armed with the weapons you brought them, ready to fight when Hakkar takes the bait.", objectives = "" }
WordHunterWoW_QuestEN[42660] = { title = "Vault of the Wardens: Matters of the Heart", description = "I have made considerable progress with the Bloodstone, thanks in part to your extensive testing.\n\nThe stone feeds on blood to grow in power, but its ability to control a demon comes from consuming a corrupted heart; the more powerful, the better.\n\nWithin the Vault of the Wardens you'll find someone with such a heart.", objectives = "" }
WordHunterWoW_QuestEN[42662] = { title = "Champion: Archmage Kalec", description = "", objectives = "" }
WordHunterWoW_QuestEN[42663] = { title = "Rise, Champions", description = "The Tirisgarde has been defunct for ages. To defeat the Burning Legion, we must first recruit the greatest champions of our class to fight by our side. Two powerful archmages, Archmage Kalec and Archmage Modera, have come to help us succeed. \n\nSpeak to them and enlist their aid.", objectives = "" }
WordHunterWoW_QuestEN[42664] = { title = "Champion: Shade of Akama", description = "", objectives = "" }
WordHunterWoW_QuestEN[42665] = { title = "Into Our Ranks", description = "We should make a show of welcoming this Shade of Akama into our ranks. It is important that the others see him treated as one of us, rather than as an outsider.\n\nKor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.\n\nIt is time to officially raise them up as champions.", objectives = "" }
WordHunterWoW_QuestEN[42666] = { title = "Return to the Fel Hammer", description = "{name}, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.\n\nHe requests your presence back on the Fel Hammer as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[42669] = { title = "Preparations for Invasion", description = "We have the Sargerite Keystone. We have most of the forces we will need. We even have a plan.\n\nNow we need to locate the Felsouls and prepare for an invasion of whatever demon world they're hiding out on.\n\nPlease leave it to me. If you will grant me the use of your champions, I and the Scythe of Souls will extract the information by any means necessary from the demons that we question.", objectives = "" }
WordHunterWoW_QuestEN[42670] = { title = "Rise, Champions", description = "The matron mother, Lady S'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider's perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.\n\nThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.\n\nOur unanimous recommendations for the first two are Altruis and Asha.", objectives = "" }
WordHunterWoW_QuestEN[42671] = { title = "Rise, Champions", description = "The matron mother, Lady S'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider's perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.\n\nThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.\n\nOur unanimous recommendations for the first two are Kayn and Asha.", objectives = "" }
WordHunterWoW_QuestEN[42673] = { title = "Champion: Kor'vas Bloodthorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[42677] = { title = "Things Gaardoun Needs", description = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that.\n\nTime to put your new champions to the test. I'm sure it will be a grueling mission.", objectives = "" }
WordHunterWoW_QuestEN[42678] = { title = "Black Rook Hold: Into Black Rook Hold", description = "This thing is ancient. Just turning the pages risks them disintegrating in my hands.\n\nHere, I have found it. An entry about the Raven's Eye.\n\n<Valeera traces her finger from left to right above the page. A look of discovery comes over her features, which is quickly replaced by a frown.>\n\nIt says here that the last person to have possession of the eye was Lord Ravencrest himself. You are going to have to go into Black Rook Hold and take it from him.", objectives = "" }
WordHunterWoW_QuestEN[42679] = { title = "Broken Warriors", description = "It's important that we increase our numbers. Trust me, I know these things. Battlelord Gaardoun and his Ashtongue warriors are our best bet to quickly accomplish such a task.\n\nYou should speak with him and let him know just what kind of broken you want trained.", objectives = "" }
WordHunterWoW_QuestEN[42680] = { title = "Deciphering the Letter", description = "We have the Raven's Eye. Use it, {name}. Decipher the SI:7 letter.\n\nWe must know what secrets it contains!", objectives = "" }
WordHunterWoW_QuestEN[42681] = { title = "Loramus, Is That You?", description = "Belath Dawnblade has given us a strange scouting report from the Felblaze Ingress in Azsuna. The dreadlord, Razelikh the Defiler has returned to the world. That's not the odd part, though.\n\nStrangely, he's sometimes going around killing the other demons and calling himself, Loramus!\n\nLast we knew, our demon hunter brother, Loramus Thalipedes sacrificed himself to defeat Razelikh, whom he'd been possessed by.\n\nYour champions and Ashtongue warriors need to go to Azsuna and find out what is going on.", objectives = "" }
WordHunterWoW_QuestEN[42682] = { title = "Additional Accoutrements", description = "I heard a rumor that you are going to attempt to make contact with Illidan's immortal demon soul in the Twisting Nether. You are going to need many magical things.\n\nI have taken the luxury of putting together a potential list for you. I do so hope that it proves helpful, handsome.", objectives = "" }
WordHunterWoW_QuestEN[42683] = { title = "Demonic Improvements", description = "Having Loramus back will work greatly to our advantage, despite the fact that he's trapped inside Razelikh's body... and also that the demon sometimes takes control.\n\nStill, he was one of our most powerful demon hunters. And now, he also has the knowledge of a dreadlord at his disposal.\n\nI think we should have him share his knowledge and wisdom with us to improve our odds in this war.", objectives = "" }
WordHunterWoW_QuestEN[42684] = { title = "Throwing SI:7 Off the Trail", description = "SI:7 is dogging our heels at every turn. We must make certain that they do not catch wind of what we are up to.\n\nTo that end, I have some suggestions for you in the form of missions. Send your champions, assign your forces, it matters little to me. The important thing is that we keep them out of Val'sharah and away from Black Rook Hold.\n\nAt least until we can decipher that damned letter.", objectives = "" }
WordHunterWoW_QuestEN[42685] = { title = "Champion: Archmage Modera", description = "", objectives = "" }
WordHunterWoW_QuestEN[42687] = { title = "Troops in the Field", description = "Our troops are ready! It's time to test them out in the field.\n\nWe've received word of survivors near the Broken Shore, but the area is still crawling with Legion.\n\nSend our troops quickly to help with the rescue!", objectives = "" }
WordHunterWoW_QuestEN[42688] = { title = "Mrgls of Endearment", description = "Mrmlgr! Mrglr rlmgrg mlrgr! Mrlgmr...\n\n<Phin shows you a flaw on the side of the pearl.>\n\nMmlrgmlr rlmgr grlmrmlg mglrmglr. Mlrgmrl rmglr? Mlgrmglr!\n\nGmmlrgmrl mlrgmlr lrglrmgrl lrlgllrlm mglrlr grlm-grlm.\n\n<Phin makes a pinching motion with his hand.>\n\nMrlgmlgr mgrlmlgr? Mlrgmlr gmrlmglr Mrgrlilgrl.", objectives = "" }
WordHunterWoW_QuestEN[42689] = { title = "Knowing Our Enemy", description = "If we hope to gain the upper hand against Hakkar, we need to find out more about these hounds that he's breeding and pinpoint their weaknesses.\n\nI know of a warlock that studies demons extensively. Maybe she has seen some of these hounds, and knows how to defeat them.", objectives = "" }
WordHunterWoW_QuestEN[42690] = { title = "Champion: Altruis the Sufferer", description = "", objectives = "" }
WordHunterWoW_QuestEN[42691] = { title = "Leyworm Lure", description = "Felhounds are attracted to magic, young ones especially.\n\nThey get a whiff and go into a feeding frenzy! You're not quite as enticing as a mage, so you'll need to cover yourself in something that can fool a felhound into thinking you're its next magical meal.\n\nLeyworm entrails should do the trick.", objectives = "" }
WordHunterWoW_QuestEN[42692] = { title = "Children of Nar'thalas", description = "Hi! {name}, right? The archmages in Dalaran said we might see you down here.\n\nMy brother and I are here on a reconnaissance mission. We're looking for our parents.\n\nWe've lived our entire lives thinking that our family was killed in Azsuna several thousand years ago, but look around! Most of the elves here are ghosts.\n\nOlothil's been searching through books for clues as to why, but we could use some help.", objectives = "" }
WordHunterWoW_QuestEN[42693] = { title = "You Never Know Until You Scry", description = "In order to find the spirits of our family, I will need materials to scry their location.\n\nThe naga carry magical trinkets imbued with ley energy that is better-attuned to this land than anything we have in Dalaran. If I had a few of those, I could do some real scrying.", objectives = "" }
WordHunterWoW_QuestEN[42694] = { title = "Back from the Dead", description = "<Olothil sighs.>\n\nMy sister tries my patience sometimes.\n\nNo matter. I've identified a few locations that our parents might be. I shall search in this area with Kallistia. You've already helped us so much... would you help us look to the east?\n\nYou can use my scrying orb to see the locations that our ritual has uncovered.", objectives = "" }
WordHunterWoW_QuestEN[42695] = { title = "Champion: Kayn Sunfury", description = "", objectives = "" }
WordHunterWoW_QuestEN[42696] = { title = "Tech It Up A Notch", description = "Thanks to you, the Hall of the Guardian is gradually re-assembling.\n\nHowever, there is much more work to do. As our leader, you can determine the trajectory of our order's future.\n\nSpeak to Chronicler Elrianne. She will show you the ropes.", objectives = "" }
WordHunterWoW_QuestEN[42697] = { title = "Champion: Asha Ravensong", description = "", objectives = "" }
WordHunterWoW_QuestEN[42701] = { title = "Champion: Matron Mother Malevolence", description = "", objectives = "" }
WordHunterWoW_QuestEN[42702] = { title = "Champion: Millhouse Manastorm", description = "", objectives = "" }
WordHunterWoW_QuestEN[42703] = { title = "Technical Wizardry", description = "Now that you have your first two champions, there is an abundance of work they can do to help us.\n\nArchmage Melis has been hard at work getting our command room up and running. Head downstairs and ask her to show you what needs to be done.", objectives = "" }
WordHunterWoW_QuestEN[42704] = { title = "Champion: Arcane Destroyer", description = "", objectives = "" }
WordHunterWoW_QuestEN[42705] = { title = "Champion: Ravandwyr", description = "", objectives = "" }
WordHunterWoW_QuestEN[42706] = { title = "Champion: Esara Verrinde", description = "", objectives = "" }
WordHunterWoW_QuestEN[42707] = { title = "Eye of Azshara: A Magical Affliction", description = "Archmage Vargoth's betrayal is an unimaginable loss to our cause, {name}. We will have to deal with him, but first Meryl's condition has become dire. \n\nUnfortunately it is not an illness at all, but a magical attack of fel origin. It may be his old nemesis Kathra'natir is behind it. We need to buy him time.\n\nThe Eye of Azshara contains a vast store of arcane energy from Queen Azshara herself. If we could obtain a vial of water from the Wrath of Azshara's body, that will sustain him for a while.", objectives = "" }
WordHunterWoW_QuestEN[42708] = { title = "A Personal Request", description = "If you have a moment, Deathlord... there is a personal matter I would like to speak with you about.\n\nSome time ago, a brother of the Ebon Blade was imprisoned beneath the ruins of Lordaeron by the Dark Lady.\n\nSylvanas has refused all attempts to negotiate his release. Now, our world faces destruction and the time for diplomacy has passed.\n\nKoltira Deathweaver cannot fight the Burning Legion in chains.\n\nSo we will break them.", objectives = "" }
WordHunterWoW_QuestEN[42719] = { title = "Eye of Azshara: Cleansing the Dreamway", description = "Brightwing has lots of friends. I like friends!\n\nBut you know who isn't Brightwing's friend? Scary monsters from the nightmare!\n\nThey hurt Brightwing's allies, and they made the grove all yucky!\n\nThis place needs to be cleansed, but I'm all out of magic.\n\nCan you bring Brightwing some purified water to help? You'll have to go far, far away... to the Eye of Azshara where the naga live.", objectives = "" }
WordHunterWoW_QuestEN[42722] = { title = "Friends in Cages", description = "<Korine stomps her foot and refuses to move.>\n\nThey put my friends in cages!\n\nMake the bad men stop hurting them! They take them out the garden and they never come back!\n\n<Korine gestures stubbornly toward the door.>\n\nI am not going home until they do!", objectives = "" }
WordHunterWoW_QuestEN[42728] = { title = "A Mlrglrmg For Grlmrgl", description = "Mrglm, rmgrlg mrlgmrl.\n\nGrmrglmrl mlrmglrgr mlrmlgr! Rglrmgl rmglrgmlr mlmlglr mglgrgrlm - grlgmr, mlgr - lrgmlrgr rmgrmlg mlrg! Mlrgr?\n\nMrlgmrlgmrl rmglrmglr!\n\n<Pearlhunter Phin makes a stabbing motion.>", objectives = "" }
WordHunterWoW_QuestEN[42730] = { title = "Noggenfogger's Reasonable Request", description = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible.\n\nMarin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor.\n\nOf course, if you would rather, I can eliminate him.", objectives = "" }
WordHunterWoW_QuestEN[42731] = { title = "Working With the Wardens", description = "As much as we might not like it, we need the aid of the Wardens if we're to locate the Sargerite Keystone. They took it from you when we were all imprisoned in the vault.\n\nWith Maiev missing, their current leader is Sira Moonwarden. On your behalf, I have agreed that we will assist them in tracking down some of the more powerful creatures that escaped from the Vault of the Wardens. In return, she will direct us to where we need to go to get the Keystone.", objectives = "" }
WordHunterWoW_QuestEN[42733] = { title = "A Very Special Kind of Fuel", description = "All Legion constructs, including the Fel Hammer, are powered by souls. If we are going to take the command center to Niskara, we are going to need some very powerful souls, indeed!\n\nYou are a very creative person, {name}. I am certain that you will find a way to get what we need from the right sorts of creatures.", objectives = "" }
WordHunterWoW_QuestEN[42734] = { title = "Into the Oculus", description = "I fear Kathra'natir is behind the attack on Meryl. We have little time to act. \n\nI suspect Archmage Vargoth's involvement is no coincidence. While it greatly pains me to destroy an archmage of his caliber and worse, someone I once called friend, we cannot permit his betrayal to stand unpunished. \n\nIt is time to follow him into the Oculus.", objectives = "" }
WordHunterWoW_QuestEN[42735] = { title = "Malace in Vrykul Land", description = "I did some recon in Stormheim. What I discovered is that the Tideskorn are a tribe of vrykul who have been cut-off from the sea by their kvaldir brethren. Many of the Tideskorn have pledged their services to the Legion and become Felskorn.\n\nMalace Shade was last seen heading toward the Felskorn Warcamp. It is likely that she was captured.\n\nI have arranged a flight to Stormheim for you. When you are ready, you can use the gateway to travel to Dalaran and speak with Aludane Whitecloud at Krasus' Landing.", objectives = "" }
WordHunterWoW_QuestEN[42736] = { title = "Rune Ruination", description = "A cage wasn't enough to hold me, so the vrykul ensorcelled these runestones to trap me in here. Each is powered by a different Felskorn rune.\n\nUnfortunately, they gave the runes to different guardians, who have all scattered to different places around Stormheim.\n\nSo, if Sira said that you could have your precious keystone back, you're first going to have to get me out of here.\n\nThen, we'll see.", objectives = "" }
WordHunterWoW_QuestEN[42737] = { title = "Rune Ruination: Runeskeld Rollo", description = "<Collect the rune from Runeskeld Rollo to deactivate this runestone.>", objectives = "" }
WordHunterWoW_QuestEN[42738] = { title = "Rune Ruination: Runelord Ragnar", description = "<Collect the rune from Runelord Ragnar to deactivate this runestone. If you do not already have one, obtain a grapple launcher in order to scale the walls of Hrydshal.>", objectives = "" }
WordHunterWoW_QuestEN[42739] = { title = "Rune Ruination: Runesage Floki", description = "<This runestone is entrapping Malace Shade. It can only be destroyed by using Runesage Floki's rune upon it.>", objectives = "" }
WordHunterWoW_QuestEN[42740] = { title = "The Battle for Broken Shore", description = "This is your vessel, {name}. She's a fine ship; been through many a campaign. Speak with the ship's captain when you're ready to depart.\n\nGood luck out there. We've received few reports about what's happening at the Broken Shore, but I'd wager King Varian has matters well in hand.", objectives = "" }
WordHunterWoW_QuestEN[42747] = { title = "Where the Wildkin Are", description = "Owlbeasts are often charged with protecting places of importance to Elune. But if her influence over them wanes or is cut off, the creatures can become dangerous.\n\nThese wildkin, unfortunately, must be dealt with. The recent disturbances in Val'sharah have driven these creatures to madness.\n\nOnce an individual is lost, there is only one way to address the problem.\n\nI cannot bring myself to kill one of Elune's creations, but I know what must be done.", objectives = "" }
WordHunterWoW_QuestEN[42748] = { title = "Emerald Sisters", description = "The owlbeasts here are disconnected from Elune.\n\nA contingent of dryads went into their territory to find out what went wrong, but none of them have returned.\n\nI fear the worst, and I believe they are  in need of rescue.\n\nWhile I try to learn if the owlkin can be saved, I would appreciate your help in freeing any Sisters you find in the grotto.", objectives = "" }
WordHunterWoW_QuestEN[42749] = { title = "Strange Bedfellows", description = "The reason why I came out here was to capture or kill a fel lord named, Lochaber. I am no longer in a capturing mood.\n\nI'll grab my weapon and then head up to the bridge in front of the Gates of Valor. That place is a scary mess full of Felskorn vrykul and demons.\n\nHow do you think I got caught?\n\nSo, I'd rather not go back in there. But, I think I know a way to get the demon to come out to us.", objectives = "" }
WordHunterWoW_QuestEN[42750] = { title = "Dreamcatcher", description = "I cannot hold on for much longer...\n\nI brought a dreamcatcher with me. I was to use it to steal the magic from owlbeast totems.\n\nIt is the only way to break the barrier where they hold Keeper Remulos.\n\nPlease help where I have failed.", objectives = "" }
WordHunterWoW_QuestEN[42751] = { title = "Moon Reaver", description = "We must not delay! If Keeper Remulos is in danger, he must be protected.\n\nWith the dreamcatcher, we should be able to enter the lair of the owlbeast Boneflux.\n\nIt must be defeated so Keeper Remulos can break free!", objectives = "" }
WordHunterWoW_QuestEN[42752] = { title = "Vault of the Wardens: Vault Break-In", description = "<All that is left now is to travel to the Isle of the Watchers off of southwest Azsuna. There, you will need to break back in to the Vault of the Wardens and descend down into its lowest recesses where once you were imprisoned.>\n\n<Within the so-called Vault of the Betrayer, where the Wardens once held Illidan's corpse, the Sargerite Keystone awaits.>", objectives = "" }
WordHunterWoW_QuestEN[42753] = { title = "Vault of the Wardens: Vault Break-In", description = "The Wardens made good on the deal. All that's left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you'll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned.\n\nWithin the so-called Vault of the Betrayer, where the Wardens once held the Master's corpse, you'll find Sargerite Keystone.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[42754] = { title = "Jump-Capable", description = "While it is true that the Fel Hammer is powered, sadly, its jump engines are non-functional. If we are going to invade a demon world, we're going to have to make the command center jump-capable.\n\nWe need some replacement parts.\n\nLuckily for us, the Legion brought a couple of command centers and soul engines along with them to the Broken Isles. You will find them at Faronaar in Azsuna, and at Felsoul Hold in Suramar.", objectives = "" }
WordHunterWoW_QuestEN[42756] = { title = "Hunger's End", description = "I am weak. The hunger is devastating, my friend. I understand now why your dragon rests in these pools.\n\n<cough, cough>\n\nI came to warn you but... it looks like I was too late.\n\nI hear him outside now. Ael'Yith... is... here...", objectives = "" }
WordHunterWoW_QuestEN[42758] = { title = "You're Gonna Need A Bigger Boat!", description = "Sharks. They be the biggest threat to us pirates. Well... after scurvy, ninjas, and the judicial system. Luckily, we only have to deal wit' sharks today.\n\nGo pull some teeth out of their ugly faces 'n bring 'em back to me. I needs a new necklace!", objectives = "" }
WordHunterWoW_QuestEN[42762] = { title = "The Wanderer's Companion", description = "Fu Zan... a wise choice. If the legends are true, its powers will be essential to our cause.\n\nWe believe that the staff possessed by the Monkey King could be fabled Fu Zan, yet no one has seen him with the weapon for over a year.\n\nThe Monkey King was last spotted at Tian Monastery. Be prepared for anything! He is known for being... less than forthcoming with his answers.\n\nTak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", objectives = "" }
WordHunterWoW_QuestEN[42765] = { title = "The Trial at the Temple", description = "My staff was strong and mighty without peer, but since I not its master, in time it would soon disappear.\n\nThe staff was a gift from the Jade Serpent, Yu'lon, but for only a single task. With my work finished, to her again it has passed.\n\nYu'lon be the staff's keeper, holding it for those who are blessed. To her we now go now, to announce your request.", objectives = "" }
WordHunterWoW_QuestEN[42766] = { title = "The Riddle of the Barrel", description = "My weapon is great when in a fight,\nIt's even handy when you sit for a bite.\n\nMy favorite flask I've tied on it, hanging from a cord,\nThe brews within are some of the best that I've ever scored.\n\nIf you truly seek my weapon then bring me something nice to put into my belly,\nA powerful brew is what I want, something strong and smelly.", objectives = "" }
WordHunterWoW_QuestEN[42767] = { title = "The Riddle of the Land", description = "My weapon is strong but not for attacking, \nProtecting the weak is what it's enacting.\n\nIn the valley are people who till the land from dawn to night,\nThe fruits of their labor, you must show me tonight.\n\nSacks of grain are what I require,\nNot just any will do, only those kissed by a fire.\n\nBring me what I seek.", objectives = "" }
WordHunterWoW_QuestEN[42768] = { title = "The Riddle of Purity", description = "Do you seek my weapon? Then you better answer my question.\n\n  \"I seek something curvy and bendy but with no spine,\n\n   It rushes and rushes leaving chaos behind.\n\n   Sometimes it brings life, sometimes it brings death:\n\n   A little is good, but a lot steals your breath.\n\n   It's as common as dirt, but this part's obscure:\n\n   This stuff comes from a pool that's known to be pure.\"\n\nBring me what I seek.", objectives = "" }
WordHunterWoW_QuestEN[42770] = { title = "Seeking Guidance", description = "Highlord Tirion may be gone, but the Ashbringer is still out there somewhere. Its power would devastate the Legion. We must find it!\n\nI wish it were as simple as returning to where Tirion fell. It could be anywhere on that infernal landscape by now.\n\nI believe an old friend can help us find the blade. I ask that you place your faith in me and journey to Uther's tomb in the Plaguelands. We will seek answers there.", objectives = "" }
WordHunterWoW_QuestEN[42771] = { title = "Keeping the Peace", description = "The lost souls roaming the cemetery grounds have been drawn to the realm of the living in the wake of the Light's disturbance. In truth, they merely seek comfort... as we all do in these dark times since Highlord Tirion's passing.\n\nHowever, their unrest threatens the very sanctity of the tomb we have sworn to protect. If we are to restore peace here, then they must be exorcised.", objectives = "" }
WordHunterWoW_QuestEN[42772] = { title = "Sacred Ground", description = "We must ensure that those buried here are never again disturbed. Their spirits' very presence only further perturbs the Light.\n\nThis cannot continue.\n\nI must maintain this barrier to ensure none of the wayward souls enter the Lightbringer's resting place. If you can purify the graves themselves, this madness can finally cease.", objectives = "" }
WordHunterWoW_QuestEN[42773] = { title = "The Light Reveals", description = "We seek aid not from a living friend, but one who passed long ago.\n\nUther the Lightbringer was more attuned to the subtleties of the Light than any paladin I've ever known. If we reach out to him, he may be able to help us find the Ashbringer.\n\nThe ceremony has been prepared. Approach the tomb when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[42774] = { title = "Hope Prevails", description = "Tirion... still alive! We have to save him.\n\nLight's Hope Chapel is not far from here. We must rally our forces and leave at once for the Broken Shore.", objectives = "" }
WordHunterWoW_QuestEN[42775] = { title = "The Crux of the Plan", description = "We have Akama. Cordana Felsong has been eliminated. And, we have the Sargerite Keystone.\n\nEverything is falling into place.\n\nThe honor is all yours, {name}.", objectives = "" }
WordHunterWoW_QuestEN[42776] = { title = "Two Worthies", description = "As our forces grow, and our reach extends ever outward, you have need of more trusted companions to handle the most important of missions.\n\nThe time has come for you to elevate two worthies into the ranks of your champions. \n\nIt's my opinion that you should consider recruiting Belath and Malevolence. They have both proven themselves indispensable.", objectives = "" }
WordHunterWoW_QuestEN[42777] = { title = "Champion: Belath Dawnblade", description = "", objectives = "" }
WordHunterWoW_QuestEN[42782] = { title = "To Be Prepared", description = "Allies from across Azeroth have come to Stormwind to support our efforts against the Burning Legion.\n\nBefore you ship out, you should pay them a visit. Every bit of preparation helps!", objectives = "" }
WordHunterWoW_QuestEN[42786] = { title = "Grotesque Remains", description = "These grotesque remains are an amalgamation of jelly-like ooze and what appear to be dryad bones.\n\nGuviena Bladesong would be interested in seeing these.", objectives = "" }
WordHunterWoW_QuestEN[42787] = { title = "Deal With It Personally", description = "The way I see it, the Wardens owe us for all of those years we were imprisoned. Unfortunately, their new leader, Sira Moonwarden doesn't agree with my assessment.\n\nEven though your champions have already dealt with several of their escaped bounties, she wants more. In fact, as a sign of good faith, she's asking that you deal with it personally.\n\nYou'll have to extinguish the flames of the kobold candles to summon forth the Devouring Darkness. The other two should be more straightforward.", objectives = "" }
WordHunterWoW_QuestEN[42792] = { title = "Make Your Mark", description = "While you were out, I asked around.\n\nYou are looking for Overseer Durant. Turns out he lives near the Shimmershade Garden.\n\nI can help you confront him, but you will need help. There are three individuals with the necessary skills, and they serve our cause.\n\nTell Cyrille that the owl hoots at dusk.\n\nInform Lorin that the saber prowls the plaza.\n\nMention to Sylessa that the cruel caskmaster has breathed his last.\n\nThey will know what to do. \n\nSpeak to Vanthir when the deed is done.", objectives = "" }
WordHunterWoW_QuestEN[42800] = { title = "Champion: Valeera Sanguinar", description = "", objectives = "" }
WordHunterWoW_QuestEN[42801] = { title = "Back in Black", description = "Before you head into the Black Temple, we need more information. The last thing we want is for you to teleport into a trap.\n\nWe must discern their force structure, patrol schedule, new defenses, and what Akama eats for breakfast.\n\n<Belath grins.>\n\nI suggest you send our broken warriors to handle this. They can blend in with the rest of Akama's Ashtongue forces inside the temple. We'll get what we need to know from the ones that make it back.\n\nA champion handler or two can scout outside the temple.", objectives = "" }
WordHunterWoW_QuestEN[42802] = { title = "Securing Mardum", description = "There has been increased demonic activity below on Mardum. There are still demons leftover down there from when we first invaded.\n\nTo eliminate any threat to the Fel Hammer, it's time that they were destroyed.", objectives = "" }
WordHunterWoW_QuestEN[42808] = { title = "Green Adepts", description = "As much as I would love us to finesse our way to victory, the cold, hard reality is that we need more powerful forces.\n\nWe are already straining Gaardoun's ability to recruit more broken.\n\nBut now that we have Ariana Fireheart, she can train new demon hunters for us.", objectives = "" }
WordHunterWoW_QuestEN[42809] = { title = "The Invasion of Niskara", description = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready.\n\nCaria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara.\n\nIt's time to begin the invasion and finish this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[42810] = { title = "A Final Offer", description = "What was that? Sounds like something's outside.\n\nSomething big...\n\nYou'd better get up there, {name}!", objectives = "" }
WordHunterWoW_QuestEN[42811] = { title = "We Meet at Light's Hope", description = "We must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.\n\nPaladins the world over will join us for the ceremony. I know Tirion would want you there most of all.", objectives = "" }
WordHunterWoW_QuestEN[42812] = { title = "We Meet at Light's Hope", description = "Before we march on the Broken Isles, {name}, we must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel here.\n\nPaladins the world have gathered below for the ceremony. They await your arrival to begin the ceremony.", objectives = "" }
WordHunterWoW_QuestEN[42814] = { title = "An Important Mission", description = "Champion! I bear an urgent message from Danath Trollbane.\n\nHe requests that you join him at Krasus' Landing. He has an urgent mission that requires your expertise!", objectives = "" }
WordHunterWoW_QuestEN[42815] = { title = "Return to the Broken Shore", description = "If I'm to assist in this war, I need firsthand information. I will fly to the Broken Shore and see the battlefield for myself.\n\nYour record as a proven commander is unquestioned, and you were there. I could use your insight.\n\nWill you accompany me to the Broken Shore? I don't anticipate engaging the enemy, but that close to the Fel Storm, one can never be sure.", objectives = "" }
WordHunterWoW_QuestEN[42818] = { title = "The Scarlet Assault", description = "The High Inquisitor of the Scarlet Crusade?!\n\nYou will not find High Inquisitor Whitemane listed in the annals of history alongside the names of fallen heroes.\n\nStill... despite her madness and zealotry she held a bond to the Light unmatched by even the greatest paladins.\n\nThere are few scarlet crusaders left on this world, but Scarlet Monastery is far from abandoned. The monastery now houses the most zealous and crazed crusaders the order has left.\n\nSuccess will require a full blown assault.", objectives = "" }
WordHunterWoW_QuestEN[42821] = { title = "Raising an Army", description = "We underestimated the number of scarlet crusaders still residing in the monastery. The battle for control of the cathedral is taking too long.\n\nIt's time to take a more resourceful approach to the battle...\n\nRaise the fallen crusaders as ghouls and send them back into the battle against their brothers and sisters.\n\nThe Scarlet Crusade will not be able to hold back the tide of undeath for long.", objectives = "" }
WordHunterWoW_QuestEN[42823] = { title = "The Scarlet Commander", description = "There is only one more obstacle standing between us and the tomb of Sally Whitemane.\n\nHigh Commander Goodchilde guards the path to the tomb. Although he is a zealot and a murderer, he is still a hardened knight who has dedicated his life to the eradication of our kind.\n\nHe should not be underestimated...\n\nSlay him and our work here will be nearly done.", objectives = "" }
WordHunterWoW_QuestEN[42824] = { title = "The Zealot Rises", description = "Sometimes the line between hero and villain is nothing more than perception. As High Inquisitor, Sally Whitemane saw herself as a champion of humanity in the war against the scourge. Yet under her leadership the Scarlet Crusade slew the living along with the undead.\n\nDeath can bring a silent peace to the soul, but not for Sally Whitemane. Her death is one of regret and unrest.\n\nWe will offer her the chance to atone for her crimes. The price will be high, but I have little doubt she will pay it.", objectives = "" }
WordHunterWoW_QuestEN[42828] = { title = "Moths to a Flame", description = "No doubt you have noticed our guests.\n\nI have watched them for a time and seen how they are attracted to the tree. I do not know if they are harmful to our sapling, but we cannot take that chance.\n\nCollect a handful of the insects and bring them to me. I will examine them and determine if they are to be left alone.", objectives = "" }
WordHunterWoW_QuestEN[42829] = { title = "Make an Entrance", description = "I need you to infiltrate the Twilight Vineyards and bring back something to deal with these insects.\n\nTo do that, you will need a way to bypass the guards that keep the orchards secure.\n\nLy'leth will be able to help us there. I will arrange to have her meet you near the entrance.\n\nGo quickly!", objectives = "" }
WordHunterWoW_QuestEN[42832] = { title = "The Fruit of Our Efforts", description = "It is my job to maintain appearances here.\n\n<Margaux smiles apologetically.>\n\nYou will have to endure a little showmanship while I walk with you through the vineyard. It is the only way to avoid suspicion.\n\nI will try to help you as I can, but only when it is safe to do so.\n\nCome with me- our first stop is the tasting pavilion. There you can sample some of our work.", objectives = "" }
WordHunterWoW_QuestEN[42833] = { title = "How It's Made: Arcwine", description = "<Margaux speaks in a hushed tone.>\n\nWhile we walk through the Vineyard, we may find time to exchange information.\n\nTry not to look alarmed at what you see, hm?\n\n<Margaux flashes a vacant, forced smile.>\n\nShall we press on?", objectives = "" }
WordHunterWoW_QuestEN[42834] = { title = "Intense Concentration", description = "This is a rare treat, I hope you know. Not just anyone is allowed to stand on this hallowed ground.\n\n<Sylverin adjusts his cuffs in a dignified fashion.>\n\nTo participate in the demonstration, simply take up an energy vessel and wade into the pool beside us. \n\nCatch the delicate dewdrops of Nightwell energy in the bowl as they fall- this is the only way one can safely manage its essence.\n\nOnce your vessel is full, proceed to our demonstration cask and gently pour the amalgamation into it.\n\nEnjoy!", objectives = "" }
WordHunterWoW_QuestEN[42835] = { title = "The Old Fashioned Way", description = "While you experienced the raw majesty that is Nightwell Infusion, Margaux was busy preparing another demonstration for you.\n\nHead across the bridge and to the left, then again across a bridge and to your right. You will find her on the juicing veranda.\n\nEnjoy the remainder of your tour!\n\n<Sylverin offers an intensely fake smile.>", objectives = "" }
WordHunterWoW_QuestEN[42836] = { title = "Silkwing Sabotage", description = "Moths. Who ever heard of something so... barbaric!\n\nThey are eating our crop and the mana wyrms do nothing to deter them.\n\nYou. You seem capable. Deter these creatures so we can complete our harvest on schedule.\n\nAhem. Please.", objectives = "" }
WordHunterWoW_QuestEN[42837] = { title = "Balance to Spare", description = "Our tour is just about over. I will let you loose to 'walk the orchard', as is proper at this stage.\n\nWhile you are there, you will notice a large number of mana wyrms floating about.\n\nI am certain the vineyard would not miss a handful of them.\n\nGood luck with your insect problem, friend.\n\n<Margaux smiles warmly at you.>", objectives = "" }
WordHunterWoW_QuestEN[42838] = { title = "Reversal", description = "<Sylverin regards you uneasily.>\n\nI was meant to meet you and Margaux here so I could escort you from the Vineyard. \n\nMy mistress Margaux is never late. I fear that something terrible may have happened.\n\nPlease find her and make sure she is well.", objectives = "" }
WordHunterWoW_QuestEN[42839] = { title = "Seek the Unsavory", description = "This is just... unspeakable.\n\nMargaux risked everything to get these mana wyrms to us. I cannot let it end this way.\n\nI need you to find someone who can make this right. Someone who will do whatever it takes to see Overseer Durant slain.\n\nSpeak with Vanthir. I am certain he will know exactly who we need.", objectives = "" }
WordHunterWoW_QuestEN[42840] = { title = "If Words Don't Work...", description = "Unless you have something worth risking my life for, I will not budge.\n\nVanthir must have told you that my services do not come cheap.\n\nLet's say... enough mana to sustain me for a month.\n\n<Arluin looks smug, as if you could never agree to this request.>", objectives = "" }
WordHunterWoW_QuestEN[42841] = { title = "A Big Score", description = "I'm not rich in anything but information, but maybe that can be of use to someone with your skills. You helped me, now you can help yourself.\n\nThe Magistrix receives a daily shipment of arcwine, which travels to the palace with a heavy escort. I can share the location, provided you leave me a cut of the goods.\n\nOne of my men has infiltrated the group and will hold up the delivery long enough for you to strike.", objectives = "" }
WordHunterWoW_QuestEN[42844] = { title = "Growing Power", description = "Lord Maxwell Tyrosus has requested your presence back at the Sanctum of Light.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.", objectives = "" }
WordHunterWoW_QuestEN[42846] = { title = "The Blood Matriarch", description = "I am but the first of many; you must find the holiest of paladins to champion our order.\n\nThere is one other I believe deserves such an honor - Lady Liadrin, Matriarch of the Blood Knights.\n\nGo speak to her now.", objectives = "" }
WordHunterWoW_QuestEN[42847] = { title = "Dark Storms", description = "Greetings, Highlord.\n\nBeside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical - the storms above the Tomb of Sargeras are intensifying. We should send our champions to keep an eye on that region, and scour the area for possible survivors.", objectives = "" }
WordHunterWoW_QuestEN[42848] = { title = "Recruiting the Troops", description = "Commander Ansela is a grizzled war veteran and seasoned teacher. Many of our most valiant knights once trained under her.\n\nGo speak to her now, and recruit a squad of Squires.", objectives = "" }
WordHunterWoW_QuestEN[42849] = { title = "Wrath and Justice", description = "A new mission requires our attention, Highlord {name}. Hearthglen has come under attack by a small demon army.\n\nNo doubt, they are testing our strength... and our patience.\n\nStrength we have in bounds, but my tolerance wears thin. I suggest we send our champions and troops to deal with this threat.", objectives = "" }
WordHunterWoW_QuestEN[42850] = { title = "Tech It Up a Notch", description = "Alamande Graythorn is well known among scholars of the Light.\n\nHe has long since retired from battle, but his mind is sharp as ever. I wouldn't be surprised if he could take a bout or two in a duel, either.\n\nSpeak to him and see if he has any knowledge to share regarding the improvement of our order hall.", objectives = "" }
WordHunterWoW_QuestEN[42851] = { title = "Champion: Vindicator Boros", description = "", objectives = "" }
WordHunterWoW_QuestEN[42852] = { title = "Champion: Justicar Julia Celeste", description = "", objectives = "" }
WordHunterWoW_QuestEN[42853] = { title = "Champion: Aponi Brightmane [NYI]", description = "", objectives = "" }
WordHunterWoW_QuestEN[42854] = { title = "Champion: Maximillian of Northshire [NYI]", description = "", objectives = "" }
WordHunterWoW_QuestEN[42855] = { title = "Champion: Arator the Redeemer [NYI]", description = "", objectives = "" }
WordHunterWoW_QuestEN[42856] = { title = "Champion: Lord Commander Leothraxion [NYI]", description = "", objectives = "" }
WordHunterWoW_QuestEN[42857] = { title = "Moist Around the Hedges", description = "These fruit appear to be food to grell.\n\nOld Grizzleback might appreciate it if they were removed from the village.", objectives = "" }
WordHunterWoW_QuestEN[42865] = { title = "Grell to Pay", description = "The ringleader of the grell must be sent to his final rest.\n\nYou will know him by the white of his skin and the bite of his tongue.", objectives = "" }
WordHunterWoW_QuestEN[42866] = { title = "A Sign From The Sky", description = "Greetings, Highlord. I have important news to share with you.\n\nDuring my expedition to the Broken Shore, I saw with my own eyes an extraordinarily luminescent object emerge from the Felstorm. It fell down towards the coast of Suramar, cutting a swath through the tempest itself!\n\nFrom it I felt an incredible surge of power, before it vanished beyond the horizon.\n\nWe need to bring news of this immediately to Archmage Khadgar.", objectives = "" }
WordHunterWoW_QuestEN[42867] = { title = "Meeting of the Silver Hand", description = "The Light's Heart will be safe within our order's walls, but it bears dark tidings.\n\nWe should gather the leaders of our order for a council.\n\nGo and speak to Lady Liadrin, Vindicator Boros, Justicar Julia Celeste, Arator the Redeemer, and Aponi Brightmane. We should seek their wisdom for the days ahead.", objectives = "" }
WordHunterWoW_QuestEN[42868] = { title = "The Monkey King's Challenge", description = "You can roll, you can hit, even shoot flaming spit...\nBut can your training you heed? Tasty brew's what I need!\nThe goodies you've gathered are what you must mix,\nThe instructions to follow will come from my lips.\nJust pass this final brewing lesson,\nAnd I will point you to my weapon.", objectives = "" }
WordHunterWoW_QuestEN[42869] = { title = "Eternal Vigil", description = "<Kor'vas glances at your glaives, her eyes widening.>\n\nI'm excited to see what those can do in person! Maybe we can spar a bit before heading out on the next hunt?\n\nWhile you were gone we built a camp just off of this landing to help us watch over the Legion's movements. We should head there right away - Jace needed your help with something. It sounded big!", objectives = "" }
WordHunterWoW_QuestEN[42872] = { title = "Securing the Way", description = "I was able to make contact with our forces on Mardum - they secured the Fel Hammer after our departure all those years ago and have held it ever since!\n\nMalevolence has utilized the ship's warp systems to transport the bulk of our forces aboard, but doing so greatly taxes what little power remains.\n\nI believe there to be a better way.\n\nYour glaives carry a piece of the power of Kil'jaeden - you should be able to use them to open a permanent gateway to the Fel Hammer.", objectives = "" }
WordHunterWoW_QuestEN[42881] = { title = "Champion: Lady Liadrin", description = "", objectives = "" }
WordHunterWoW_QuestEN[42882] = { title = "The Scarlet Massacre", description = "We have a single purpose here, to raise Sally Whitemane as a Death Knight of the Ebon Blade. Such is our goal and we will see it through.\n\nHowever, the Scarlet Crusade has terrorized the people of Azeroth long enough. Therefore, our work here this day will not be done until every crusader has fallen, every stone has crumbled, and every banner burned.\n\nCome, Deathlord, let us bring ruin upon the Scarlet Crusade.", objectives = "" }
WordHunterWoW_QuestEN[42883] = { title = "All Grell Broke Loose", description = "The grell are in a frenzy, attacking my brethren and destroying our village!\n\nPlease, stranger, help us send these wicked miscreants to the soil.", objectives = "" }
WordHunterWoW_QuestEN[42884] = { title = "Grassroots Effort", description = "When I arrived at my home, the front door was barred by magical roots.\n\nI was able to remove them, but few of my tribe possess the necessary ability to do so themselves.\n\nTake my staff. Its powers will easily disentangle the obstructing roots.", objectives = "" }
WordHunterWoW_QuestEN[42885] = { title = "The Highlord's Command", description = "Tracking down the dreadlord Balnazzar is our highest priority. Let us send defenders of our order to pinpoint his recent movements.", objectives = "" }
WordHunterWoW_QuestEN[42886] = { title = "To Faronaar", description = "We are keeping a close eye on Legion movements at Faronaar in Azsuna.\n\nOur intel suggests that a high-ranking lieutenant, possibly the dreadlord Balnazzar himself, masterminds the attacks in that region.\n\nThis may be our chance to strike a blow at the Legion's leadership.\n\nVindicator Boros commands our forces at the front. He would welcome your help, Highlord.", objectives = "" }
WordHunterWoW_QuestEN[42887] = { title = "This Is Retribution", description = "Anger seethes within me like smoldering coals.\n\nOne stoke, and that anger will flare into a roaring flame.\n\nThe Legion's attack on Exodar was just the motivation I needed, Highlord. I've watched my brethren die for the last time.\n\nNow, I will be the one who does the killing. I WILL have justice! Help me, Highlord, and slay any demons you encounter in lower Faronaar.", objectives = "" }
WordHunterWoW_QuestEN[42888] = { title = "Communication Orbs", description = "We have important work at hand, Highlord.\n\nSpread out across the legion camp are orbs that are vital to the Legion's planning and strategy.\n\nDestroying them will severely damage their efforts. I will go with you, Highlord, to see this through.", objectives = "" }
WordHunterWoW_QuestEN[42889] = { title = "The Way Back Home", description = "Hello? This is Chief Telemancer Oculeth. I see you have emerged safely!\n\nI am locking in your location as we speak. I will need you to activate the beacon on your end so we can establish a teleportation link.\n\nGot it? Good.", objectives = "" }
WordHunterWoW_QuestEN[42890] = { title = "The Codex of Command", description = "Boros is in serious trouble.\n\nThe fel lord, Jarvox, guards the pit to the west. Boros is trapped in there, too.\n\nWe need to defeat Jarvox, take the Codex of Command that he carries, and rescue Vindicator Boros.\n\nI am with you, Highlord!", objectives = "" }
WordHunterWoW_QuestEN[42905] = { title = "LFGDungeons - Legion - Raid Finder - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[42911] = { title = "Drowned Mana", description = "How did you end up out here?  Ah well, that's neither here nor there at this point.  What matters is that I need your help!\n\nI see you have some experience fishing. Think you could put that skill to use for me?", objectives = "" }
WordHunterWoW_QuestEN[42914] = { title = "Champion: Meryl Felstorm", description = "", objectives = "" }
WordHunterWoW_QuestEN[42917] = { title = "Champion: Archmage Vargoth", description = "", objectives = "" }
WordHunterWoW_QuestEN[42918] = { title = "Demonic Runes", description = "Hodir valiantly went through that demonic portal. He should've earned an honorable death, but instead was taken prisoner by Legion scum.\n\nWe always imagined the battles of the end days to take place here in Azeroth, but we shall bring the fight to the enemy if it means sparing one of our own that terrible fate.\n\nHymdall thinks that with the right power source, he can reactivate and redirect the Legion's own gateways. Gather demonic runestones from the Legion and let the final conflict begin!", objectives = "" }
WordHunterWoW_QuestEN[42919] = { title = "The Scion's Legacy", description = "The leaders of the Silver Hand have gathered. Listen to their counsel.", objectives = "" }
WordHunterWoW_QuestEN[42920] = { title = "The Invasion of Niskara", description = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready.\n\nCaria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara.\n\nIt's time to begin the invasion and finish this once and for all.", objectives = "" }
WordHunterWoW_QuestEN[42921] = { title = "Confrontation at the Black Temple", description = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers.\n\nI will need but a moment to summon a gateway. Stand back, please.", objectives = "" }
WordHunterWoW_QuestEN[42931] = { title = "Where the Hammer Falls", description = "You saved us all, shaman! Thank you!\n\nThrall wants to dive right into the Maelstrom and retrieve the Doomhammer, but I worry - he was badly wounded in that last fight, and that demon Geth'xun may still be alive down there. We should go with him.\n\nHop on Stormbeak when you're ready and we'll track down that artifact!", objectives = "" }
WordHunterWoW_QuestEN[42932] = { title = "What the Stonemother Knows", description = "We must split up. I am still badly wounded from my encounter with Geth'xun, and I don't want to appear weak before the Stonemother. This task falls to you.\n\nTravel to Therazane's Throne and speak to Therazane herself. Find out if she has seen the Doomhammer.\n\nHelp her if she asks. She is dangerous and mercurial, but this is her realm, and without her aid we will find nothing.", objectives = "" }
WordHunterWoW_QuestEN[42933] = { title = "The Troggs that Fel to Earth", description = "\"Demons\" you say? A \"Burning Legion?\" Hrmph! Nothing burns here but for my ire, shaman, and if these monsters think to corrupt my domain, they will be crushed beneath my dainty beautiful feet!\n\nI have not seen this hammer of yours, but the stone troggs witnessed everything that fell from the sky. Moreover, they've been running amok in the Pale Roost ever since the green fire landed near their home.\n\nBe a dear and lay waste to the Felrock Troggs west of here. Perhaps you can get one of them to talk.", objectives = "" }
WordHunterWoW_QuestEN[42935] = { title = "Stone Drake Rescue", description = "When that demon of yours fell into my realm he must have done something to the troggs. They were never a threat to my beloved stone drakes before.\n\nNow they're loose all over the Pale Roost, subduing drakes on the ground. Put a stop to this insult at once, and free those drakes! They may be of use to us later.", objectives = "" }
WordHunterWoW_QuestEN[42936] = { title = "Clutch Play", description = "I confess the stone drake broodmother and I have had a rocky relationship in the past. She supported Deathwing during the Cataclysm, you know. But Aeosera has been put back in her place and it is my responsibility to protect her.\n\nThe problem is that she refuses to abandon her eggs, even in the midst of a trogg attack.\n\nYou're a shaman! Use your natural magnetism to reassemble fallen Opalescent Guardians in the Pale Roost. Escort them to Aeosera so they can carry her eggs to safety of my bosom.", objectives = "" }
WordHunterWoW_QuestEN[42937] = { title = "Needlerock Beatdown", description = "The troggs saw where your hammer fell, and I expect those cowards told the Legion where to find it. Hmph!\n\nThe leader of the stone troggs since the Cataclysm has been \"Borlock,\" a thick-headed little dirt-grubber who's about to get what's coming to him. Find him at Needlerock Spire and beat the information out of him.\n\nTake Aeosera with you. Her and her brood have their own score to settle with those belligerent little beasts.", objectives = "" }
WordHunterWoW_QuestEN[42939] = { title = "Tracking Down Uthalesh", description = "The logbook contains the latest information on Uthalesh. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "" }
WordHunterWoW_QuestEN[42940] = { title = "When There's a Will, There's a Way", description = "The Oculus appears to have fallen to the Burning Legion and is heavily shielded. We will need to figure out a way to get you inside. \n\nI suspect your champions can help us out quite a bit.", objectives = "" }
WordHunterWoW_QuestEN[42952] = { title = "Tracking Down the Skull", description = "The logbook contains the latest information on the Skull of the Man'ari. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "" }
WordHunterWoW_QuestEN[42954] = { title = "A Small Favor", description = "Meryl's illness is troubling. I have seen something similar before, but I cannot think of its name...\n\nTalk to my friend. I call her Ari. She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.", objectives = "" }
WordHunterWoW_QuestEN[42955] = { title = "The Proper Way of Things", description = "Archmage Khadgar is my friend. That he trusts you means much. \n\nI know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.", objectives = "" }
WordHunterWoW_QuestEN[42956] = { title = "Ari's Package", description = "Look! It was right here under our noses. \"Arcanists Guide to Rare Diseases.\" Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough.\n\nHere. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth's wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.", objectives = "" }
WordHunterWoW_QuestEN[42957] = { title = "Journey to the East", description = "My riddles you've solved but your job is not complete.\n\nCome, meet me at the Jade Serpent Temple for the answers you seek.", objectives = "" }
WordHunterWoW_QuestEN[42959] = { title = "Three Is a Lucky Number", description = "Ari is much more than she appears, you know. She was once one of the most powerful archmagi on Azeroth and a member of the Council of Tirisfal. Unfortunately her mind was badly damaged and she has not left the Hall of the Guardian since.\n\nShe must like you very much to have given you a gift. If you bring her something special in return, I suspect she will surprise you. She prefers things in threes.", objectives = "" }
WordHunterWoW_QuestEN[42966] = { title = "The Highlord's Command", description = "Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.", objectives = "" }
WordHunterWoW_QuestEN[42967] = { title = "The Highlord's Command", description = "Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads.\n\nTo defeat them, we will need to stay vigilant on all fronts.\n\nLet us send our champions to deal with the Legion incursions as they come.", objectives = "" }
WordHunterWoW_QuestEN[42968] = { title = "The Highlord's Command", description = "You are right, Highlord. Our military efforts cannot succeed without solid logistics.\n\nThat means we need a steady supply of weapons, food, medicine, and other provisions.\n\nLet us send our champions to establish a supply line.", objectives = "" }
WordHunterWoW_QuestEN[42970] = { title = "The Diamond King", description = "Me brother Magni, once King o' Ironforge, got changed into a diamond statue by a titan ritual. He's stood frozen in the belly o' the city fer years.\n\nBut I just got word that he's up and around... sayin' he knows somethin' 'bout how to beat the Legion!\n\nLook, {name}, I dunno if Magni's crazy, or if that's even really him. But if there's even a chance he kin help us...\n\nI'm told he muttered the name Ulduar. That's where I'm headed! I'd be obliged if you an' Khadgar were ta join me.", objectives = "" }
WordHunterWoW_QuestEN[42971] = { title = "Controlling the Elements", description = "Come closer, {race}.\n\nRagnaros in the Firelands, Al'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new.\n\nProve to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.", objectives = "" }
WordHunterWoW_QuestEN[42974] = { title = "The Fate of Hodir", description = "It is time, {name}. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir.\n\nThe Legion will regret they set foot on Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[42977] = { title = "Servant of the Windseeker", description = "The elemental lords must be united,  but there has been no Windlord to lead the air elementals since the death of Al'Akir.\n\nOnce, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince's rebirth.\n\nThere is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.", objectives = "" }
WordHunterWoW_QuestEN[42978] = { title = "A Royal Audience", description = "{name},\n\nMy father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought.\n\nYou have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized.\n\nPlease join me in Stormwind Keep at once so that you can be properly rewarded for your service.\n\n- King Anduin Wrynn", objectives = "" }
WordHunterWoW_QuestEN[42982] = { title = "The Victor's Spoils", description = "It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to.\n\nYou have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion.\n\nAs a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.", objectives = "" }
WordHunterWoW_QuestEN[42983] = { title = "Mistral Essence", description = "To restore the Maelstrom Pillar, we will need to infuse it with the essence of air.\n\nA large quantity of Mistral Essence will be required to do this.\n\nMistral Essence can be found on many of the elementals in Vortex Pinnacle.\n\nIf you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.", objectives = "" }
WordHunterWoW_QuestEN[42984] = { title = "Eye of Azshara: The Scepter of Storms", description = "The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar.\n\nAir, no matter how capricious, cannot resist a good storm.\n\nIn the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms.\n\nRetrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.", objectives = "" }
WordHunterWoW_QuestEN[42985] = { title = "A Royal Audience", description = "{name},\n\nThose who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves.\n\nI admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all.\n\nJoin me in the Undercity at once. Your victories must be met with due reward.\n\n- Warchief Sylvanas Windrunner", objectives = "" }
WordHunterWoW_QuestEN[42986] = { title = "Enemies of Air", description = "Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly.\n\nIn his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos.\n\nWe will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.", objectives = "" }
WordHunterWoW_QuestEN[42987] = { title = "The Victor's Spoils", description = "We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way.\n\nYou have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed.\n\nFace your fellow champions, {name}. Face them, and be recognized.", objectives = "" }
WordHunterWoW_QuestEN[42988] = { title = "Worldmender", description = "The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before.\n\nHowever, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles.\n\nWhen we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.", objectives = "" }
WordHunterWoW_QuestEN[42989] = { title = "Ma'haat the Indomitable", description = "In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg.\n\nThe Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later.\n\nFirst, we must find that egg!\n\nThe Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!", objectives = "" }
WordHunterWoW_QuestEN[42990] = { title = "Neltharion's Lair: The Earthen Amulet", description = "That you were even able to acquire the Egg of Gaiath  is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope.\n\nFor the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg.\n\nThere is an item that just may have the ability to do this - a relic known as the Earthen Amulet, rumored to have been created by Loken himself.\n\nIt was lost many ages ago, and has fallen into the hands of Dargrul the Underking.", objectives = "" }
WordHunterWoW_QuestEN[42995] = { title = "A Taste For Blood", description = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 3 Blood of Sargeras, and I will give you the egg.", objectives = "" }
WordHunterWoW_QuestEN[42996] = { title = "The Maelstrom Pillar: Air", description = "Elementalist Janai was looking for you earlier, Farseer. It appears that her study of the Maelstrom Pillar has been most enlightening.\n\nIf you have a moment, you should go and meet with her to discuss her progress.", objectives = "" }
WordHunterWoW_QuestEN[42997] = { title = "The Maelstrom Pillar: Earth", description = "Elementalist Janai has been hard at work restoring the Maelstrom Pillar. As of late, she has been focusing her research on the element of earth.\n\nYou should speak with her when you have a chance. I have heard that she is close to a breakthrough.", objectives = "" }
WordHunterWoW_QuestEN[43002] = { title = "Blessed Blade of the Windseeker", description = "So the Earthen Ring wishes to resurrect my master?\n\n<Highlord Demitrian laughs maniacally.>\n\nI knew this day would come! At last, humanity understands the power of the Windseeker!\n\nWhen Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury.\n\nTo resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master's sword traveled to the Broken Isles to fight demons.", objectives = "" }
WordHunterWoW_QuestEN[43003] = { title = "Return to Janai", description = "<Ma'haat the Indomitable speaks to you with a low, rumbling voice.>\n\nHere... is the Egg of Gaiath. It is yours now.\n\nGo... in peace.", objectives = "" }
WordHunterWoW_QuestEN[43007] = { title = "Return to the Chamber of Shadows", description = "Lord Jorach Ravenholdt sent me out to find you, {name}. He wants your counsel on some matter of importance.\n\nHe requests your presence back at the Chamber of Shadows.", objectives = "" }
WordHunterWoW_QuestEN[43013] = { title = "The School of Roguery", description = "Great! Sounds like she's already settled in. That's good, cuz we already need some fresh meat for the grinder.\n\nYou should mosey over an' see if she's got any thieves just lying around takin' up space.", objectives = "" }
WordHunterWoW_QuestEN[43014] = { title = "The Big Bad Wolfe", description = "You've heard of Winstone Wolfe, right? Of course you have. Who hasn't?\n\nSo, while you were off gabbin' with the headmistress, Lord Ravenholdt graced me with his presence. In the flesh. I didn't think he ever came out of that chamber.\n\nAnywhoodles, he more than suggested, in that way of his, that we send Garona, Vanessa, and our new merry gang of bandits off to have a little chat with The Wolf at Ravenholdt Manor.\n\nJust make sure they're nice and civil, or that's the last we'll see of them.", objectives = "" }
WordHunterWoW_QuestEN[43015] = { title = "What Winstone Suggests", description = "If anyone can improve the way things run around here, it's Winstone Wolfe. I tell ya, the man is a miracle-worker!\n\nNow that he's workin' for us, shall we pick his brain an' see what he suggests?", objectives = "" }
WordHunterWoW_QuestEN[43054] = { title = "An Ample Stockpile", description = "I have gone through our stockpile several times and no matter how I try to cut corners, we come up short.\n\nA lack of food and medicine will halt our war efforts... that is simply the reality.\n\nWe desperately need food or bandages. If you know how to acquire any such items, you can bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[43055] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[43056] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[43057] = { title = "Candy Bucket", description = "", objectives = "" }
WordHunterWoW_QuestEN[43062] = { title = "Further Training", description = "You may be the Grandmaster, but mastery must be maintained through discipline.\n\nTo achieve perfect harmony, you must continue your training.\n\nI would like to see your form in practice, {name}. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.", objectives = "" }
WordHunterWoW_QuestEN[43090] = { title = "Ulduar's Oath", description = "I was once leader of all of the titanforged keepers of Azeroth.  We were charged by the Titans themselves to protect the world.\n\nOnce I gave up on the post of Prime Designate, I gave up any measure of influence over the other keepers.  Not even my own son, Thorim, is bound to heed my commands.\n\nThe Gjallarhorn comes from a time before our falling out, however.  A time of an ancient oath of honor.\n\nLet us invoke that oath -- I am certain Thorim will answer the call.", objectives = "" }
WordHunterWoW_QuestEN[43100] = { title = "Finding the Scepter", description = "Very powerful, but difficult to acquire. Scepter is in the hands of Gul'dan. We must find out his plans, get close.\n\nCalydus know Gul'dan planning major operation. He has sent out a call to arms to all Shadow Council to help with big ritual. One such group at Caer Darrow, talking to the necromancers there.\n\nYou should go, find out about plan.", objectives = "" }
WordHunterWoW_QuestEN[43151] = { title = "Making A Trade", description = "Yes I do have Amaranthine Hops, but they took me quite some time to gather. I cannot part with them easily.\n\nHowever, I'd be willing to trade them for Stonehide Leather.\n\nIf you come upon any, bring it to me and we can make a trade.", objectives = "" }
WordHunterWoW_QuestEN[43153] = { title = "An Eye for a Scepter", description = "Sounds simple? Make nice with Shadow Council friend must... for now. Help with ritual enough to gain trust, then turn tables!\n\nCouncil made portal device to Tol Barad here. Go, help Shadow Council find Eye of Dalaran, earn spot in big ritual! Then steal Scepter!\n\nCalydus will try to keep eye on friend when possible.", objectives = "" }
WordHunterWoW_QuestEN[43162] = { title = "Under the Crooked Tree", description = "My three sisters from that tree hung,\nThe crimes accused there was not one,\nThe youngest sister did escape,\nAs the noose looped around their nape,\nOld Ravencrest is the one to blame,\nThis curse for you to lift our shame.", objectives = "" }
WordHunterWoW_QuestEN[43181] = { title = "Tracking Down the Scepter", description = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "" }
WordHunterWoW_QuestEN[43182] = { title = "The Missing Vessel", description = "So long as Hakkar roams free, no mage will be safe.\n\nMillificent Manastorm created a vessel that siphons the essence of a mage, binding their magic to the object. It was created to be a weapon, but we can use it as bait.\n\nIf I channel my essence into the vessel, it will become an object of pure magic.\n\nUpon capture, Millificent shattered the vessel, allowing it to fall into the hands of our enemies.\n\nFind the pieces and return them to me. Together we can set a trap Hakkar won't be able to resist!", objectives = "" }
WordHunterWoW_QuestEN[43184] = { title = "Champion: Allari the Souleater", description = "", objectives = "" }
WordHunterWoW_QuestEN[43185] = { title = "Champion: Jace Darkweaver", description = "", objectives = "" }
WordHunterWoW_QuestEN[43186] = { title = "I Am the Slayer!", description = "{name}, we have all gathered here to honor you for your leadership, successes, and sacrifices.", objectives = "" }
WordHunterWoW_QuestEN[43215] = { title = "Tracking Down the Scepter", description = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "" }
WordHunterWoW_QuestEN[43242] = { title = "Demon Commander", description = "", objectives = "" }
WordHunterWoW_QuestEN[43243] = { title = "Demon Commander", description = "", objectives = "" }
WordHunterWoW_QuestEN[43244] = { title = "Invasion: Tanaris", description = "", objectives = "" }
WordHunterWoW_QuestEN[43245] = { title = "Invasion: Westfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[43249] = { title = "The Raven's Eye", description = "It is imperative that we decipher the SI:7 letter. We must uncover the secrets that it holds before it is too late. But, our best code breakers have yet to make a dent in the cypher.\n\nHowever, we now know that the myth is in fact reality. The Raven's Eye truly exists.\n\nShall we tell the others?", objectives = "" }
WordHunterWoW_QuestEN[43250] = { title = "Off to Court", description = "The Ravencourt of Black Rook Hold is where we begin our search. It is the ancestral home of Lord Kur'talos Ravencrest, night elven hero of the War of the Ancients. Some of my own ancient ancestors are interred in its cemetery.\n\nMeet me there and make sure that you are not followed. SI:7 is very good at what they do. We have to be better.", objectives = "" }
WordHunterWoW_QuestEN[43251] = { title = "In Search of the Eye", description = "The Raven's Eye should be somewhere within the courtyard. This is where Ravencrest's lieutenants used to plan their strategies in life. Hell, it looks like they still might be doing so in death.\n\nIt has to be around here somewhere. Your skill at lock picking should prove invaluable.", objectives = "" }
WordHunterWoW_QuestEN[43252] = { title = "Eternal Unrest", description = "My ancient ancestors are buried here in the cemetery to the west. Because of whatever is causing the dead to rise, their souls are now at unrest.\n\nAll blood elves are descended from high elves, who in turn came from these lands before they were sundered.\n\nI cannot bring myself to do it. Will you put my ancestors to rest?", objectives = "" }
WordHunterWoW_QuestEN[43253] = { title = "Maw of Souls: Ancient Vrykul Legends", description = "Our diversionary tactics in Stormheim uncovered intel on something I thought only a myth.\n\nThere is a legend about a magical jewel the vrykul created long before the time of man. The jewel was said to be able to...\n\n<Valeera stops herself from continuing while looking around and eyeing you wryly.>\n\nI do not want to talk about it just yet. Not until we have proof.\n\nUnfortunately, the only way we are going to get that proof is in the Maw of Souls on the Naglfar... the ship of the dead.", objectives = "" }
WordHunterWoW_QuestEN[43254] = { title = "Ritual Ruination", description = "Time for main event, friend! Gul'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan.\n\nTake this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out!\n\nCalydus will help when he can! Good luck, friend!", objectives = "" }
WordHunterWoW_QuestEN[43259] = { title = "Beware of the Crooked Tree", description = "{race}, you must be warned. There is great evil in Val'sharah. I've seen it, and I wish I hadn't. If you take my advice, you will stay far away from the crooked tree in Bradensbrook.", objectives = "" }
WordHunterWoW_QuestEN[43260] = { title = "Growing Power", description = "It appears ye and yer weapon are both growin' in strength. Return to me at Netherlight Temple. I have more to show ye.", objectives = "" }
WordHunterWoW_QuestEN[43261] = { title = "Champion: Vanessa VanCleef", description = "", objectives = "" }
WordHunterWoW_QuestEN[43262] = { title = "Champion: Garona Halforcen", description = "", objectives = "" }
WordHunterWoW_QuestEN[43264] = { title = "Rise, Champions", description = "Your power is great, Deathlord, but power alone will not be sufficient.\n\nIf we are to save this world from the onslaught of the Burning Legion, then you will need powerful allies. The Knights of the Ebon Blade are yours to command, it will be wise to make use of them effectively.\n\nGo and speak with Nazgrim and Thassarian. They will be of great use to you in the fight against the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[43265] = { title = "Spread the Word", description = "Now that you have recruited your champions, you can use the Scouting Map to complete vital missions across the Broken Isles.\n\nThe first mission is critical to the growth and power of our order. Send Nazgrim and Thassarian to seek out new candidates for the Ebon Blade.\n\nOur order must grow in strength if we are to defeat the Burning Legion.", objectives = "" }
WordHunterWoW_QuestEN[43266] = { title = "Recruiting the Troops", description = "A powerful necromancer has joined the cause of the Ebon Blade.\n\nDark Summoner Marogh has come a long way to us from deep within the realm of the Shadowlands. He will be a powerful ally of the Ebon Blade.\n\nSpeak with Dark Summoner Marogh to begin raising an army of ghouls for the Ebon Blade.", objectives = "" }
WordHunterWoW_QuestEN[43267] = { title = "Troops in the Field", description = "It's time to send our newly summoned ghouls out into the field. Look at the Command Table and send your champions and troops on a routine scouting mission.", objectives = "" }
WordHunterWoW_QuestEN[43268] = { title = "Tech It Up A Notch", description = "Archivist Zubashi has been doing a great deal of research on the necropolis we call Acherus.\n\nThrough his studies on the necropolis, he has located a number of potential improvements that can greatly increase the power of the Ebon Hold.\n\nSpeak with Archivist Zubashi now and he will show you what improvements can be made.", objectives = "" }
WordHunterWoW_QuestEN[43270] = { title = "Rise, Champions", description = "As leader of our order, other priests will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary to bring down the Burning Legion.\n\nAfter your display of power during the cleansing ritual, there will be many who are eager to serve at your side. Seek out those priests, and let them ease the burden of leadership.", objectives = "" }
WordHunterWoW_QuestEN[43271] = { title = "Champion: Calia Menethil", description = "", objectives = "" }
WordHunterWoW_QuestEN[43272] = { title = "Champion: High Priestess Ishanah", description = "[PH]", objectives = "" }
WordHunterWoW_QuestEN[43273] = { title = "Spread the Word", description = "In the center of the dais is a map of the Broken Isles. From it, you can direct our allies to carry out vital assignments across the world.\n\nThe first task is critical to the growth of our order - identifying skilled priests whom we can trust to train our order's troops.\n\nThis is a task we can easily entrust to one of our new champions.", objectives = "" }
WordHunterWoW_QuestEN[43275] = { title = "Recruiting the Troops", description = "Our recruiting efforts have paid off. Grand Anchorite Gesslar has pledged his service to our order.\n\nHe has an eye for greatness, and can easily spot a recruit with potential. He takes those selected under his wing, and shapes them into worthy allies.\n\nSpeak to him now and train a troop of acolytes.", objectives = "" }
WordHunterWoW_QuestEN[43276] = { title = "Troops in the Field", description = "It's time to send our newly trained acolytes out into the field. Look at the Command Map and send your champions and troops on a routine scouting mission.", objectives = "" }
WordHunterWoW_QuestEN[43277] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Archon Torias.\n\nHis knowledge will be invaluable as we improve our defenders and fortify Netherlight Temple.", objectives = "" }
WordHunterWoW_QuestEN[43282] = { title = "Invasion: Northern Barrens", description = "", objectives = "" }
WordHunterWoW_QuestEN[43283] = { title = "Demon Commander", description = "", objectives = "" }
WordHunterWoW_QuestEN[43284] = { title = "Invasion: Dun Morogh", description = "", objectives = "" }
WordHunterWoW_QuestEN[43285] = { title = "Invasion: Hillsbrad Foothills", description = "", objectives = "" }
