WordHunterWoW_QuestEN[43301] = { title = "Invasion: Azshara", description = "", objectives = "" }
WordHunterWoW_QuestEN[43303] = { title = "Time to Rumble!", description = "Welcome to the Black Rook Rumble!  Many combatants have entered to prove their might in the Black Rook Arena, and now it is your time.", objectives = "" }
WordHunterWoW_QuestEN[43309] = { title = "The Perfect Opportunity", description = "I have heard whispers from Suramar City.\n\nRecent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested.\n\nThis is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause!\n\nI know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray.\n\nSeek her out at the Waning Crescent and ensure her victory.", objectives = "" }
WordHunterWoW_QuestEN[43310] = { title = "Either With Us", description = "Thalyssra asks much of me, but our cause is worth the risks.\n\nThe title of advisor would grant us enormous influence. Information. Access.\n\nI could change this rebellion. I could save so many lives.\n\nI will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant.\n\nLady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. \n\nEarn her trust and the rest will follow.", objectives = "" }
WordHunterWoW_QuestEN[43311] = { title = "Or Against Us", description = "If Ly'leth is to achieve the role of advisor to the Grand Magistrix we will need to open a path for her.\n\nIt is true she will have some supporters but they alone cannot grant her the title.\n\nThere are other houses that Ly'leth must contend with. Fear and coercion are their tools. None dare stand against them openly, and we cannot win them over with favors and oaths. \n\nSeek out Arluin. I trust he will have some ideas of how to proceed.", objectives = "" }
WordHunterWoW_QuestEN[43312] = { title = "Thinly Veiled Threats", description = "How could I let this happen?\n\n<Aurore wrings her hands.>\n\nYesterday Coryn Stelleris approached me about the appointment. He sought my support, but I did not offer it. \n\nHe said my son's life would continue as normal... if I gave him my vote.\n\nThis morning my son was gone.\n\nI can only think of the terrible things he may be suffering. You know what this family is capable of!\n\nYou want my support, but I can do nothing while my son is in danger. Nothing.\n\nPlease... save him!", objectives = "" }
WordHunterWoW_QuestEN[43313] = { title = "Rumor Has It", description = "Coryn Stelleris and Ruven Duskmere were close friends, but one always overshadowed the other. Now the Stelleris family stands to gain from lord Ruven's death. Handsomely.\n\nHouse Duskmere will soon learn of their loss. I want you to be the one to redirect their anger and grief.\n\nA handful of well placed rumors should do the trick.\n\nI won't be lingering in this part of the city for long, and Ly'leth will want to know of your efforts.\n\nReturn to her when you are finished.", objectives = "" }
WordHunterWoW_QuestEN[43314] = { title = "Court of Stars: Beware the Fury of a Patient Elf", description = "An opportunity presents itself, {name}.\n\nLy'leth has arranged to grant you entry into a ball at the Court of Stars. I do not know what we may gain from this venture, but there is one task I must set for you.\n\nAdvisor Melandrus once called himself my ally. He and I planned Elisande's downfall, but when the moment came I found myself betrayed.\n\nThe wound his dagger inflicted still aches. I cannot enter Suramar to take my revenge, but you can.\n\nGive him a traitor's death, and bring me his spellstone.", objectives = "" }
WordHunterWoW_QuestEN[43315] = { title = "Death Becomes Him", description = "There are two houses that pose a threat to Ly'leth's rise, but we concern ourselves with only one of them now.\n\nHouse Duskmere commands respect through fear and that fear is not unfounded. Few can boast of magical talent equal to that of Ruven Duskmere. \n\nWithout this charming specimen, however, their house is nothing.\n\nI know you may find my methods distasteful. Know that there were demons in Suramar long before the Legion.\n\nThis one has lived long enough.", objectives = "" }
WordHunterWoW_QuestEN[43317] = { title = "In the Bag", description = "Already the city is abuzz with outrage.\n\nI will not lie to you- it pleases me greatly that one such as Coryn is made a fool.\n\nThe other houses have sent their endorsements. It is done, and nothing remains but a formal ceremony to grant me the title of advisor.\n\nMeet me there. You deserve to share in this success.", objectives = "" }
WordHunterWoW_QuestEN[43318] = { title = "Ly'leth's Champion", description = "Tal'ashar is an honor duel.\n\nIf I lose, then I must forfeit my title to Coryn Stelleris.\n\n<Ly'leth smiles gently.>\n\nThat is why you are going to fight for me. \n\nI will grant you a more powerful disguise for this task, and together we will put Coryn in his place.\n\nSpeak to me when you are ready to battle on my behalf.", objectives = "" }
WordHunterWoW_QuestEN[43319] = { title = "The Way of the Tiger", description = "Among the allies who joined us from Tian Monastery is Gin Lai, a monk famed for his experience in the ways of the tiger.\n\nWith his help, we will be able to train Tiger Initiates, who strike swiftly and precisely on the field of battle.\n\nGo speak with him now and request his services.", objectives = "" }
WordHunterWoW_QuestEN[43323] = { title = "A Time to Reflect", description = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", objectives = "" }
WordHunterWoW_QuestEN[43331] = { title = "Time to Collect", description = "Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I'd imagine you're not very happy with them?\n\nLet's just say we're not exactly friends either.\n\nSo I'll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow?\n\nOh, and bring some friends. They're not exactly the easiest of targets.", objectives = "" }
WordHunterWoW_QuestEN[43334] = { title = "The Coming Storm", description = "You saved us all, my friend! Truly you embody all the elements stand for.\n\nIf the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power.\n\nThey were placed in the care of the White Tiger, who will give them only to one who is worthy. Come {name}! Travel with me to Pandaria and we will prove your worth!", objectives = "" }
WordHunterWoW_QuestEN[43335] = { title = "Survival Skills", description = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct.\n\nShow me you have the basic survival skills to live off the land.", objectives = "" }
WordHunterWoW_QuestEN[43338] = { title = "The Codex of Ra", description = "The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as \"Ra-den\" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone, The Edict of Fire, and the Edict of the Storm.\n\nThese pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.", objectives = "" }
WordHunterWoW_QuestEN[43341] = { title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[43349] = { title = "The Aegis of Aggramar", description = "Now that it's out of the hands of the Legion, the Aegis should be brought back to Dalaran for safekeeping while the hunt continues for the rest of the Pillars of Creation.\n\nIt should be safe in the central portal chamber until the time comes when it is needed.", objectives = "" }
WordHunterWoW_QuestEN[43352] = { title = "Asset Security", description = "With the demons and guards so agitated, I'm running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now.\n\nHead to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge.\n\nI will make sure there is something in it for you when you are done.", objectives = "" }
WordHunterWoW_QuestEN[43359] = { title = "A Hero's Weapon", description = "Grand Master, you have saved our order from the brink of destruction.\n\nYour deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential.\n\nPlease, stand before the Forge of the Roaring Mountain and raise your weapon high.", objectives = "" }
WordHunterWoW_QuestEN[43360] = { title = "The Shardmaidens", description = "Long have I walked this land and I have seen many forms of corruption.\n\nThe creatures that wander this hall are twisted by the magics unleashed by the failed arcan'dor. These dryads have lost their way, and cannot be saved.\n\nYou must destroy them. End their suffering.", objectives = "" }
WordHunterWoW_QuestEN[43361] = { title = "Fragments of Disaster", description = "In the hall beyond rests the bones of the failed arcan'dor.\n\nI will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction.\n\nOnly then do we have any hope of preventing this disaster from repeating itself.", objectives = "" }
WordHunterWoW_QuestEN[43362] = { title = "The Stuff of Dreams", description = "This arcan'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both.\n\nThe arcane will soon devour it whole.\n\nWe can restore balance, but it will require wild magic. Magic trapped in another realm.\n\nYou must enter the Emerald Dreamway and bring back the essence of life itself.\n\nOnly then can the arcan'dor find stability and begin to thrive once more.", objectives = "" }
WordHunterWoW_QuestEN[43363] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[43364] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[43365] = { title = "The Cycle Continues", description = "Yay! The grove is regenerating nicely. Our flower friends thank you for helping them.\n\nWe were able to save most of the grove, but sadly, many living souls were lost as well.\n\nBrightwing is so sad!\n\nBut you can help! Take this bag of Dream Seeds. Plant them onto fresh corpses, and in time, new flowers will grow!\n\nDeath is beautiful, and from death comes rebirth. This is the cycle that must continue!", objectives = "" }
WordHunterWoW_QuestEN[43368] = { title = "Champion: Brightwing", description = "", objectives = "" }
WordHunterWoW_QuestEN[43370] = { title = "A New Invention", description = "I have been experimenting with technology that allows you to alter the structure of beasts, specifically with how they look.", objectives = "" }
WordHunterWoW_QuestEN[43371] = { title = "Relieving the Front Lines", description = "Many within our order have been on the front lines of battle for too long, aiding those who are attempting to thwart the Legion's invasion.\n\nIt is time we send in some relief, allowing our allies some much needed rest.", objectives = "" }
WordHunterWoW_QuestEN[43372] = { title = "Whispers in the Void", description = "Our priests are resting and recuperating, but one not as well as the others. Gilner Greymoss lingers within the Sanctuary of the Void, laughing to himself.\n\nHe refuses to leave, but his presence is making the other priests uneasy.\n\nPerhaps you should speak to him and see what is wrong?", objectives = "" }
WordHunterWoW_QuestEN[43373] = { title = "The Best and Brightest", description = "If we wish to see the truth in Gilner's ramblings, I will need to induce a vision.\n\nIt is not the sort of thing that is typically forced, but we have within our ranks the best and brightest alchemists who can craft an extract that will grant me the sight I need.\n\nSeek them out in Azsuna where they are currently aiding those on the front lines.", objectives = "" }
WordHunterWoW_QuestEN[43374] = { title = "Murloc Mind Control", description = "Yalia and I were deliverin' antidotes to da front lines a Faronaar when we were attacked by a herd a murlocs. We dropped our supplies and made a run for it, but Yalia never made it out a da camp. Obviously I didn't fair much better, ma bones still ache from bein' turned to stone.\n\nIt's possible Yalia's still alive and bein' held captive. Please, ya have to find her!", objectives = "" }
WordHunterWoW_QuestEN[43375] = { title = "An Ample Supply", description = "Durin' our attempt to flee da murlocs, Yalia and I dropped da supplies we planned to deliver to da demon hunters in Faronaar.\n\nInside each a those crates were vials a salve dat took us countless days and resources to craft. If we don' get those supplies back, I fear our allies on da front lines will suffer.", objectives = "" }
WordHunterWoW_QuestEN[43376] = { title = "Problem Salver", description = "Forcing a vision isn't easy by any means. Finding the ingredients for the elixir alone will take a considerable amount of time, time we don't have. Too many are suffering on the front lines as we speak, in need of the salve we were meant to deliver.\n\nI suppose if we all work together, we can make this work.\n\nZabra and I will find the items needed for Velen's elixir, if you take the salve to Faronaar and cure the demon hunters. Does that sound fair?", objectives = "" }
WordHunterWoW_QuestEN[43377] = { title = "Halls of Valor: The Light Within", description = "We cannot ignore the Prophet's vision, {name}. To do so would mean that everything we know and hold dear will be lost to the Legion.\n\nWe must focus on what we know, and that is that the Light must walk among us.\n\nWithin the Halls of Valor you will find an ascending val'kyr by the name of Hyrja. Recover a spark of her Light and release it within our temple.", objectives = "" }
WordHunterWoW_QuestEN[43378] = { title = "Eye of Azshara: Looking Through the Lens", description = "We have what we need to create Velen's elixir, but in order for others to be able to witness his vision, we'll need to find something that can be used to project images from the mind.\n\nA lens from the nearby naga should work well, but I don't think they're going to be too eager to give it up.", objectives = "" }
WordHunterWoW_QuestEN[43379] = { title = "Velen's Vision", description = "I have everything I need to bring forth a vision, but the question remains: are you ready to witness it? Even the smallest glimpse into the future can weigh heavy on your soul.\n\nOnce I ingest the elixir, the vision will come quickly. Gazing into the Lens of the Tides will allow you to see what I see.\n\nLet me know when you are ready to begin.", objectives = "" }
WordHunterWoW_QuestEN[43380] = { title = "Champion: Sol", description = "", objectives = "" }
WordHunterWoW_QuestEN[43381] = { title = "Champion: Mariella Ward", description = "", objectives = "" }
WordHunterWoW_QuestEN[43382] = { title = "Champion: Natalie Seline", description = "", objectives = "" }
WordHunterWoW_QuestEN[43383] = { title = "Awakening the Light", description = "This spark will only know its full potential once it's been filled with pure Light, gleaned from the holiest places in our world.\n\nNurture this spark, and it may grow to walk among you.", objectives = "" }
WordHunterWoW_QuestEN[43384] = { title = "Demonic Runes", description = "I cannot stand by idly and allow the Legion to destroy our home. \n\nI've been studying their language for some time, deciphering any runes I can get my hands on, but my supply is severely limited. \n\nIf I had more runes to study, it's possible that I may discover something that will help us in locating Balnazzar.", objectives = "" }
WordHunterWoW_QuestEN[43385] = { title = "Infiltrating Our Enemies", description = "With the Light at our side, we should focus our efforts on figuring out who among our enemies could be a potential ally.\n\nAny of your champions should be capable of infiltrating enemy ranks, giving us a better understanding of how to approach this.\n\nEven so, it is a delicate task. Proceed with caution.", objectives = "" }
WordHunterWoW_QuestEN[43386] = { title = "Onslaught Envoy", description = "A few defectors have been discovered among the Scarlet Onslaught in Northrend.\n\nI know it's difficult to think that any within their ranks could be useful to our cause, but we must make an attempt.\n\nThe prophecy says an old enemy will become an ally, so it's worth it to investigate and see if these defectors can be brought to the Light.", objectives = "" }
WordHunterWoW_QuestEN[43387] = { title = "Scarlet Redemption", description = "The Light shines upon me, {name}! For the first time in my life, I feel it!\n\nI was without hope, ready to die for the things I had done in the name of the Scarlet Crusade, but then you appeared! You are my chance at redemption. \n\nPlease, let me prove to you that I am worthy of a second chance. Let me slay those I used to be loyal to!", objectives = "" }
WordHunterWoW_QuestEN[43388] = { title = "Apostate Liberation", description = "There are others like me, you know. Others that have removed the veil that the Scarlet Crusade has kept over our eyes for so long. \n\nThey've been placed in cages, treated like animals, simply because their beliefs no longer line up with what the Onslaught deems is right and holy. \n\nThey wish to redeem themselves. We should try to free them, if you think their lives are worth saving.", objectives = "" }
WordHunterWoW_QuestEN[43389] = { title = "Unexpected Guests", description = "You helped me escape my fate by freeing me from the gallows, but allowing me to fight the Scarlet Onslaught by your side has truly freed my heart and mind from the guilt I have felt for so long.\n\nI want to be a part of something greater than myself, a noble cause that won't distort the meaning of the Light. \n\nLet me travel to your temple and beg forgiveness of the Prophet. I may not be a welcome guest, but it's a journey I must make to complete my redemption.", objectives = "" }
WordHunterWoW_QuestEN[43390] = { title = "Forgotten Shadows", description = "The Light walks among us, as does one of our enemies. You have done well to bring the prophecy to life, but it is not yet complete.\n\nThe shadows must rise, and to do so, the Cult of Forgotten Shadows must be restored. \n\nYou will find the few remaining followers at the cemetery in Duskwood. They linger there near the grave of their fallen leader.", objectives = "" }
WordHunterWoW_QuestEN[43391] = { title = "Secrets of the Void", description = "Our leader was murdered for her beliefs, or so most would believe.\n\nNatalie Seline knew her fate, and took steps to protect herself from an inevitable death. \n\nThe night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself.\n\nShe penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place.\n\nWithout her journal, we will never be able to recover her spirit.", objectives = "" }
WordHunterWoW_QuestEN[43392] = { title = "Into the Void", description = "This is without a doubt Natalie's writing. The entry was scrawled in haste, but the message is clear: The spell within this journal will lead us to Natalie's spirit, but it needs to be incanted at a shadow altar within the catacombs.\n\nOdessa and I have a duty to watch over Natalie's body, but with your considerable power, you should be able to perform the spell with ease.", objectives = "" }
WordHunterWoW_QuestEN[43393] = { title = "Rising Shadows", description = "News of my return will spread fast among those who share my beliefs. Soon Azeroth will see the rise of Shadows, but I imagine this is not news to you.\n\nWhatever your plan may be, I hope it continues to see the Cult of Forgotten Shadows as allies.", objectives = "" }
WordHunterWoW_QuestEN[43394] = { title = "Crossing Legion Lines", description = "I've received word from the Highlord that a group of paladins and priests were captured after a battle broke out at Felblaze Ingress. Your priestess, Delas Moonfang, was among those captured.\n\nThey've been taken through the demon portal and into the Legion stronghold of Niskara.\n\nWe will need the assistance of the Conclave if we have any hope of recovering them.", objectives = "" }
WordHunterWoW_QuestEN[43395] = { title = "Allies of the Light", description = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.\n\nWe cannot leave them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[43396] = { title = "The Mind of the Enemy", description = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly.\n\nLet us find whatever information we can about their plans.", objectives = "" }
WordHunterWoW_QuestEN[43397] = { title = "United As One", description = "You and Delas have had dealings with the paladins before, maybe it's possible they will grant you an audience with their war council. \n\nHead to the Sanctum of Light and ask the paladins to help us defend Netherlight Temple from Balnazzar's attack.", objectives = "" }
WordHunterWoW_QuestEN[43398] = { title = "Champion: Alonsus Faol", description = "", objectives = "" }
WordHunterWoW_QuestEN[43399] = { title = "Fortifying the Temple", description = "We've all worked so hard turning this temple into something all priests can be proud of, it would be a shame to see it fall to the Burning Legion.\n\nWe must strengthen our defenses in preparation for the attack. With the right resources, we can make the temple a nearly impenetrable fortress.", objectives = "" }
WordHunterWoW_QuestEN[43400] = { title = "Lumenstone", description = "To prepare for the battle, we will need the best armor and weapons we can get.\n\nLumenstone is an enchanted material that can withstand great amounts of fel magic.\n\nIt is found in rare quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", objectives = "" }
WordHunterWoW_QuestEN[43401] = { title = "A Light in the Darkness", description = "The Burning Legion has begun their attack!\n\nI will remain here and prepare the temple's defenses. You must meet our allies in Dalaran and let them know that the battle has begun!\n\nMake haste, {name}. I do not know how long we will be able to keep Balnazzar at bay.", objectives = "" }
WordHunterWoW_QuestEN[43402] = { title = "High Priest of Netherlight", description = "You have fulfilled the prophecy, but more than that, you have united the priests of Azeroth.\n\nWe should take a moment to recognize all that you have accomplished.", objectives = "" }
WordHunterWoW_QuestEN[43403] = { title = "Defending the Isles", description = "As druids, our charge is to defend nature... and in turn, our home, Azeroth.\n\nConflict breaks out all across the Broken Isles. The Burning Legion pushes forward, and numerous allies call out for our aid.\n\nWe must focus our efforts on defense, before we can mount an offense against the Nightmare.\n\nHelp our allies across the Broken Isles, then return to me when the situation is under control.", objectives = "" }
WordHunterWoW_QuestEN[43404] = { title = "A Gathering for the Grand Master", description = "{name}, err... {class}t,\n\nYour presence is requested for a matter of the greatest importance at the Temple of Five Dawns.\n\nMaster Ponshu and the rest of the Broken Temple are waiting for you!", objectives = "" }
WordHunterWoW_QuestEN[43406] = { title = "Request for the Deathlord", description = "", objectives = "" }
WordHunterWoW_QuestEN[43407] = { title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Soul Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", objectives = "" }
WordHunterWoW_QuestEN[43408] = { title = "Summons for the Arch Druid", description = "", objectives = "" }
WordHunterWoW_QuestEN[43409] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Circle.\n\nWe are inspired by your determination and have developed a new technique that will bind the power of your weapon with the Emerald Dream itself!\n\nEverything is prepared. When you are ready we shall begin.", objectives = "" }
WordHunterWoW_QuestEN[43410] = { title = "The Master is Requested", description = "", objectives = "" }
WordHunterWoW_QuestEN[43411] = { title = "The Master is Requested", description = "", objectives = "" }
WordHunterWoW_QuestEN[43412] = { title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", objectives = "" }
WordHunterWoW_QuestEN[43413] = { title = "A Twist in the Nether", description = "", objectives = "" }
WordHunterWoW_QuestEN[43414] = { title = "A Hero's Weapon", description = "{class}t, our research into the Felblood Altar has proven useful. We've developed a ritual that should unleash the full powers of your artifact weapon!\n\nSay the word, and we shall begin the ritual at once!", objectives = "" }
WordHunterWoW_QuestEN[43415] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much for our order.\n\nThrough your words and deeds we've been inspired to redouble our efforts and I'm proud to report that we've discovered a new technique that may be of use to you.\n\nIf you have a moment, {class}t, I would be pleased to show you the fruit of our research.", objectives = "" }
WordHunterWoW_QuestEN[43417] = { title = "The Spirits Call", description = "", objectives = "" }
WordHunterWoW_QuestEN[43418] = { title = "A Hero's Weapon", description = "Farseer, since you have joined us you have done much to aid the Earthen Ring.\n\nYour efforts have not gone unnoticed. The spirits have watched all that you have done and are pleased. They also have shown me a technique that will unleash the true power of your weapon!\n\nThe ritual is ready. When you are prepared we can begin.", objectives = "" }
WordHunterWoW_QuestEN[43419] = { title = "The Light Beckons", description = "", objectives = "" }
WordHunterWoW_QuestEN[43420] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Conclave. Now, with the work upon the Altar of Light and Shadow complete, it is time that we aid you. We have discovered a method to awaken the full power of your weapon!\n\nPlease, step before the altar and raise your weapon high.", objectives = "" }
WordHunterWoW_QuestEN[43421] = { title = "The Raven Calls", description = "", objectives = "" }
WordHunterWoW_QuestEN[43422] = { title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the crucible are complete!\n\nWhen you are prepared, we shall use it to unlock the true potential of your weapons!", objectives = "" }
WordHunterWoW_QuestEN[43423] = { title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the Altar of the Eternal Hunt are complete!\n\nWhen you are ready, we shall use it to unlock the full potential of your weapon!", objectives = "" }
WordHunterWoW_QuestEN[43424] = { title = "A Hero's Weapon", description = "{class}t, you've brought together the Silver Hand like no {class}t has done before. You've shown us that with determination and faith in the holy light we can overcome any challenge.\n\nFollowing in your example our workmen have toiled hard to improve the Altar of Ancient Kings, allowing it to unlock the true potential of your weapon.\n\nTheir work is now complete! Step forward when you are ready and we shall begin.", objectives = "" }
WordHunterWoW_QuestEN[43425] = { title = "A Hero's Weapon", description = "I've been watching you, {name}.\n\nTime and again you've led the Valarjar to war with your weapon held high! Time and again the halls of Valhalas have thundered with the cheers of your victory!\n\nNow that the enhancements to the forge have been completed, it is time that your weapon's true potential be unleashed! Meet with me at the forge, hero.", objectives = "" }
WordHunterWoW_QuestEN[43441] = { title = "A Second Weapon", description = "We have strong leads on other ancient weapons that you might choose to pursue, if having one renowned, powerful piece of history in your hands is somehow insufficient.\n\nI'll lay out the options for you. Let me know how you'd like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[43461] = { title = "A Time to Reflect", description = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", objectives = "" }
WordHunterWoW_QuestEN[43462] = { title = "Mother Ozram", description = "The fiendish imps in this region are an incessant pain on our allies defending the camps below.\n\nThey are the spawn of a wicked imp-mother named Mother Ozram, who has been seen on a hill to the south.\n\nDestroy her, and we will end her brood as well.", objectives = "" }
WordHunterWoW_QuestEN[43468] = { title = "Blood for the Wolfe", description = "We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask.\n\nI am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some.\n\nWe should show him the same professional courtesy.", objectives = "" }
WordHunterWoW_QuestEN[43469] = { title = "Where In the World is Mathias?", description = "Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord.\n\nOr rather, a very clever dreadlord has taken his place while he is being held captive somewhere.\n\nIt is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.", objectives = "" }
WordHunterWoW_QuestEN[43470] = { title = "Pruning the Garden", description = "In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole.\n\nOn the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn't you agree, {name}?", objectives = "" }
WordHunterWoW_QuestEN[43471] = { title = "The Historians", description = "{name}, each year I visit Stormwind to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Stormwind Royal Library and we can speak more.", objectives = "" }
WordHunterWoW_QuestEN[43472] = { title = "The Historians", description = "{name}, each year I visit Orgrimmar to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Valley of Spirits and we can speak more.", objectives = "" }
WordHunterWoW_QuestEN[43473] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43474] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43475] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43476] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43477] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43478] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "" }
WordHunterWoW_QuestEN[43479] = { title = "The World is Not Enough", description = "Now that we have pruned the garden, it is time to dig up the rotting tree stump in the middle.\n\nPut another way, we need to make sure to keep the forces of chaos from overwhelming the Broken Isles. Certainly others are helping in this endeavor.\n\nHowever, I am sure the target you select to eliminate will be the wisest from the standpoint of the Uncrowned.", objectives = "" }
WordHunterWoW_QuestEN[43485] = { title = "A Burning Distraction", description = "We're going to need a distraction if we are to rescue Mathias Shaw from where he's being held captive in Felsoul Hold.\n\nA big one.\n\nExplosives placed in a few key locations should do nicely. Noggenfogger is playing nice and has donated some bombs to the cause. He might be trying to smooth over relations due to his earlier extortion.\n\nI can have someone go ahead and mark the best locations. You want to do the honors?", objectives = "" }
WordHunterWoW_QuestEN[43486] = { title = "Cracking the Codex", description = "I have been studying the Codex of Command that you recovered from Faronaar.\n\nIt is important to Balnazzar, but WHY? What does it say? I'm sure we could gain valuable knowledge if we could just crack this code.\n\nI have a friend who might be able to help us: a priestess named Delas Moonfang. She has been studying Eredun, the language of the demons.\n\nTake the sigil to her in Dalaran. Tell her I sent you.", objectives = "" }
WordHunterWoW_QuestEN[43487] = { title = "Assault on Violet Hold: The Fel Lexicon", description = "I have been studying the language of the demons, but it has been difficult to get my hands on written material.\n\nI have heard rumor of a book called the Fel Lexicon, written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much!\n\nI heard that this book might be in the hands of a powerful prisoner inside the Violet Hold.\n\nBring me this book, and my work here will go much faster.", objectives = "" }
WordHunterWoW_QuestEN[43488] = { title = "Blood of Our Enemy", description = "I have seen demonic artifacts before, {name}.\n\nLegion sigils will only reveal themselves in the presence of demon blood.\n\nI sense that time is of the essence. Bring me a large quantity of demon blood, so that I may translate the book as soon as you retrieve it.", objectives = "" }
WordHunterWoW_QuestEN[43489] = { title = "To Felblaze Ingress", description = "I have sobering news, Highlord.\n\nWe have had no word from Chieftain Aponi Brightmane, young Arator, or priestess Delas Moonfang since they departed for Felblaze Ingress.\n\nWe need to know what happened to them.\n\nWe fear the worst.", objectives = "" }
WordHunterWoW_QuestEN[43490] = { title = "Aponi's Trail", description = "<The book is missing several pages. Nearby, you can see signs of a struggle.>\n\n<If you can seek the missing pages on the nearby demons, perhaps you could learn what fate befell your allies.>", objectives = "" }
WordHunterWoW_QuestEN[43491] = { title = "Allies of the Light", description = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.\n\nWe cannot leave them, {name}.", objectives = "" }
WordHunterWoW_QuestEN[43492] = { title = "Champion: Aponi Brightmane", description = "", objectives = "" }
WordHunterWoW_QuestEN[43493] = { title = "Black Rook Hold: Lord Ravencrest", description = "Highlord, news has reached us of a Legion presence at Black Rook Hold.\n\nIt is rumored that the night elf commander, Kur'talos Ravencrest, amasses an enormous army behind the fortress walls.\n\nTake a group of your most powerful allies, Highlord, and investigate these stories. Lord Ravencrest was a formidable general during Azshara's reign, and if the reports are true, then we must know more.", objectives = "" }
WordHunterWoW_QuestEN[43494] = { title = "Silver Hand Knights", description = "Good news, Highlord! We have recruited a paladin trainer named Commander Born.\n\nHe is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services.\n\nGo speak to him, and train a squad of Silver Hand Knights.", objectives = "" }
WordHunterWoW_QuestEN[43496] = { title = "The Power Within", description = "My apologies for the unannounced intrusion, {name}. Do you have a moment?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", objectives = "" }
WordHunterWoW_QuestEN[43499] = { title = "Legion 110 H", description = "", objectives = "" }
WordHunterWoW_QuestEN[43501] = { title = "The Power Within", description = "My apologies for the unannounced intrusion, {name}. Do you have a moment?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", objectives = "" }
WordHunterWoW_QuestEN[43502] = { title = "A Change of Seasons", description = "It is time.\n\nThe arcan'dor is preparing to mature. With a final burst of growth, this gift will be fully realized.\n\nWe must make ready the leyline feed.", objectives = "" }
WordHunterWoW_QuestEN[43503] = { title = "The Power Within", description = "Do you have a moment, Conjurer?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away deep within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", objectives = "" }
WordHunterWoW_QuestEN[43505] = { title = "The Power Within", description = "Do you have a moment, Conjurer?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", objectives = "" }
WordHunterWoW_QuestEN[43506] = { title = "Black Rook Hold: Greater Power", description = "The raw power of the runestones will allow Hymdall to temporarily open a tear into demonic worlds, but it's not enough.\n\nThe Legion hides its presence in far away worlds with dark magic. Bring a greater runestone so that Hymdall can hone in on our enemies across the cosmos.", objectives = "" }
WordHunterWoW_QuestEN[43508] = { title = "The Captive Spymaster", description = "We must move swiftly while the distraction is working. Mathias Shaw is being held in the lower levels of the Halls of the Eclipse directly to the south.\n\nQuickly, {name}, we must go!", objectives = "" }
WordHunterWoW_QuestEN[43514] = { title = "A Vainglorious Past", description = "The Heart's magic is attuned to Azshara's elite through powerful warding spells. If we tried to tap into its power now we would be met only with our own demise.\n\nHowever, there may be a way we can bypass the wards.\n\nPrince Farondis and his court were once a part of Azshara's empire, and still hold on to keepsakes of their sordid past. Among these is sure to be a Vainglorious Draught, said to further bind the queen's followers to her will.\n\nSee if you can convince the court to part with a bottle.", objectives = "" }
WordHunterWoW_QuestEN[43517] = { title = "Darkheart Thicket: Fallen Power", description = "Once we have the proper implements we can use the Heart to infuse great power into your artifact. We need only a source.\n\nDeep within the Darkheart Thicket lies the ancient Oakheart, once a great and mighty protector of Shaladrassil. He has regrettably fallen to the nightmare like so many of his kin.\n\nAs the darkness within him has taken root, an essence of the corruption has manifested. I ask that you recover the essence so that we may draw from its power, and put noble Oakheart to rest.", objectives = "" }
WordHunterWoW_QuestEN[43518] = { title = "Tempering Darkness", description = "I do not doubt Senegos' plan, but I do have some concerns about the Heart's volatility, especially when combined with nightmare energy.\n\nDespite its name, Blood of Sargeras is often used as a tempering agent by master craftsmen. I believe it would work for our ritual as well.\n\nYou should keep an eye out for it during your travels - we'll need a substantial amount to ensure that everything goes smoothly.", objectives = "" }
WordHunterWoW_QuestEN[43519] = { title = "Lucid Strength", description = "We have everything we need, {name}.\n\nOnce you are ready, raise your artifact and channel its energy upon the Heart of Zin-Azshari to safely absorb the power stored within the nightmare essence.\n\nI will use the blood you provided to make sure the ritual stays safely contained.", objectives = "" }
WordHunterWoW_QuestEN[43520] = { title = "The Emerald Nightmare: In Nightmares", description = "We must do what we can to ensure that the Nightmare never again festers within the Emerald Dream.\n\nThe aberration known as Il'gynoth lies at the heart of the corruption - a living, writhing manifestation of the horrors you will encounter at every turn of your journey.\n\nI ask that you ensure its destruction, along with the Nightmare Lord himself... Xavius.\n\nOnce the deeds have been done, bring a small piece of each to me. We can study them to figure out just how the Nightmare grew so quickly.", objectives = "" }
WordHunterWoW_QuestEN[43521] = { title = "The Emerald Nightmare: Essence of Power", description = "Now that we have a better understanding on the Heart's capabilities, it is time we tap into its true potential.\n\nIn the Emerald Nightmare you will find creatures that should not be; monsters that defy all that the Dream stands for.\n\nAll that the green flight itself stands for.\n\nEach of these fiends carry within them corrupted essence, as Oakheart did, but far more potent. Gather all that you can, and we will turn their corruption against them.", objectives = "" }
WordHunterWoW_QuestEN[43522] = { title = "Essential Consumption", description = "As before, {name}, once you are ready raise your artifact and channel its energy upon the Heart of Zin-Azshari and we will unleash the power of the essence you gathered.\n\nDo not worry - we still have enough of the blood you gathered to ensure the ritual remains stable.", objectives = "" }
WordHunterWoW_QuestEN[43523] = { title = "Repaid Debt", description = "The Moon Guard fought against the Legion many years ago, during the War of the Ancients. Their intimate knowledge of our enemies would be invaluable to our cause.\n\nThey have remained in Shal'Aran since you saved Thalrenus and his kin. Shall we pay them a visit and see what they can do?", objectives = "" }
WordHunterWoW_QuestEN[43524] = { title = "Court of Stars: Literary Perfection", description = "Out of all the books, why that one?! Oh, Mother Moon, I am but a trusting fool.\n\nI apologize, you have no idea what I'm going on about.\n\nI lent my first edition copy of \"Wards, Sigils, and the Nightborne Way\" to a dear friend - well, former friend, I should say - just before the betrayal.\n\nAs fate would have it, there is an incantation in that book that I will need for my part of the ritual.\n\nPlease retrieve it if you can, but be careful - it is quite valuable!", objectives = "" }
WordHunterWoW_QuestEN[43525] = { title = "Vault of the Wardens: Borrowing Without Asking", description = "The elusive Wardens run an immense secret prison facility deep underneath the mountains of Azsuna housing all manner of terrible creatures.\n\nPerhaps... 'used to run' is more accurate.\n\nThis presents us with a unique opportunity. The wardens used powerful containment crystals to encase each prisoner in their cell. If any of them still remain intact, we could use one to safely contain the Heart's power.\n\nThey certainly won't be needing them.", objectives = "" }
WordHunterWoW_QuestEN[43526] = { title = "A True Test", description = "Vizuul's runebindings are more potent than I had anticipated. Not a bad thing - more power is certainly welcome - but there's certainly more potential for catastrophe if the spell matrix somehow becomes unstable.\n\nWe should be able to safely contain the fel energy within the containment field using the eon winder you recovered... but keep an eye open just in case.", objectives = "" }
WordHunterWoW_QuestEN[43527] = { title = "Saving the Guard", description = "The Moon Guard were once among the most powerful sorcerers on Azeroth. Most assumed their ranks demolished after the War of the Ancients, but it seems they have managed to survive in their ancient stronghold in Suramar!\n\nI believe they could be valuable allies in our quest if they still oppose the Legion.\n\n{name}, if you can save what remains of the Guard, I will work to convince the Council of Six to lend us additional aid.", objectives = "" }
WordHunterWoW_QuestEN[43528] = { title = "Planning the Assault", description = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself.\n\nWe just need a way inside.\n\nI am working fervently with the rest of the Council of Six to secure an entrance. Once we have, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills.", objectives = "" }
WordHunterWoW_QuestEN[43530] = { title = "The Nighthold: Delusions of Grandeur", description = "Grand Magistrix Elisande and her cohorts have lost their minds - they truly believe that allying themselves with the Legion will end in anything but their own demise!\n\nThey are too far gone to save, I'm afraid, but they still have powerful items that we can use to help us infuse the Heart of Zin-Azshari with their power.\n\nIn your assault on the Nighthold, ensure you recover the mad construct Trilliax's power core, as well as the spellbook of the Grand Magistrix herself.\n\nGood luck.", objectives = "" }
WordHunterWoW_QuestEN[43531] = { title = "The Nighthold: Into the Nighthold", description = "Our work is very nearly complete. Now that the Heart can safely absorb power from fel magic, we need the strongest sources of it that we can get our hands on.\n\nGul'dan has called the nightborne's elite back to the Nighthold to aid him. The storm of fel energy above the palace has seeped into the very fabric of their being, even making its way into the crystallized pieces of the Nightwell that many carry with them.\n\nThose shards are exactly what we need, {name}. Save as many as you can in your assault.", objectives = "" }
WordHunterWoW_QuestEN[43532] = { title = "The Nighthold: Darkness Calls", description = "Before we perform the ritual there is one last thing I must ask of you, {name}.\n\nYou must finally bring Gul'dan to justice.\n\nNo more of his lies, his deceits, or his trickery. None of it can save him now.\n\nTake one of his conjured eyes when you're done. Using his power for good will be a fitting end.", objectives = "" }
WordHunterWoW_QuestEN[43533] = { title = "Balance of Power", description = "At long last, it is time to reap the fruits of your labors.\n\nLothrius tells of a place deep in the former Moonguard Stronghold used to infuse new Guards with immense power. It will be the perfect place to tap into and augment the power of the Nightshards you gathered.\n\nGather your effects and meet me there when you are ready, and we will use the Heart to finally reveal the great power within your artifact.", objectives = "" }
WordHunterWoW_QuestEN[43534] = { title = "Blood of Sargeras", description = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras.\n\nWe will need a plentiful quantity. Bring me whatever you can muster.", objectives = "" }
WordHunterWoW_QuestEN[43535] = { title = "Translation: Danger!", description = "<Delas smears fel blood across the lexicon's pages. Alien sigils blaze forth above the paper. She scribbles them down furiously.>\n\nMy goodness... these are detailed records of the Legion invasion force at Felblaze Ingress. They are planning to open a portal directly to their demon world of Niskara! This is quite serious - we need to alert your allies at once.\n\nIf you are going back to Light's Hope Chapel, could I accompany you? I would like to offer my services.", objectives = "" }
WordHunterWoW_QuestEN[43539] = { title = "Salanar the Horseman", description = "The Four Horsemen will need perfect steeds. This is no simple task.\n\nFor the next step of our campaign, I have organized a mission to the Realm of Shadows.\n\nThe goal of the mission is to find Salanar the Horseman, leader of the Dark Riders, and summon him to Acherus.\n\nThe mission is currently waiting your assignment.", objectives = "" }
WordHunterWoW_QuestEN[43540] = { title = "The Mind of the Enemy", description = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly.\n\nLet us find whatever information we can about their plans.", objectives = "" }
WordHunterWoW_QuestEN[43541] = { title = "United As One", description = "I am glad you returned safely, Highlord. Delas Moonfang has also arrived with representatives of the Conclave.\n\nThe priests have come to discuss Netherlight Temple, their seat of power, hidden deep within the Twisting Nether.\n\nAs you have both discovered, the Legion has been searching for them for quite some time, and now... they have found them.\n\nThe Silver Hand has agreed to hear their words. Would you join them now, Highlord?", objectives = "" }
WordHunterWoW_QuestEN[43558] = { title = "Bindings of the Windlord", description = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own.\n\nReturn to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", objectives = "" }
WordHunterWoW_QuestEN[43560] = { title = "Audience with the Windlord", description = "I have kept my promise. Thunderaan the Windlord awaits.\n\nKnow that if betrayal is in your heart, the Windlord will not be deceived. Be silent, and perhaps your audience shall be a fortunate one.", objectives = "" }
WordHunterWoW_QuestEN[43561] = { title = "I Believe I Can Fly!", description = "Let's not bother explaining how this happened, just know that I have the plan of all plans to escape this... this... <Looks over his hand-crafted outfit, then quickly glances to a pile of droppings nearby.>\n\nThis place stinks! But you can help!\n\nThese feathers here will help craft my escape plan. If you wouldn't mind, I'm sure there's enough for the both of us!", objectives = "" }
WordHunterWoW_QuestEN[43562] = { title = "Giving It All We've Got", description = "The arcan'dor is drawing incredible amounts of energy.\n\nEven with the leyline feed at full capacity, we may not have the power.\n\nLet us first ensure that all potential leyline conduits connecting to Shal'Aran are active.\n\nThen I can attempt to amplify the output and hopefully satisfy this insufferable plant.", objectives = "" }
WordHunterWoW_QuestEN[43563] = { title = "Ephemeral Manastorm Projector", description = "Oculeth's theory is sound. Reckless, but sound.\n\nA small warp-field could trap and excite ambient mana in the conduit, thus creating a manastorm similar to when the arcan'dor fell out of balance.\n\nI can build a device to generate the warp-field, but I need materials.\n\nSpecifically, warp-resistant alloys - such as the armor plating of high-end security constructs in the noble district.\n\nThose constructs are deadly. If anyone owes you a favor, now is the time to call it in.", objectives = "" }
WordHunterWoW_QuestEN[43564] = { title = "Flow Control", description = "If all goes as planned, the manastorm will cause the leyline to flare up, sending a great surge of energy through the arcway.\n\nIn order for the surge to reach Shal'Aran, we must seal off any outlets along the way. If we miss even one, the mission fails - and hundreds of people will be vaporized by the energy blow off.\n\nThalyssra had better be sure about this tree.", objectives = "" }
WordHunterWoW_QuestEN[43565] = { title = "Bring Home the Beacon", description = "The conduit we need is in the Arcway, and security in the Arcway has doubled since your last visit.\n\nOur only reasonable option is to teleport your strike team directly in. \n\nThis is a long-range teleport to a non-anchored destination. In other words, it will be hard.\n\nTake this beacon and survey the commons in Suramar City, then return the beacon to me so I can analyze the results. \n\nThis will help me teleport you as close as possible to the conduit!", objectives = "" }
WordHunterWoW_QuestEN[43566] = { title = "Withered Progress", description = "", objectives = "" }
WordHunterWoW_QuestEN[43567] = { title = "All In", description = "It is time to put our plan into action.\n\nOculeth will send you, Arluin and myself into the Arcway, where we shall trigger a manastorm in the Nightflow Conduit.\n\nValtrois will stay here and prepare Shal'Aran for a massive jolt of arcane power - hopefully enough to satisfy the arcan'dor.\n\n{name}... We have a saying... \"To lead is to stand alone.\" It means only those who bear the weight of leadership can truly appreciate it.\n\nThank you for standing beside me. In truth, I do not feel alone.", objectives = "" }
WordHunterWoW_QuestEN[43568] = { title = "Arcan'dor, Gift of the Ancient Magi", description = "Thousands of years ago, as the Quel'dorei were just beginning to unravel the mysteries of the arcane, a small enclave of druids met with the first of the elven magi.\n\nIn the pale moonlight, they formed an order that would seek to bring the arcane into balance - using nature itself as a vessel. Thus the arcan'dor were created.\n\nMy masters who belonged to this order have long since faded away. Yet their legacy remains.\n\nTheir gift will mend the spirit of the shal'dorei. Let them eat, and be made whole.", objectives = "" }
WordHunterWoW_QuestEN[43569] = { title = "Arluin's Request", description = "I never thought I would need to read this...\n\n<Vanthir hefts a scroll in his hand.>\n\nArluin made... plans... in the event he fell. It is not much, but I would like to honor his last request.\n\n<Vanthir hands you the scroll.>\n\nGo to the location marked on this map. Take this Arcan'dor Fruit and give it to a woman named Arluelle. Arluin was very specific that all rewards for his work be directed to her.\n\nI think he may have known what his sacrifice meant. I was wrong about him.", objectives = "" }
WordHunterWoW_QuestEN[43571] = { title = "Neltharion's Lair: Braid of the Underking", description = "Greetings, Deathlord. Years have passed since we first met, but for me it has been mere days.\n\nThe unholy bond between Horseman and steed must not be taken lightly. Power begets power, Deathlord. Never forget this fact!\n\nI can forge an inseparable bond between rider and steed, but components of great power are required.\n\nThe first item I require is the Braid of the Underking, a dark shamanic adornment passed down for generations.\n\nCurrently, it is possessed by Dargrul the Underking.", objectives = "" }
WordHunterWoW_QuestEN[43572] = { title = "Darkheart Thicket: The Nightmare Lash", description = "The dark steeds of the apocalypse are indomitable creatures of anguish and cruelty. They can never be tamed... only subjugated.\n\nThe next component of power we require is one born of hatred, fashioned within the Emerald Nightmare. It is known as the Nightmare Lash.\n\nThe Nightmare Lash has the power to suffocate all hope... all light... from within a living soul.\n\nThe Shade of Xavius himself carries the lash. Defeat him and bring the lash to me!\n\nI will use it to dominate the steeds of the damned!", objectives = "" }
WordHunterWoW_QuestEN[43573] = { title = "Advancing the War Effort", description = "The quest for the Four Horsemen is of the utmost importance, however we must turn our attention to the warfront.\n\nOur continued success on the field of battle has shaken the Burning Legion and as a result, they have increased the frequency and intensity of their assaults.\n\nWe must meet the increased aggression with continued resistance!\n\nOnly then will we be able to turn our attention back to the Four Horsemen.", objectives = "" }
WordHunterWoW_QuestEN[43574] = { title = "Maw of Souls: Maul of the Dead", description = "All of the necessary components have been gathered together. Soon, the unholy steeds of the damned will trample the armies of the Burning Legion.\n\nHowever, our work is not quite done. One item yet remains beyond our grasp...\n\nLurking within the depths of Helheim, the fallen queen Helya rules over the dead. In her possession is a maul, infused with the souls of countless fallen warriors.\n\nBring to me the Maul of the Dead and with it, I will forge barding so impenetrable... no demon shall break it!", objectives = "" }
WordHunterWoW_QuestEN[43576] = { title = "Regroup at the Refuge", description = "I cannot think clearly in this place.\n\nEven though the moonwell is still pure, the corrupting influence of the Nightmare remains.\n\nCome, we will return to the refuge and gather our wits. Then we will continue the hunt for my husband.", objectives = "" }
WordHunterWoW_QuestEN[43577] = { title = "Capturing the Gateway", description = "The time has come to make our move against the Legion.\n\nThe Legion has multiple portals across the Broken Isles.\n\nShould your armies succeed in securing one while it's still active, Hymdall can use the runestones you gathered to direct it to whatever hellish world Hodir is trapped in.", objectives = "" }
WordHunterWoW_QuestEN[43581] = { title = "The Wisdom of Patience", description = "The horrors you braved in the thicket are only the beginning. Within the Emerald Nightmare you will face the very heart of the corruption that threatens the stability of all life on Azeroth.\n\nBut not just yet.\n\nWe have not yet managed to permeate the magic protecting Xavius' sinister realm. Once we have, however, you should return here; there is still much to be done.", objectives = "" }
WordHunterWoW_QuestEN[43582] = { title = "Shalassic Park", description = "We have a Devilsaur.\n\nI think she sees you as the pack leader now. She should obey your commands.\n\nShe looks hungry. Why don't you let her off the leash a little bit?", objectives = "" }
WordHunterWoW_QuestEN[43585] = { title = "Preparing For War", description = "We would do well to bolster our own forces before calling upon our allies to join us in the final conflict against the Legion.\n\nThere still remains much to do in the Broken Isles and victories there will give us the momentum we need to crush the enemy.", objectives = "" }
WordHunterWoW_QuestEN[43586] = { title = "Maw of Souls: Message to Helya", description = "We cannot fight on two fronts and succeed.\n\nIf we're to give ourselves the room we need to fight off the Legion we need to deliver a decisive victory against Helya. Not her armies, not her lieutenants, but the mother of the underworld herself.\n\nGo to the Maw of Souls and defeat Helya, {name}.", objectives = "" }
WordHunterWoW_QuestEN[43587] = { title = "Leyline Feed: Elor'shan", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "" }
WordHunterWoW_QuestEN[43588] = { title = "Leyline Feed: Kel'balor", description = "<This feed appears to draw power from the leyline in order to become fully operational.\n\nYou should be able to imbue it with mana, but it will take a few minutes to draw enough leyline energy to accept the infusion.\n\nBeware, for creatures may notice the surge of arcane energy...>", objectives = "" }
WordHunterWoW_QuestEN[43590] = { title = "Leyline Feed: Ley Station Moonfall", description = "<This leyline feed appears to be damaged. The large collector at the top is broken.\n\nThe broken piece must be around here somewhere. There are rough scuff marks on the floor that appear to be made by something larger than the creatures inside.\n\nMuch, much larger.>", objectives = "" }
WordHunterWoW_QuestEN[43591] = { title = "Leyline Feed: Ley Station Aethenar", description = "<This leyline appears to be damaged and needs repair.\n\nSeveral large chunks of the main column are missing and arcane energy is crackling in the gaps.\n\nThe elementals nearby seem to pick up debris and absorb it into their bodies as they move around. Maybe they have the missing pieces...>", objectives = "" }
WordHunterWoW_QuestEN[43592] = { title = "Leyline Feed: Falanaar Arcway", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "" }
WordHunterWoW_QuestEN[43593] = { title = "Leyline Feed: Falanaar Depths", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "" }
WordHunterWoW_QuestEN[43594] = { title = "Leyline Feed: Halls of the Eclipse", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "" }
WordHunterWoW_QuestEN[43595] = { title = "To Honor the Fallen", description = "Souls are not the only plunder Helya craves, and the kvaldir are ever eager to please.\n\nAmong their spoils are the venerable blades of fallen heroes who dared stand against Helya's minions. These blades belong in a place of honor, not among their wretched kind.\n\nReclaim the blades, for the honor of the Tideskorn!", objectives = "" }
WordHunterWoW_QuestEN[43596] = { title = "Maw of Souls: Piercing the Mists", description = "In a time before memory, the Naglfar was the prize of Helya's fleet. It would seem that it has lived on to serve her once more.\n\nNow, the dread ship sails the sea of souls, and cuts through the mist unseen by the living. The kvaldir must have a way to summon her, and this is what you must seek.\n\nFind her berth and board the Naglfar. Put an end to the dread ship, and the souls of the Tideskorn may be redeemed.", objectives = "" }
WordHunterWoW_QuestEN[43604] = { title = "Maw of Souls: Ymiron's Broken Blade", description = "You hold King Ymiron's blade and realize what a fierce combatant he would make, were he to fight on your side.\n\nPerhaps Odyn could be persuaded to force the vrykul King's spirit to fight alongside your army.", objectives = "" }
WordHunterWoW_QuestEN[43635] = { title = "Needs of the Many", description = "[THIS IS A TEMPORARY QUEST TO GET YOU TO DALARAN IN THE BROKEN ISLES.]\n\nPlease take this portal to Dalaran in the Broken Isles and begin your artifact quest!", objectives = "" }
WordHunterWoW_QuestEN[43643] = { title = "Secrets of the Axes", description = "Battlelord, I have a request. Find me inspiration! An axe whose form has seen a truly astounding amount of battle, wielded by one of the world's most powerful warriors. Both weapon and owner forged together in the crucible of war.\n\nFind this hero and their weapon, and convince them to come here.", objectives = "" }
WordHunterWoW_QuestEN[43644] = { title = "To the Deeps", description = "I assure you the legends are true: Sharas'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing.\n\nWavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj'ir, but we haven't heard from her since.\n\n{name}! Come with me to the ocean depths. Let's track down our missing shaman and get that artifact!", objectives = "" }
WordHunterWoW_QuestEN[43645] = { title = "Wavespeaker's Trail", description = "The shaman we seek is Wavespeaker Adelee. Her research brought her down to these ancient ruins, where she reported naga armies amassing prior to the Legion invasion.\n\nThe last I had heard, she had located Sharas'dal, the Scepter of Tides - and then she went silent.\n\n{name}, Search for clues to her whereabouts among the lower level of the ruins. Beware the naga patrols!", objectives = "" }
WordHunterWoW_QuestEN[43686] = { title = "The Fourth Horseman", description = "The Lich King demands too much! Tirion Fordring deserves more than a life of anguish and undeath!\n\nKnow this, Deathlord... I will obey your will, but there will be no redemption for what we are about to do.\n\nThe Silver Hand will never hand Tirion to us. The path to the Fourth Horseman will be soaked in righteous blood!\n\nBlood that will stain our hands forever.\n\nYour will be done, Deathlord. I will begin the preparations to invade Light's Hope. If this is what it takes to save our world, so be it!", objectives = "" }
WordHunterWoW_QuestEN[43687] = { title = "Walking in Shadows", description = "If we are to infuse the shard's power into the Ashbringer we will need help. We cannot wield such dark magic; however, I know who can...\n\nThe Knights of the Ebon Blade.\n\nI will commission a flight for you to Acherus at once and meet you there - find Aludane Whitecloud in Dalaran when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[43697] = { title = "Warriors of Light", description = "We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.", objectives = "" }
WordHunterWoW_QuestEN[43698] = { title = "Lumenstone", description = "To prepare for the battle ahead, we will need armor and weapons.\n\nWe have learned of lumenstone, a rare metal that can negate magic... even fel magic.\n\nIt is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", objectives = "" }
WordHunterWoW_QuestEN[43699] = { title = "Defenders of the World", description = "Requests are pouring in from across the Broken Isles for our aid, Highlord.\n\nI know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help.\n\nWe cannot turn our backs on those who need our aid.", objectives = "" }
WordHunterWoW_QuestEN[43700] = { title = "A Light in the Darkness", description = "Highlord, thank goodness you've arrived! The invasion of Netherlight Temple has begun.\n\nOur forces are already waiting on the other side of the portal.\n\nJoin them, and we will close the trap around Lord Balnazzar.", objectives = "" }
WordHunterWoW_QuestEN[43701] = { title = "Champion: Lothraxion", description = "", objectives = "" }
WordHunterWoW_QuestEN[43702] = { title = "Softening the Target", description = "The Archdruid's end draws near. His memory will live on in the hearts of all who knew him.\n\nElothir's desperate efforts revealed that Malfurion is being held in Shala'nir, amidst the roots of Shaladrassil.\n\nMy love. So near, yet so far....\n\nShala'nir is infested with Nightmare creatures. To rush in would be suicide.\n\nI subdued one of Xavius' creatures. Use it against him, {name} and clear us a path.", objectives = "" }
WordHunterWoW_QuestEN[43705] = { title = "Nobundo's Last Stand", description = "The Exodar shook from the force of the Legion's arrival. Before we could react, demons were running rampant through the halls, slaughtering everything in their path. If it were not for the Prophet, we would have all perished in the initial assault.\n\nI was charged with evacuating the Crystal Hall, which is when my Broken and I were separated from the main force.\n\nWe fell back into the collapsed hall to make our last stand.\n\nWith your aid, we may survive this invasion.", objectives = "" }
WordHunterWoW_QuestEN[43723] = { title = "Champion: Taoshi", description = "", objectives = "" }
WordHunterWoW_QuestEN[43724] = { title = "Champion: Master Mathias Shaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[43750] = { title = "The Call of Battle", description = "Once, the mighty titanforged keepers of Ulduar and Odyn acted as one. Ever since Odyn broke off to create the valarjar, not even Odyn's own son Thorim is bound to follow his father's advice.\n\nThere is one hope to unite the forces of Skyhold and Ulduar however.\n\nThe Gjallarhorn was a gift given to Hymdall before Odyn's departure. The keepers of Ulduar are oathbound to answer the call of the Gjallarhorn were it to be sounded as it would signal that the end times are upon us!", objectives = "" }
WordHunterWoW_QuestEN[43785] = { title = "Champion: Arator the Redeemer", description = "", objectives = "" }
WordHunterWoW_QuestEN[43797] = { title = "Aiding the Conclave", description = "The priests of the Conclave are formidable allies. With our combined strength, we may just have a chance to slay the dreadlord, forever.\n\nLet Alonsus Faol know that we will be by your side and ready to fight when you need us.", objectives = "" }
WordHunterWoW_QuestEN[43806] = { title = "The Battle for Broken Shore", description = "The third fleet has shipped out ahead of us, {name}. This gryphon will bring you to them.\n\nGood luck out there. It's clear the Legion isn't going to make this easy, but let's hope King Varian has matters well in hand.", objectives = "" }
WordHunterWoW_QuestEN[43808] = { title = "Moon Guard Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "" }
WordHunterWoW_QuestEN[43809] = { title = "Tel'anor'eporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "" }
WordHunterWoW_QuestEN[43810] = { title = "Down to Business", description = "First things first, {name}: we must set up our camp.\n\nWe do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike.\n\nThey are drawing up their battle lines within the city, but could attack us while we are setting up our defenses.\n\nVenture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.", objectives = "" }
WordHunterWoW_QuestEN[43811] = { title = "Lunastre Estate Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "" }
WordHunterWoW_QuestEN[43812] = { title = "Down to Business", description = "Time to get to business, {name}. We cannot afford to tarry.\n\nWhile we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes.\n\nThey are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.", objectives = "" }
WordHunterWoW_QuestEN[43813] = { title = "Sanctum of Order Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "" }
WordHunterWoW_QuestEN[43829] = { title = "Spy vs. Spy", description = "SI:7 is the espionage and intel branch of the Alliance. They are based out of Stormwind City and headed up by Master Mathias Shaw. As of late, they have been acting, shall we say, peculiar.\n\nI would like for you to send some of our people out to assess the situation. It might be nothing, but I am not fond of situations that I do not fully understand.\n\nIf we are going to win this war against the Burning Legion, the last thing we need is for something wholly unexpected to occur.", objectives = "" }
WordHunterWoW_QuestEN[43832] = { title = "Elixirs of Aid", description = "We can never be too prepared for battle. The Legion will strike at any moment, and we must be ready to deal with a multitude of injuries and afflictions.\n\nZabra and Yalia have provided me a list of their most potent potions and battle elixirs than can do everything from restore health to blind the enemy.\n\nWe have an exhaustive list of ingredients that we'll need in order to craft a respectable supply.", objectives = "" }
WordHunterWoW_QuestEN[43841] = { title = "Convincin' Old Yancey", description = "Avast ye! Th' time be long overdue that we get some more pirate blood into our ranks.\n\n<Crackers gives a sudden squawk in agreement.>\n\nAnd I know just th' man t' do it.\n\nI'm talkin' about good old Yancey Grillsen, o' course. He's an old salt down Stranglethorn way.\n\nSend some o' your land lovin' scallywags off t' round him up.", objectives = "" }
WordHunterWoW_QuestEN[43851] = { title = "Recruiting More Troops", description = "Word of your leadership has spread rather fast. Priests of all sorts have traveled to the temple to lend their aid.\n\nWe're lucky enough to have caught the eye of Vicar Eliza. She's quite the leader in her own right, commanding countless devotees that do her bidding without question. \n\nSpeak to her now.", objectives = "" }
WordHunterWoW_QuestEN[43852] = { title = "Fancy Lads and Buccaneers", description = "Aye, it warms me heart t' know that Yancey's now part o' th' crew.\n\n<Tethys feeds Crackers some cackle fruit from the table.>\n\nWhy don't you be a good lad and see if he can sponge us up some bilge rats.", objectives = "" }
WordHunterWoW_QuestEN[43892] = { title = "Sealing Fate: Order Resources", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end?  Will you ever stop risking others lives just to satisfy your greedy nature?\n\nYou can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43893] = { title = "Sealing Fate: Stashed Order Resources", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43894] = { title = "Sealing Fate: Extraneous Order Resources", description = "Four times the cost of the first for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43895] = { title = "Sealing Fate: Gold", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold?  That is the offer I present.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43896] = { title = "Sealing Fate: Piles of Gold", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43897] = { title = "Sealing Fate: Immense Fortune of Gold", description = "Four times the cost of the first, but for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "" }
WordHunterWoW_QuestEN[43898] = { title = "Preparing to Move", description = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion.\n\nThe final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself.\n\nBefore we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.", objectives = "" }
WordHunterWoW_QuestEN[43899] = { title = "Steeds of the Damned", description = "Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen.\n\nSalanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items.\n\nUse the mission table to assign your chosen champions to the task.", objectives = "" }
WordHunterWoW_QuestEN[43926] = { title = "Legion: The Legion Returns", description = "Warriors of da Horde! Break out ya axes and sharpen ya spears. Da Burning Legion has returned ta our world!\n\nWe be shipping outta Bladefist Bay right away. With da full fury of da Horde, we gonna smash der line so hard dat Sargeras is gonna feel it in da Nether!\n\nGet to da ships. We got demons ta slay!", objectives = "" }
WordHunterWoW_QuestEN[43928] = { title = "Aggregates of Anguish", description = "Our preparations for conjuring the Steeds of the Damned are nearly complete.\n\nSalanar the Horseman has given us a list of the remaining components. The ritual of conjuring requires five unholy essences known as the Aggregates of Anguish.\n\nI have taken it upon myself to organize the necessary missions to obtain these components.\n\nUse the mission table to assign your chosen champions to the task.", objectives = "" }
WordHunterWoW_QuestEN[43929] = { title = "Vantus Mastery", description = "", objectives = "" }
WordHunterWoW_QuestEN[43933] = { title = "Champion: Delas Moonfang", description = "", objectives = "" }
WordHunterWoW_QuestEN[43934] = { title = "A New Path", description = "Highlord {name}, if I could have a moment of your time?\n\nLong have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more.\n\nWhen I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me.\n\nI wish to become a paladin of the Silver Hand. Will you allow me to join you?", objectives = "" }
WordHunterWoW_QuestEN[43935] = { title = "A Second Legend", description = "Perhaps it's time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested.\n\nLet me show you what your options are and you can choose one.", objectives = "" }
WordHunterWoW_QuestEN[43937] = { title = "Seeking Refuge", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nIf you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion's nose.", objectives = "" }
WordHunterWoW_QuestEN[43938] = { title = "Focusing Our Efforts", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nAfterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.", objectives = "" }
WordHunterWoW_QuestEN[43942] = { title = "Timeworn Artifact", description = "<You've found a strange looking naga artifact on the fallen corpse.\nYou saw King Mrgl Mrgl as you were walking around Timeworn Strand. Maybe he knows what to do with it?>", objectives = "" }
WordHunterWoW_QuestEN[43945] = { title = "Expanding Your Horizons", description = "You are a fast study, {class}t {name}. The elements speak through you - it is rare to have such a connection to the world.\n\nA true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another?\n\nSpeak with me and let us discuss your options.", objectives = "" }
WordHunterWoW_QuestEN[43949] = { title = "More Weapons of Legend", description = "It is wise to carry more than one weapon to war. Sometimes one will be better suited than another. You should choose another weapon of legend to carry with you, especially against foes so deadly.\n\nWhat say you?", objectives = "" }
WordHunterWoW_QuestEN[43958] = { title = "A Body of Evidence", description = "There is an urgent matter that requires your attention, {name}.\n\nThe body of a woman with a knife in her back has turned up in the sewers.\n\nNormally, such a matter would be less than newsworthy... but this isn't your average cutthroat. It's an SI:7 operative!\n\nI've got some of our goons guarding the body, but you had better get over there before the word spreads.\n\nIf SI:7 finds out about this... it will be bad for business.", objectives = "" }
WordHunterWoW_QuestEN[43962] = { title = "Blades of Destiny", description = "I'm glad that weapon you've been carrying around has proven useful. Our ally, the Lich King, has offered to provide you with a lead on another weapon should the one you already have somehow be lacking.\n\nConsider the options carefully and let me know which you would like to seek out.", objectives = "" }
WordHunterWoW_QuestEN[43969] = { title = "Hired Help", description = "I was fond of Margaux. News of her death weighs heavily on many of us.\n\n<Vanthir shakes his head sadly.>\n\nIf we are to carry on, we need to send a strong message. We need those like Durant to know that we are watching, and we will hold them accountable.\n\nI know someone who could help us.\n\nHis name is Arluin. To call him a reluctant ally would be generously overstating it. He is cautious, and will not risk himself without compensation.\n\nYou can find him in the alleys north of the Evermoon Bazaar.", objectives = "" }
WordHunterWoW_QuestEN[43973] = { title = "Two Paths, Two Weapons", description = "We've searched through our scrolls and have found new leads on a couple of powerful weapons. They may prove beneficial in our efforts.\n\nHere, let me show you what I've found. If any of these interest you then simply let me know.", objectives = "" }
WordHunterWoW_QuestEN[43975] = { title = "Recruiting Shieldmaidens", description = "The powerful val'kyr Savyn Valorborn has arrived to aid us in bolstering our numbers. She ushers some of the most valorous vrykul shieldmaidens into the Halls of Valor.\n\nSpeak to her and recruit powerful troops to add to our roster.", objectives = "" }
WordHunterWoW_QuestEN[43980] = { title = "Another Weapon of Old", description = "You have done well but our foes are powerful and cunning. It would be wise to be prepared for whatever they may unleash upon us. \n\nYou would be wise to consider obtaining another of the weapons of old to aid in our conflict.\n\nLet me know how you'd like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[43984] = { title = "The Tome Opens Again", description = "You've been doing well, friend, but you would be unstoppable if you had another weapon at your side.\n\nHere, let me show you what options remain in the book. If either of these interest you then simply let me know.", objectives = "" }
WordHunterWoW_QuestEN[43991] = { title = "The Protectors", description = "To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity.\n\nTo find these essences, we must consult the protectors of the forest.\n\nGo to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.", objectives = "" }
WordHunterWoW_QuestEN[44004] = { title = "Bringer of the Light", description = "Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear.\n\nWe must hurry, {name}. We must uncover the object's sacred purpose.\n\nThe prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen.\n\nI will open a portal for you now. Take my beacon and use it when you are ready to return.", objectives = "" }
WordHunterWoW_QuestEN[44006] = { title = "Your Fullest Potential", description = "I see that you walk many paths, as a true shaman should.\n\nTwo mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle.\n\nSpeak with me, and together we will unlock your fullest potential.", objectives = "" }
WordHunterWoW_QuestEN[44009] = { title = "A Falling Star", description = "{class}t {name}, thank you for coming. I have a matter of some urgency that requires your unique talents.\n\nThe Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having \"cut a swath\" through the Felstorm itself.\n\nWill you investigate? There is a gryphon awaiting your arrival at Krasus' Landing.", objectives = "" }
WordHunterWoW_QuestEN[44034] = { title = "Another Worthy Blade", description = "We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work.\n\nI would be happy to go over the remaining options with you so that you may make an informed decision.", objectives = "" }
WordHunterWoW_QuestEN[44040] = { title = "Vote of Confidence", description = "I will endeavor to protect my son until the votes are cast.\n\nCoryn Stelleris is a predator even among the nobility. It does not surprise me that he should stoop to such depths to ensure his own success.\n\nTell Ly'leth that she has my support. Unequivocally.\n\nYou may also choose to tell her that Coryn Stelleris will hurt her, if she gives him a chance.\n\nBe careful.", objectives = "" }
WordHunterWoW_QuestEN[44041] = { title = "The Bloody Truth", description = "We need to find out who is behind the assassination of Amber Kearnen.\n\nIt won't be long before SI:7 realizes that their agent is MIA and comes sniffing around The Hall of Shadows.\n\nHere, take these stylish spy glasses and set them to scan for traces of hemoglobin. I've taken the liberty of calibrating them specifically for Amber Kearnen's blood.\n\nFollow the blood trail back to the culprits, but make sure to stay out of sight!\n\nReport back to us when you've got the information we need.", objectives = "" }
WordHunterWoW_QuestEN[44043] = { title = "Continuing the Legend", description = "There are still two paths you may walk - two powerful weapons you might yet obtain to aid you in the fight against the Legion.\n\nI will help you recall your remaining options, of course.", objectives = "" }
WordHunterWoW_QuestEN[44051] = { title = "Wasted Potential", description = "You have done well for us here, but it is time for you to return to Thalyssra.\n\nThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.\n\nOh, and before you go:\n\n<Vanthir hands you a wrapped bottle of Arcwine.>\n\nTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.\n\nWe are grateful beyond measure. Farewell for now.", objectives = "" }
WordHunterWoW_QuestEN[44052] = { title = "And They Will Tremble", description = "There will be consequences for what has transpired this day.\n\nFor now, you should return to Thalyssra. Tell her that we have avenged Margaux and that the Dusk Lily has announced itself to all of Suramar.\n\nThere will be many more deaths before this is over, rest assured, but this is a death that will teach others like Durant to tread more carefully in the future.", objectives = "" }
WordHunterWoW_QuestEN[44053] = { title = "Friends With Benefits", description = "The Lunastre Attendant, silent as ever, offers you a wax-sealed scroll.\n\nIt reads:\n\"Dearest {name},\n\nI asked my attendant to catch you, should things go in my favor.\n\nThe role of Advisor will keep me away from the estate for some time and I settled on a gift for Thalyssra.\n\nI have sent a detachment of attendants to Shal'Aran with some comfort items. Treat them well- they need someone to wait on and I could think of none better!\n\nGive the others my thanks, and my love,\nAdvisor Ly'leth Lunastre\"", objectives = "" }
WordHunterWoW_QuestEN[44055] = { title = "They Have A Pitlord", description = "The Feltotem are not the first to embrace the temptations of the Burning Legion. And they will not be the last.\n\nBut in their arrogance, they have conjured a pit lord.\n\nWill you join us in battle against this beast? The power of your artifact and skill could prove invaluable against such a creature.", objectives = "" }
WordHunterWoW_QuestEN[44057] = { title = "A \"Noble\" Event", description = "The invitation appears to be for an exclusive fox hunt. They plan to hunt Volpin, a rare, elusive fox somewhere in the Broken Isles.  Perhaps we can take advantage of this?\n\nWe need to gather more information about this hunt, but we should do so without alerting the Nightborne to your plans. Your champions can act in your stead and further  investigate where the hunt will be.", objectives = "" }
WordHunterWoW_QuestEN[44058] = { title = "Volpin the Elusive", description = "According to the map, the fox hunt will start at the Feathermane Hunting Grounds in Suramar. If the Nightborne succeed, they will kill Volpin, a fox that is the last of his kind in the Broken Isles.\n\nTravel to the Hunting Grounds, and interrupt the hunt.", objectives = "" }
WordHunterWoW_QuestEN[44063] = { title = "Bolstering Your Arsenal", description = "Highlord, there are still weapons that you might obtain to help you defeat the Legion. We have kept a close eye on them during your time on the Broken Isles.\n\nI would be happy to review them with you if you wish.", objectives = "" }
WordHunterWoW_QuestEN[44074] = { title = "Neltharion's Lair: Essence of Tenacity", description = "Greetings, Archdruid. I hear that you seek the essence of tenacity.\n\nThere is none more unyielding and unbreakable than a creature of stone.\n\nIn Neltharion's Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.", objectives = "" }
WordHunterWoW_QuestEN[44075] = { title = "Halls of Valor: Essence of Ferocity", description = "To find the essence of ferocity, you must seek a creature who has slain thousands, and is revered by even the gods.\n\nI speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.", objectives = "" }
WordHunterWoW_QuestEN[44076] = { title = "Darkheart Thicket: Essence of Regrowth", description = "My child, I can think of only one place to capture the essence of regrowth.\n\nDeep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare's corruption, but deep within his heart, he still fights.\n\nGather the essence of this great tree, so that his everliving soul may be used to fuel new life.", objectives = "" }
WordHunterWoW_QuestEN[44077] = { title = "Eye of Azshara: Essence of Balance", description = "Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist.\n\nSlay it. In its aftermath, you may find the essence of balance that you seek.", objectives = "" }
WordHunterWoW_QuestEN[44082] = { title = "Knights of the Ebon Blade", description = "Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential.\n\nI cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion.\n\nThe demon armies are nearly endless and we are few.\n\nSpeak with Korgaz when you are ready to recruit additional death knights.", objectives = "" }
WordHunterWoW_QuestEN[44083] = { title = "The Grimoire of the First Necrolyte", description = "This ancient tome appears to be the spellbook of Sataiel, the first necrolyte.\n\nWithin its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, \"The Rite of the Executioner.\"\n\nThe site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed.  Perhaps you can pick up where she left off?\n\nFirst, you'll need some skulls.", objectives = "" }
WordHunterWoW_QuestEN[44084] = { title = "Vengeance for Margaux", description = "<Sylverin sputters, pale-faced with rage.>\n\nHow could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her!\n\nSuch injustice cannot stand. We must take vengeance for Margaux.", objectives = "" }
WordHunterWoW_QuestEN[44087] = { title = "Return to the Fel Hammer", description = "{name}, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.\n\nHe requests your presence back on the Fel Hammer as soon as possible.", objectives = "" }
WordHunterWoW_QuestEN[44089] = { title = "A Greater Arsenal", description = "The tome speaks of one more weapon that friend can use against our foes. \n\nDo you wish to seek it?", objectives = "" }
WordHunterWoW_QuestEN[44090] = { title = "Pledge of Loyalty", description = "The eagle appears to have a message for you:\n\nTo: {name}\n\nI hope this message finds you well.\n\nWord of Ohn'ahra's omen has traveled fast. There are many who wish to pledge their loyalty to the Unseen Path's new leader.\n\nReturn to me at Trueshot Lodge, and we can discuss this further.\n\n             -Altar Keeper Biehn", objectives = "" }
WordHunterWoW_QuestEN[44092] = { title = "Protect the Home Front", description = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.\n\nWe must seek them out and stop them, everywhere their darkness touches.\n\nWe've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map.\n\nMake them suffer, {name}!", objectives = "" }
WordHunterWoW_QuestEN[44098] = { title = "Recruiting Apprentices", description = "Grand Conjuror Mimic has arrived to aid us in bolstering our numbers. She seeks out the most promising apprentices and trains them very quickly. Her former students are some of the most powerful conjurors in the land!\n\nSpeak to her and recruit some of her apprentices to add to our roster.", objectives = "" }
WordHunterWoW_QuestEN[44099] = { title = "A Mutual Friend", description = "It's good to see you are well.\n\nI've been sent by our mutual friend, Calydus. He is eager to speak with you.\n\nPlease return to Dreadscar Rift at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[44100] = { title = "Proper Introductions", description = "I'm glad I found you. \n\nI have a message from Alonsus Faol.\n\nHe says introductions are in order, and requests your presence within Netherlight Temple at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[44101] = { title = "Supply Dropped", description = "These supplies for the Earthen Ring have not been processed yet. It looks like someone has been rummaging through them and looting whatever can be carried. You have reasons to suspect the Grimtotem tribe, on account of the fact that one of their champions is nearby, visibly pilfering your stuff.\n\nChallenge the Grimtotem to secure your resources!", objectives = "" }
WordHunterWoW_QuestEN[44106] = { title = "Archdruid of Lore", description = "Elothir resides in the ancient grove Thas'talah, where he communes with nature and instructs his acolytes in the ways of healing and the preservation of lore.\n\nSeek him out and tell him that he is desperately needed here.", objectives = "" }
WordHunterWoW_QuestEN[44112] = { title = "Trading for Dreams", description = "From the look of you, I take it you're an alchemist, yes?\n\nI'd be willing to trade my services with you for a price that I deem is fair.\n\nI have been away from Suramar for some time now. I long for an Ysera's Dream Draught. To concoct it, you'll need some dreamleaf as well as the leaves of a Dreamer's Tear.\n\nOne grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I'll do as you ask.", objectives = "" }
WordHunterWoW_QuestEN[44116] = { title = "Mystery at Citrine Bay", description = "The Burning Legion invades Azeroth, and SI:7 is wasting valuable resources hunting down and assassinating one of their top agents?\n\nSomething isn't adding up...\n\nWe need to find out how deep this goes. Why was Amber Kearnen being hunted by her own organization?\n\nThe encrypted letter she was carrying may hold the clues... but we need more information.\n\nThe SI:7 assassins you tailed in Dalaran mentioned Citrine Bay... search Citrine Bay for clues and we'll see about getting this letter decrypted.", objectives = "" }
WordHunterWoW_QuestEN[44117] = { title = "Time Flies When Yer Havin' Rum!", description = "Thar be few pirates ye want to cross swords wit' less than th' Red Blade! They be salty dogs, indeed!\n\nThat being said... they does have a way wit' rum! I'll level wit' ye, {name}... thar be few rums as jolly as that 'o th' Red Blade.\n\nSeein' as ye be headin' off in search 'o clues, ye might as well brin' back a few bottles while ye be at it!\n\nBrin' me back as many bottles as ye can find, and I'll reward ye handsomely! Pirates honor, {name}!", objectives = "" }
WordHunterWoW_QuestEN[44120] = { title = "Illidari Allies", description = "At first I was unsure whether it was wise to allow the Illidari inside the city. But they may have just saved all our lives.\n\nI gave the demon hunters leave to establish a temporary camp in the Mage Quarter. I'd like you to be my personal envoy to them. Thank the Illidari for their assistance and see how they can aid our cause.\n\nJust... keep your eyes open. They have harnessed a terrible power, and we must be ready should they be consumed by the darkness within.", objectives = "" }
WordHunterWoW_QuestEN[44137] = { title = "Into the Fray", description = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.\n\nCome, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", objectives = "" }
WordHunterWoW_QuestEN[44140] = { title = "From Within", description = "Our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "" }
WordHunterWoW_QuestEN[44152] = { title = "A Growing Crisis", description = "The Arcan'dor is failing.\n\nThis energy was once bound in its boughs and fueled its growth. There was balance, between life and arcane.\n\nNow that energy is breaking free. When the heart can no longer hold it, this tree will kill every living thing in this hall.\n\nI have seen this happen before and I must find a way to stop it from happening again. \n\nWe must go to the tree that came before. Its bones can guide us.\n\nMeet me at the temple of Fal'adora. We will descend together.", objectives = "" }
WordHunterWoW_QuestEN[44153] = { title = "Light's Charge", description = "\"You did not ask for this burden, but it is what fate has deemed.\" Turalyon's haunting last words still echo in my mind. I worry about the fate of the draenei... about the fate of my friend, Velen; but we must remain vigilant, {name}!\n\nFor now, Light's Heart remains under your watchful eye. There is one place on Azeroth that I would trust with the safekeeping of the object: your order hall. Take it there, {name}. I will remain in Dalaran and continue looking for answers. There must be another way!", objectives = "" }
WordHunterWoW_QuestEN[44154] = { title = "The Rite of the Executioner", description = "The skulls have been gathered and the ritual area is prepared.\n\nAll that is left is to perform the incantation, and Ulthalesh will become imbued with the essence of the Executioner.", objectives = "" }
WordHunterWoW_QuestEN[44155] = { title = "Searching For Clues", description = "It be no coincidence that we be in Citrine Bay investigatin' a murder, and we find th' band 'o pirates known as th' Red Blade here as well!\n\nAye, this be no coincidence at all, {name}... but we be needin' proof!\n\nYe go on ahead and look fer clues and I'll find some scallywags to interrogate.\n\nAye {name}, we'll get t' 'th bottom o' this t' be sure! Thar be no doubt!", objectives = "" }
WordHunterWoW_QuestEN[44156] = { title = "Another Arcan'dor Closes...", description = "I hope you have a better understanding of what is at stake.\n\nCome. There is no more for us to do here.\n\nMeet me in Shal'aran and we will discuss what steps we may take next.", objectives = "" }
WordHunterWoW_QuestEN[44159] = { title = "A Ticket for Marin", description = "This Vault Ticket should be delivered to Marin Noggenfogger.", objectives = "" }
WordHunterWoW_QuestEN[44161] = { title = "Things Gaardoun Needs", description = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that.\n\nTime to put your new champions to the test. I'm sure it will be a grueling mission.", objectives = "" }
WordHunterWoW_QuestEN[44176] = { title = "The Conveniences of Home", description = "This chest could prove very useful to our efforts. Take the chest back to Shal'aran.", objectives = "" }
WordHunterWoW_QuestEN[44177] = { title = "Dark Secrets and Shady Deals", description = "Whatever Amber Kearnen knew, Mathias Shaw didn't want it gettin' out...\n\nAye, this be dirty business indeed, hiring th' Red Blade at such a price... just to hunt down and kill one of their own!\n\nYe best get back to th' Hall 'o Shadows, and let Lord Ravenholdt know what we found here in Citrine Bay.\n\nWhatever SI:7 be up to, it be goin' deeper than we first imagined...", objectives = "" }
WordHunterWoW_QuestEN[44178] = { title = "A Particularly Potent Potion", description = "I've got a proposition for ya, {name}!\n\nWord has it that Trade Prince Gallywix recently acquired a priceless, one-of-a-kind love potion. There's only one goblin who can replicate it and you're looking at him! Get me that potion and I can make us both richer than kings!\n\nThe pleasure palace is located in Azshara and it has been on high alert since the war started. Gallywix isn't letting anybody in except his personal staff, but I know a girl on the inside!\n\nFind her and she'll get you to the safe!", objectives = "" }
WordHunterWoW_QuestEN[44180] = { title = "Champion: Marin Noggenfogger", description = "", objectives = "" }
WordHunterWoW_QuestEN[44181] = { title = "Champion: Fleet Admiral Tethys", description = "", objectives = "" }
WordHunterWoW_QuestEN[44182] = { title = "City Under Siege", description = "<Khadgar's voice erupts from the elemental once again.>\n\nObtaining information on the Pillars of Creation before the Legion could stop us was a considerable victory. It won't bring back those we lost on the Broken Shore, but I believe it will help us avenge them.\n\nDalaran has become a focal point of the Legion's assault. Your presence here is crucial. If the demons are putting this much effort into attacking the city, it means Dalaran will play a pivotal role in the struggle to save Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[44183] = { title = "Champion: Lord Jorach Ravenholdt", description = "", objectives = "" }
WordHunterWoW_QuestEN[44184] = { title = "In the Blink of an Eye", description = "The Broken Isles is our destination, {name}.\n\nThe spell that will blink Dalaran to its new location is not a simple one. It will take this Council's full energy and attention.\n\nAs Jaina is... absent, Kalecgos of the blue dragonflight has offered us his aid.\n\nThe Legion will make every attempt to stop us, but we will not falter. It is time to begin!", objectives = "" }
WordHunterWoW_QuestEN[44195] = { title = "Workorders for Armaments", description = "I can get you the best deals on some slightly... used... equipment.", objectives = "" }
WordHunterWoW_QuestEN[44196] = { title = "Mathias Visit Not Active 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[44197] = { title = "Mathias Visit Not Active 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[44198] = { title = "Mathias Visit Not Active 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[44199] = { title = "Mathias Visit Not Active 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[44200] = { title = "Mathias Visit Not Active 05", description = "", objectives = "" }
WordHunterWoW_QuestEN[44201] = { title = "Mathias Visit Not Active 06", description = "", objectives = "" }
WordHunterWoW_QuestEN[44202] = { title = "For the Cause", description = "", objectives = "" }
WordHunterWoW_QuestEN[44203] = { title = "For the Cause", description = "", objectives = "" }
WordHunterWoW_QuestEN[44204] = { title = "Seal their Fates", description = "Ever feel like luck just isn't on your side?  Well maybe I can help you with that.  \n\nThere are some interesting items I've come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it.  It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?", objectives = "" }
WordHunterWoW_QuestEN[44205] = { title = "Shape Your Fate", description = "The whims of the spirits can be guided, I have seen it.\n\nThere were whispers of an item, a way to change the path of destiny.  I heard dem, and I went looking.  For many years I listened to those whispers on the wind until one day they showed me the way.  This is what I offer you.  It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power.\n\nWell?  Are you ready?", objectives = "" }
WordHunterWoW_QuestEN[44206] = { title = "The Ascended", description = "These shaman have spent their lives dedicated to the path of Air, Water or Fire.  On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion.\n\nThe ritual of ascension is not to be requested lightly.", objectives = "" }
WordHunterWoW_QuestEN[44207] = { title = "Portal Full of Shiny Things", description = "When I heard the Hall of the Guardian was open again, I said to myself \"Minuette, this is your chance!\" I rushed over here thinking I'd be hurled into the front lines.  Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors.  That would be brilliant!\n\nInstead, they send me over here and say \"Hey, open up some portals so we can throw things through, would you?\" At least I get to charge something for it.", objectives = "" }
WordHunterWoW_QuestEN[44208] = { title = "Fate and Time", description = "For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny.  These books tell of powerful mages who embraced the manipulation of time.  No no, not like Time Warp, they would laugh at us, think us silly amateurs.  No, they were true Chronomancers.\n\nThe only spell we've been able to determine is a conjuration.  It calls forth what they termed  a \"Seal of Fate\".  This allowed them to repeat their actions.  Let us try it out shall we?", objectives = "" }
WordHunterWoW_QuestEN[44211] = { title = "Unseen Armaments", description = "If we gonna win dis war, we need to get these Champions of ours better equipment.  \n\nIt won't be cheap, or easy, but I can get dem for you.", objectives = "" }
WordHunterWoW_QuestEN[44212] = { title = "Unseen Fate", description = "Our path is a winding, twisting road full of peril.  Yet did you know it can be walked many times?  There is an item of great power available to us.  It allows us another opportunity, a second chance.\n\nDo you wish to acquire one?", objectives = "" }
WordHunterWoW_QuestEN[44213] = { title = "You Will Be Prepared!", description = "{name}, your strength and leadership inspires awe in all of us!\n\nThe Illidari are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "" }
WordHunterWoW_QuestEN[44214] = { title = "One More Thing...", description = "Well done, Slayer. You are truly now the leader of the Illidari. But there's one more thing.\n\nMeet me down at the forge.", objectives = "" }
WordHunterWoW_QuestEN[44215] = { title = "One More Thing...", description = "Firstly, allow me to congratulate you. I know of no one more deserving of the title of Shadowblade. But there's one more thing.\n\nMeet me over near the forge.", objectives = "" }
WordHunterWoW_QuestEN[44217] = { title = "Armor Fit For A Deathlord", description = "{name} is strong! {name} is great leader!\n\nEbon Blade want to give you full set of armor to help with the little demon killing. Get stronger, make demons more dead!", objectives = "" }
WordHunterWoW_QuestEN[44218] = { title = "Champion Armaments", description = "This war against the Legion won't be won easily.  We will need armaments and equipment for our Champions.  \n\nGive the order sir, I'll get the word out and have a shipment brought in.", objectives = "" }
WordHunterWoW_QuestEN[44219] = { title = "Fate's Blessing", description = "The Light's blessing is powerful. We use it to mend, to defeat our enemies... we even use it to resurrect our allies. Did you know it can also be used to alter your destiny?  \n\nThe Silver Hand is able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "" }
WordHunterWoW_QuestEN[44221] = { title = "Champion Armaments", description = "A warrior lives and dies by his weapons and armor.  For a price, we can provide you with a shipment for armaments to equip your Champions with.\n\nDo we have a deal?", objectives = "" }
WordHunterWoW_QuestEN[44223] = { title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", objectives = "" }
WordHunterWoW_QuestEN[44226] = { title = "Fate Favors Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "" }
WordHunterWoW_QuestEN[44228] = { title = "Champion Armaments", description = "See Lurr?  He big and strong, but not so smart, not like Murr.  Murr can make Lurr build good things for you, things for your Champions to wear and be smashier.  \n\nFirst, you give Murr something?", objectives = "" }
WordHunterWoW_QuestEN[44229] = { title = "Champion Armaments", description = "We will need armaments and equipment for our Champions.", objectives = "" }
WordHunterWoW_QuestEN[44230] = { title = "The Fates Bless Us", description = "We are able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny.  \n\nShall we procure one for you?", objectives = "" }
WordHunterWoW_QuestEN[44231] = { title = "Champion Armaments", description = "People today see a dead body and they just think its a smelly pile of goo, not me I tell ya. I see it as a little present holding wonderful secrets.  \n\nFor a price, Ill share those secrets with you too.", objectives = "" }
WordHunterWoW_QuestEN[44232] = { title = "The Grove Provides", description = "{name}, your wisdom and leadership inspires awe in all of us!\n\nThe Dreamweavers are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", objectives = "" }
