WordHunterWoW_QuestEN[44257] = { title = "A Falling Star", description = "<Khadgar ponders the information that you brought to him.>\n\nYou say that it cut a swath through the Felstorm and was emanating power enough that your scout could feel it coursing through their body?\n\nSomething that powerful could prove to be a potent weapon against the Burning Legion!\n\nI will inform the other order leaders of your discovery while you investigate the matter further! A gryphon awaits your command at Krasus' Landing! Light guide you.", objectives = "" }
WordHunterWoW_QuestEN[44278] = { title = "Illidari Freedom", description = "<Arduen Soulblade is bleeding from several ghastly wounds. It appears he was left here to die.>\n\nWithin the prison are three of our... <cough>... comrades.\n\nWe were taken by surprise while scouting the area.\n\nI am not long for this world, {name}, but please... you can still save them.", objectives = "" }
WordHunterWoW_QuestEN[44281] = { title = "To Be Prepared", description = "Our allies have made the journey to Orgrimmar to support our war efforts.\n\nStop and visit with them, {name}. Their assistance will secure our victory today.", objectives = "" }
WordHunterWoW_QuestEN[44282] = { title = "Eye of Azshara: The Frozen Soul", description = "Ah, Deathlord. It is good to see you. I happen to have a fascinating task for you, should you be in the mood for adventure.\n\nI recently came across an obscure reference to an ancient amulet that was created by Queen Azshara herself! It is called the Frozen Soul Pendant and it offers tremendous power to those who channel the power of frost.\n\nI have reason to believe that it may be found somewhere within the Eye of Azshara.\n\nRetrieve the pendant for me, and it will prove most useful in my studies.", objectives = "" }
WordHunterWoW_QuestEN[44283] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "" }
WordHunterWoW_QuestEN[44284] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "" }
WordHunterWoW_QuestEN[44285] = { title = "The Emerald Nightmare: Piercing the Veil", description = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", objectives = "" }
WordHunterWoW_QuestEN[44286] = { title = "Vault of the Wardens: A Masterpiece of Flesh", description = "Ah, Deathlord! What a pleasant surprise! It is not often that you visit my workshop of blood and flesh.\n\nActually, I have something quite special to show you. I have been developing a new type of abomination that mixes the flesh of demons with that of humans.\n\nMy first prototype, Rottgut, is nearly complete! However I am still missing some of the more difficult-to-find body items.\n\nThe prisoners in the Vault of the Wardens should make fine donors for the parts I require.", objectives = "" }
WordHunterWoW_QuestEN[44306] = { title = "Blessings of the Order", description = "Though it takes time and resources, we are able to, of course, Bless your champions.  With this Blessing, their success on their adventures will be greatly improved.", objectives = "" }
WordHunterWoW_QuestEN[44310] = { title = "Thrice the Power", description = "We have information on one last artifact you might seek out, should you seek to weave other types of magic.\n\nAll the details are here. Let me know how you'd like to proceed.", objectives = "" }
WordHunterWoW_QuestEN[44337] = { title = "Goddess Watch Over You", description = "I may have found a \"key\" to unlock Light's Heart, {name}.\n\nI was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow.\n\nIf Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart.\n\nIt's a long shot, but we've got nothing left to lose.\n\nMeet me in Dalaran. I will ready the Tears of Elune for you.", objectives = "" }
